/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120312-3","meetingId":"h24-c-budget","date":"2012年3月12日","dateIso":"2012-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後５時１９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"よろしくお願いします。２７９ページの清掃費の収集運搬作業費、それから、２８５ページの商店街活性化事業費の共同装飾灯維持管理補助についてお伺いします。その中で今後さらにごみの減量をしていく必要があると思うんですけれども、区としてのお考えをお聞かせください。","respondent":"太田品川区清掃事務所長","answer":"都合７回の審議をしていただいた中で、昨年の３月に答申が出されてあります。答申、出された項目としては３つあります。１つは、これまでも実施してきてありますけれども、さらに区民の方への普及啓発、これを強力に進めていく必要がある。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった中で、やはりごみの有料化を進めていくということをぜひやっていただきたいなと考えています。その辺の改めて区としての今後のお考えをお聞かせいただきたい。今も聞きましたけれども、もう一度改めて、その有料化について進めていく必要があると思いますけれども、その辺をお願いいたします。","respondent":"太田品川区清掃事務所長","answer":"委員ご指摘のとおり、全国自治体で約６０％が既に導入をされてあります。ただ、東京都については、市部においては２２市町で実施をされてありますが、区部についてはまだ１区も実施をされていないという状況です。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"商店街活性化事業の共同装飾灯維持管理補助についてお伺いします。商店街の店舗数がどこも減ってきているんですけれども、商店街の街路灯の装飾灯の維持管理ができない商店街が若干増えているんじゃないかなと思うんですけれども、そういったところについて、今現状、商店街、区としてどのように把握されているのか、教えてください。","respondent":"米田商業・観光課長","answer":"現状では、緊急経済対策ということで、算定基準を増額してございまして、１００％の補助率になっているところも全体の３８％あるということで、それなりに商店街の装飾灯の維持管理にご支援ができているのではないかと、このように考えているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"それとも、もし区道のほうで装飾灯を管理していただくということになったとしても、今度、街路灯として、街路灯がありますから、装飾灯との関係というのはなかなか難しいのかなと思うんですけれども、その点、もしくは、使えない場合はもう、使えないというか、維持できない場合は引っこ抜いちゃうという手もあるかと思うんですが、それはちょっと。","respondent":"米田商業・観光課長","answer":"該当の商店街から商業・観光課にご相談があった場合は、さまざまな対応、ケースが考えられると思いますので、一つ一つについてご相談に応じてまいりたいと、このように考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"やっぱり今、どうしても、当初は、装飾灯つくった当時は、やはり皆さん、それなりに資金力があったり、維持ができていたという部分はあると思うんですけれども、これからやっぱり加盟している店が減ってくる中で、装飾灯の維持については、やはり先ほども申しましたけれども、防犯上ということからも、ぜひ残していっていただきたいし、その場合、商店街の意向で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鶴委員","kind":"質問・要望","question":"私のほうからは、２５３ページ、自動体外式除細動器管理費と、２５９ページ、母子健康診査費とあわせて、２６１ページ、すくすく赤ちゃん訪問事業についてお尋ねをいたします。","respondent":"小川健康課長","answer":"ＡＥＤのこちらの経費の内容ですが、ホームページにつきましては、現行の区有施設については掲載を既にしていますが、新たに民間の施設におきましても、こちらのホームページに載せていいかということを確認をさせていただいた上で。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鶴委員","kind":"質問・要望","question":"ただ、管理場所なんですけれども、地域活動課で管理されるということなんですけれども、リースであれば、経費的にももう少し拡大ができるのかなと考えますけれども、各地域センターレベルぐらいで管理をしていただいて、より地域の方に借りやすいような環境をつくっていただきたいなと思うんですけれども、その辺のお考えはどうかというところと、あと、現在の区有施設で。","respondent":"小川健康課長","answer":"貸し出しに関するご質問ですが、まずは５台ということで始めさせていただきたいと考えています。こちらの５台につきましても、基本的には地域に一番密着しております地域センターを通じて地域活動課におっしゃっていただいて、貸し出しをするような形をイメージとしています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鶴委員","kind":"確認","question":"もう一度、今の地域センターを通じてというところで、貸してもらうときというのは、どこに行けばいいのか、そこだけ確認。","respondent":"小川健康課長","answer":"基本的には、最寄りの地域センターを通じまして受け渡しをしたいと考えていますが、もちろん当然地域活動課に直接おっしゃっていただいても構いません。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鶴委員","kind":"提案","question":"じゃあ、地域センターでお借りというか、貸していただけるという体制になっていると。それからあと、２４時間で利用可能なところがないということでありましたけれども、これについては、これまでも公明党としても何度も、コンビニだとかをはじめ、２４時間利用できる環境整備の提案をしてきております。これは衛生費という角度でちょっとご見解をお聞かせいただければと思います。","respondent":"小川健康課長、川崎生活安全担当課長","answer":"そうした中で、この施設ではこれだけのこの時間帯がご利用できますよということもあわせて区のホームページにご紹介できるかなというふうに考えてありますので、それから、そうしたご協力をいただいたところには。ＡＥＤを生活安全サポート隊の車両に載せることについてですが、現在のところ、ＡＥＤの携帯用のものというのが、ちょっと大きさもありますので、今、うちの車は軽車両を使っておりますので、ちょっとスペース的なものもありまして。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"ちょっと款を越えていたにもかかわらず、ご答弁いただいてありがとうあります。そんなに巨大なものではないと思うので、引き続き、健康課といろいろ検討していただきたいなと思います。巡回できるというのは非常にメリットかなと思いましたので、提案まで申し上げました。それから、今現在区で実施しているＡＥＤ研修ですね、これはどういったものがあるか、この辺を教えてください。","respondent":"小川健康課長","answer":"現在区の研修としましては、年に２回ほど普通救命講習会ということで研修のほうが中心に実施をしています。場所は消防署を会場にして、各回３０名定員ということで実施をしています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鶴委員","kind":"提案","question":"じゃあ、職員向けということで理解させていただきました。これは提案です。次に移ります。２５９ページ、母子健康診査費とすくすく赤ちゃん訪問事業についてであります。そうしたところのこと、タイミングの問題なのかなとちょっと思いましたけれども、その辺の確認と、それから、既に母子手帳が交付されている方へのカードの配布体制ですね、どういう形で配布していくのか、この辺を教えてください。","respondent":"小川健康課長","answer":"具体的な配布の方法ですが、窓口でご案内をして、配布はできるような形にしていきたいと思いますけれども、ご存じのない方もいらっしゃいますので。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"早めに手を打っていただいて、両保健センターということですかね、それぞれの。ごめんなさい、３保健センターで置いていただくということだと思います。その上で、この間の民生費でもちょっと触れたんですけれども、やっぱり一、二カ月ぐらいの方というのはなかなか外出というのは困難というか、１人で育ててられている方。ご主人が行けるというのはいいのかもしれませんけれども。もう１回いただければ。","respondent":"小川健康課長","answer":"基本的には、窓口での対応というふうに考えてあります。そのためのＰＲ方法としまして、先ほど申し上げました広報しながわ、それから、ホームページ、ツイッター、メールマガジンなどの手法も探ってまいりたいと思います。","voiceIndex":29,"id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"今現在、結構いろんなところでお話を聞くと、道路、公園で、猫がやっぱり息絶えているところを結構見るんだよねという声があるんですが、現在、道路、公園等で息絶えてしまった猫がいると思うんですが、そういった件数、相談件数というか、そういった、何ていうんですか、猫たちどうにかしてくださいという声が品川区にどのくらい入っているのか、わかれば教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"道路なんですが、これは交通事故で亡くなるというのがほとんどでございまして、それはその時々であるというところで、はっきりした件数はないんですけれども、ほとんどが交通事故での死亡だというところです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"それで、結構増えていると私は認識していたので、そんなに増えてはいないのかなというご答弁だったんですけれども、そういった部分でもこういった去勢、不妊手術というのは大切なのかなと思っているんですが、また、ちょっとこれに関連して、今ちょっと現在、ペット数が、犬だと登録しているので、登録でわかると思いますので、ペット数がどのくらい現在いるのかと、また、ここ数年のペット数、犬の増加。","respondent":"工藤生活衛生課長","answer":"猫に関しましては、登録制度等はございませんけれども、やはり犬とともに増加しているというふうに東京都の報告書では記されておりまして、おおむね１０世帯に１世帯ぐらいが飼われているという報告が出ているところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"やっぱり少子高齢化社会にあって、一人暮らしのお年寄りが増えていて、そういった方が結構飼われたりすることが多いのかななんていうふうに思うんですが、そうした中、やっぱりペットというのが家族の一部になってきているかなと考えていますが、そうした中で、例えばペットの息絶えたとき、そうしたとき、品川区としてご相談があった場合、どういった対応をされているのか、教えていただければと思います。","respondent":"太田品川区清掃事務所長","answer":"猫だけに限らず、犬等の動物の死体処理という形で、飼い主等からの依頼を受けた場合に、私どもで有料で引き取りをして、動物霊園といいますか、焼却場へ、民間のところで処理をしていると、こういう状況です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"民間のほうにお願いをして焼却をしていただくということで、この件数とかがわかれば教えていただきたいのと、必ず焼却施設に行くのか。何かほかにあるんだったら、教えていただければと。ないんだったらないで結構です。","respondent":"太田品川区清掃事務所長","answer":"３年ぐらいということであれば、平成２０年度で２７８件、平成２１年度で２５９件、平成２２年度で２９６件と、こういう流れで推移してきてあります。それから、これは民間の焼却施設で処理をし、そこで共通のといいますか、埋めて、弔うという形になっております。","voiceIndex":38,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"品川区のほうで、今はペット霊園が、私が聞いたところだと１件あるということなんですけれども、そこにお願いして、焼却し、やっているのかなという思いなんですが。例えばどこの民間に頼んでいるというのがわかれば、品川区の業者なのか、それとも区外の業者なのか、ちょっと教えていただければと思います。","respondent":"太田品川区清掃事務所長","answer":"多摩地区にあります仏教平和会というところで処理をしています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"品川区にも、今ちょっと言いましたけれども、ペット霊園があるんですが、ペット霊園の区の考え方についてお伺いしたいと思います。例えば、やっぱり周りに、ペット霊園なので、火葬すると、煙が上がったりされるのかなという思いがあるんですが、区のペット霊園の考え方を教えていただければと思います。","respondent":"野呂瀬環境課長","answer":"ペット霊園についてのお尋ねです。先ほど言いました品川区内のペット霊園というのは、南品川に１軒ありまして、これは城南ペット霊園です。真了寺というお寺に附属しているペット霊園です。","voiceIndex":42,"id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"勉強不足で失礼いたしました。それで、今、ペット霊園の焼却施設、それが今、自動車でできる火葬車というのがあるんですが、こういったものに関しては、区で対応というか、自宅に来ていただいて、そこでペットを火葬車で処理するという形が今ペット霊園さんでもやられていると思うんですが、そういったものとかというのは区のほうでどうお考えになっているか、教えていただきたいと思います。","respondent":"工藤生活衛生課長","answer":"ただ、こちらに関しましては、いわゆる届出、あと登録等の規制がございませんので、私ども、正式には把握しておりませんが、いわゆるインターネット等で調べましたところ、品川区のほうでも３件ぐらい、そのような会社があるというふうに把握しています。","voiceIndex":44,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"火葬車、３件あるということなんですけれども、例えば品川区内でやられているわけですけれども、そういったところの把握というか、どういったやり方をされているというのは、多分規制がないので、なかなか指定できないのかなというところなんですが、逆に言うと、こういったものが規制されずにあるというのが少し問題かなと思っておりまして、ほかでちょっと調べたところ、各７０の自治体で。","respondent":"工藤生活衛生課長","answer":"私どもも、やはりそのような法律、その他の動き等を十分に注視してまいりたいと考えています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"すいません、ちょっと時間がないんですが、２６７ページの健康相談事業のぜん息健康教室についてちょっとお伺いしたいんですが、前回決算特別委員会で、五反田のほうにはぜん息教室というのがないというような話だったと思ったんですが、五反田のほうの、アクアマリンとか、そういったプール施設にそういった教室をつくっていただくことはできるのか、できないのか。","respondent":"小川健康課長","answer":"こちらのぜん息健康教室ですが、プールだけではございませんで、水泳のほかにも、声楽を用いた機能訓練ですとか、さまざまなことをしています。新しいところでは、ぜん息健康教室につきましては、荏原平塚学園を会場として考えているところです。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日はまず、２６１ページの母子保健指導事業費のすくすく赤ちゃん訪問事業等、２５５ページの予防接種費の定期予防接種についてお伺いしたいと思います。少なくてもヒブワクチンと小児用肺炎球菌ワクチンとロタウイルスワクチンと、およびワクチンのスケジュールに関して、わかりやすい説明とパンフレットは、これは訪問指導のときに必須のアイテムと考えますが、いかがでしょうか。","respondent":"矢野品川保健センター所長","answer":"そこで、ことしは契約更新時に予防接種の講習会を開く予定にしております。訪問時に配る中に、あんしん子育てガイドというのがございまして、その中に予防接種の予定が入っておりまして、それを用いて現在はお話をしていただくというような形になっております。","voiceIndex":51,"id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に２５５ページの予防接種の定期予防接種のほうについてお伺いします。時間が限られておりますので、今回はポリオとＢＣＧに限ってお伺いします。今現在品川区では、生ポリオワクチンを春と秋に集団接種、ＢＣＧは４カ月健診時に集団接種が行われておりますが、それぞれ平成２２年度と平成２３年度の予防接種の実績と接種人数についてお伺いいたします。","respondent":"伊津野保健予防課長","answer":"ＢＣＧですが、平成２２年度は２,９６３名受けております。ポリオにつきましては２,９６９名対象者がおりまして、接種者が合計で２,９７８名、接種率としては平成２２年度は１００％近い接種率となっております。","voiceIndex":53,"id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２３年はまだ中間総括ということで、今のデータでどうもありがとうございました。今現在、お話ししたような、あとは、ＤＰＴの途中の人が４種に切りかえた場合、途中で打つワクチンがなくなってしまうというような状況も危惧されておりまして、当然このように来年予想される混乱に対して、品川区としては今どのような対策を検討されているのか、その対策に関してちょっとお聞きしたいと思います。","respondent":"伊津野保健予防課長","answer":"ただ、国のほうでも、円滑な接種に向けての検討会を開いておりまして、どういう形で不活化ワクチンに切りかえていくかというのは、今まさに検討しているところでありますので、区としてもその動きを見守って対応していくことしかできないかなと考えております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次にＢＣＧについて、ＢＣＧの接種時期についてお伺いします。そのワクチンのスケジュールの最終に４カ月健診とＢＣＧがちょうど割り込んでくる形で、これから１カ月間ほかの予防接種ができないということで、現場が非常に混乱しております。","respondent":"伊津野保健予防課長","answer":"ＢＣＧは法定で決められておりますので、接種時期を変えることは難しいと思います。個別化のほうも検討していきたいと考えています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは２５７ページの健康診査費、２８３ページの就業支援費にかかわって、若者の健康診断など、若者支援策について伺いたいと思います。私の周りでも、２０代の方のお話を伺っても、非正規雇用や失業状態にある方、また中には正規雇用の方であっても、健康診断を受ける機会がないと訴え、状況が私は一段と深刻になっていると実感するんですけれども、この点についても区の認識を伺いたいと思います。","respondent":"小川健康課長","answer":"区としての若者支援ですが、基本的には、現在保健センターを中心に相談体制を整えておりますので、保健センターのほうで若者に対する健康のケアはしているというふうに認識しています。","voiceIndex":60,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"４０歳からは何らかの特定健診があるわけですが、２０代、３０代、若い世代の健康診断が今行われていないということです。私は、本来であるならば、雇用関係のある企業が健康診断を行う責任があると思っています。若い世代が健康診断を受ける機会を失っている。この状態が私は増えていると思うんですけれども、その実態についてどうお考えなのか、改めて伺いたい。率直にご意見を伺いたいと思います。","respondent":"小川健康課長","answer":"区といたしましても、現行の健康診査の枠組みの中で今後もしっかり実施していきたいと考えています。職場での健診につきましては、労働安全衛生法に基づきまして、雇用主の責務として実施しているものです。","voiceIndex":62,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"機会がある人は職場でと。では、機会のない人はどうしたらよいと考えているのか、そこを伺いたいと思います。伺いたいのは、若い世代で失業者となった場合、健康診断を受けるにはどうしたらよいのか、現状の制度をご説明いただきたいと思います。こうした若い世代の失業者、また、失業状態にある方が健康診断を受けるには現状どういった仕組みがあるのか、伺いたいと思います。","respondent":"小川健康課長","answer":"先ほども申し上げましたが、現在の健診の考え方は、いわゆる生活習慣病予防対策ということで、４０歳以上を想定しているものです。","voiceIndex":64,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"ぐあいが悪くなったら医療にかかるのは当然だと思います。私が言っているのは、だれもが年に１回の健康診断を受ける必要があると思うんですね。２０代にその受ける機会がない人を、一体どう考えていらっしゃるのか。先ほどからリスクの話がありましたが、では、２０代、３０代は受けなくてよいと考えているのか。そこを改めて伺いたいと思います。","respondent":"小川健康課長","answer":"現在若者への健康ケアの考え方ですが、先ほども申し上げましたけれども、保健センターを中心に相談体制を整えているです。","voiceIndex":66,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"保健センターの相談体制をよくわからないので、伺いたいんですけれども、そこで若い人たちは健康診断を受けることができるのか。まあ、内容が特定健診なら、特定健診の中身と同様の健診が受けられるのかどうか、そこを伺いたいと思います。だれもが、どの年代も、年に１回健康診断を受けることができる、それをしっかりと行うべきだと思うんですけれども、改めて伺いたいと思います。","respondent":"小川健康課長","answer":"保健センターでの相談体制ですが、基本的に国保の特定健診と同じような健診を受けられるわけではございませんが、現行の相談体制、もちろん若者だけに限らず、全世代向けの健康相談の体制を整えているです。","voiceIndex":68,"id":"exchange-030"},{"speaker":"中塚委員","kind":"確認","question":"相談では、特定健診と同様のものは受けられないけれども、相談は伺っていると。改めてそこを確認させてください。この状態が正しい状態なのか。何らかの改善、支援が必要だと思いますけれども、いかがでしょうか。こうしたさまざまなＳＯＳを受けとめるためにも、年に１回の健康診断、これがその一翼を担えればいいんじゃないかと、私はそういう思いも持っているんですけれども、あわせていかがでしょうか。","respondent":"小川健康課長、福島荏原保健センター所長","answer":"保健センターでは、ご指摘のとおり、健康相談という形で、健康診査というものは行ってございません。品川区の自殺者自体は、確かに３０代、４０代、５０代の働き盛りの人の自殺者が多いということはここ４年間のデータでもわかっております。","voiceIndex":70,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"相談の窓口で、相手の話をしっかり聞く、不安にこたえていく、それ自体は大切だと思いますよ。そこをしっかりと改善すべきだと思うんですけれども、いかがでしょうか。それと若い人の自殺の問題ですけれども、３年前の内閣府の調査では、あなたは自殺を本気で考えたことがありますかとの問いに対して、２０代、３０代では、あると答えた方が４人に１人だとの答えがありました。いかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"精神的な部分でのご不安等については、先ほどから荏原保健センター所長がお答えしているように、いわゆる精神関係の相談というのがありますし、それからまた自殺の予防という点でいうと、区としましては、いろいろな相談をする場所において。","voiceIndex":73,"id":"exchange-032"},{"speaker":"中塚委員","kind":"提案","question":"非正規雇用の方々、失業状態の方々、また現に失業されている方々、こうした２０代、３０代の世代に政策上も健診を行う意味はないというのは、あまりにもひどい話だと思います。そういう機会がない方々にして、じゃあ、どうしろというのか。改めて伺いたいと思います。そして適切な支援へと結びつけていただきたいと思うんですけれども、このセンターに保健師や心理士の配置を求めますが、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長、小川健康課長","answer":"品川区就業センターは、あくまでも就業支援という形で進めてまいりますので、保健師等の配置は予定してございません。品川区といたしましては、高齢者の医療の確保に関する法律ならびに健康増進法にのっとった形で現在適正に健康診査を実施しておりますので、それを今後もしっかりと実施してまいりたいと考えています。","voiceIndex":75,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ハローワークの中でも、保健師や心理士の方を配置をして、適切な支援へと結びつけていく、また話を伺っている、そういう状態があるわけですね。それを就労だからといって、全く切り離すというのは、実態に即した対応とは思えないんですけれども、改めて設置を求めたいと思います。そして、若い世代の健康診断の実施を強く求めたいと思いますが、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長、小川健康課長","answer":"答えは一緒になりますけれども、品川区就業センターはあくまでも就業支援のための施設ですので、そのようなことが必要な方につきましては、例えば保健所ですとか、そういうところに勧めていきたいと考えています。区独自で若者に対する健康診査を実施するという考えはございません。","voiceIndex":78,"id":"exchange-034"},{"speaker":"渡辺委員","kind":"質問","question":"私は２５７ページ、各種がん検診、２８７ページ、地域交流支援事業助成について伺いたいと思います。その中で、現状という中で、各種という中で、受診率、検診の受診率、今ここに記載されている、予算書で記載されている７つですか、８つ、その中で一番低い検診率、そして、高い率、検診の率ですね、それぞれ教えてください。それと、がん検診の受診率の目標、そしてその時期。","respondent":"小川健康課長","answer":"目標ですが、国、あるいは都に関しましては、５０％という目標を設けて、現在実施していますが、区といたしましても、それにあわせた形で、限りなく近い目標を立てて、毎年実施をしているところではありますが、現況としてはそういったところです。","voiceIndex":82,"id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"今特に低い率という中で、３％台というので、すごく驚きというか、すごい厳しい現実を見た気がします。もちろん全国的な課題ではあると思いますが、品川区に限らず、都市部も含めて、地域の構成、いろいろあるかと思います。それに対する現在の対応の状況、対応策、ここ近々の数年で構いませんので、どんな対応を現在行われているか、教えてください。","respondent":"小川健康課長","answer":"特に女性特有の乳がん検診などにおきましては、検診体制を整えるべく、受診の機関を整えてきたというような経緯もございまして、それに合わせて２０％を超えるという受診率になって、ある程度成果が少しずつ見えてきたという、その途上にあると考えています。","voiceIndex":84,"id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"これは多分今のお答えで、意識の問題、区民の方の意識が、それぞれ関心がないわけではないまでも、すごく、何でしょうか、危機感というか。というのは、普通に情報というのは今満ちあふれている。ただ、この受診率向上について、今後の対応策はどこも本当に決定打もなく、苦しんでいるところという中で、１つ取り組みとして、民間の保険会社との提携という例が幾つか紹介されています。","respondent":"小川健康課長","answer":"民間との提携につきましては、そういった課題もありますが、どういった形でするのが一番いいのかということについて、今後検討してまいりたいと考えています。","voiceIndex":86,"id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、この事業、地域交流支援事業という中で、商店街の考え方の中で１つ伺いたいのが、よく商店街というと、店が並んでいる、線で例えるならば、１本の線になります。それと、この地域交流支援事業の形というのは、結構ほかの区を調べたんですが、あまり該当するようなものを見かけなかったんですが、結構品川のオリジナルであるのかどうか、伺えればと思います。","respondent":"小川健康課長、米田商業・観光課長","answer":"１点目のがん検診受診率アップのための民間企業の活用につきましては、その可能性も含め、どういった形が好ましいのかということを検討してまいりたいと考えています。地域交流支援事業ですが、こちらについては、平成１７年度より実施しておりまして、委員がおっしゃられましたように、商店街のイベントや販売促進事業に地域ボランティア、また、豊富な経験を有する商店街ＯＢの地域サポーターを派遣し。","voiceIndex":88,"id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その点の評価は、実は私も、他区を含めて、おもしろいことをやっているねというのをよく聞いたものですから、ぜひとも明確に、品川区に特化したですね、品川区の唯一先進的な政策だというアピールも、唯一ではないけど、品川区の先進的な取り組みというお触れがあってもいいのかなと思いました。あるいは、需要や要望は、その裏にはもっとあるのかどうかで、どのように把握されているのか、教えてください。","respondent":"米田商業・観光課長","answer":"現在のところ、ある程度、この数字で充足しているというようなお声も聞かれておりますので、またその辺につきましては、関係団体等と話し合いを進めていきながら、検討してまいりたいと、このように考えてあります。","voiceIndex":91,"id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう意味で、もうちょっと、逆に、制度に対して要望を待つのも１つですが、ちょっと触れてあげることでいろんな波及効果が、大きなコストがかからずにできる仕組みかと思いますので、いろいろな用途もこれからぜひご検討いただければと思って、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこで、平成２４年度の予算、商店街の宅配サービス関連の、今まで私が述べたことに関しての事業として何か予定をされていることがあるかということを１点お聞きしたいのと、あと、中延スキップロード商店街にかつてＮＰＯが主催というか、運営するというんですかね、こういった宅配みたいなことをやっていたというふうに聞いているんですけれども、残念ながら２年ほど前に撤退というか。","respondent":"米田商業・観光課長","answer":"そういう他の事例等も参考にしながら、平成２４年度ですけれども、マイスター店等支援事業の中におきまして、いわゆるこれから商店街として取り組んでいくものの中のモデル実施というようなことで、何かしら今年度、去年のアンケート調査を受けて。","voiceIndex":95,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"居酒屋なんかに行きますと、今、本当に注文なんかも、こんなパネルでポッポッと指で押せばできるというようなシステムもでき上がっている中で、高齢者はそういうＩＴなんかには弱いというふうに思っていたりすると、あっという間に使いやすいものが出てきて、そういった大手による囲い込みみたいなものが起こってきてしまう危険性があるんじゃないかというふうにも思っているんですが。","respondent":"米田商業・観光課長","answer":"大手の仕組みは大手の仕組みとして、こちらも研究をしながら、商店街ならではの強みというようなことで、いろいろ難しい部分はあると思うんですけれども、今年度、商店街連合会、その他商店街とも意見交換を図りながら。","voiceIndex":97,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"いわゆるすみ分けですかね、大手とまた違うところで、商店街は商店街なりのサービスということでのすみ分けというところをうまくしていきながら、やっていきたいというお話だったと思いますけれども、１つの進め方としてありだと思いますので、しっかりやっていただきたいと思います。そんな中で、ことし、東京都の補助金になるんでしょうか、商店街の活性化支援というものの中で、今まで新・元気出せ！","respondent":"米田商業・観光課長","answer":"これにできればうまく乗れるような形での構築を考えてまいりたいと思いますが、時間との戦いということもあります。東京都のいわゆる募集の仕組み、時期等をまた研究しながら、こちらに乗れるような形での検討を進めてまいりたいと、こう考えてあります。","voiceIndex":99,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして、ちょっとお時間が余りなくなってきたので、商店街と大型店等の連携・協働支援事業についてお伺いをしたいんですが、ことし２００万円の予算が現状ついております。ポイントサービスといったことについて、いわゆるポイントサービス、今主婦層を中心に大変に浸透している、これについて何かしらこの事業の中でかかわるものがあるか、お伺いしたいと思います。","respondent":"米田商業・観光課長","answer":"こちらですが、大型店との連携事業ということで、基本的には大型店の中に区のマイスター店等を中心とした名店がいわゆる大型店の中の一部の敷地を借りまして、そこで販売を行うということで、大型店のいわゆる販売のノウハウと、それから。","voiceIndex":101,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"使ってもらいたいという、なるべく消費してもらいたいという意識をうまく利用するような形で、地域の商店街とお互いにポイント還元するような形での何かしらの協働、こういったものも１つ何か考えると活性化につながっていくのではないかと思いますので、その点、どのようにお考えをお持ちなのか、お聞かせいただきたいと思います。","respondent":"米田商業・観光課長","answer":"商業者のほうは、商業も業態によってある程度ポイントに対する考え方については温度差があるというふうに、いわゆるアンケートの調査からも出ておりますので、その辺のところは今後の研究課題とさせていただければと思ってあります。","voiceIndex":103,"id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"２６３ページの健康塾から質問です。そして、先ほど説明がありましたけれども、平成２３年度、７,５２４万円から大きく本年度は減って、約６,０００万円強減っているわけですけれども、ちょっと説明がよく聞こえなかったんですけれども、もう一度お願いをいたします。","respondent":"小川健康課長","answer":"健康塾ですが、健康塾につきましては、品川区トリム体操連盟に委託しています。こちらの予算が減った理由ですが、もともとございましたふれあい健康塾ならびにしながわ出会いの湯が一般会計から介護保険特別会計に移ったことによる減です。","voiceIndex":106,"id":"exchange-046"},{"speaker":"木村委員","kind":"質問","question":"品川区トリム体操連盟が行っているということですけれども、２２カ所、それで４３教室というのがよくわからないんですよ。４３教室、これは毎週行っているのか、それとも毎月４３回なのか、教室なのか、そこのところがちょっとわかりません。そして、平均年齢が７５.１歳。そして、何と最高齢が９７歳ということで、ちょっと驚きましたけれども、今までで健康にかかわる事故などはあったでしょうか。","respondent":"小川健康課長","answer":"２２カ所、４３教室の内訳ですが、基本的にはシルバーセンターを中心に２２カ所でやってございまして、１カ所、週１回なんですけれども、２コースずつ実施しているものです。","voiceIndex":108,"id":"exchange-047"},{"speaker":"木村委員","kind":"意見","question":"それも事故と言えば事故なんですけれども、まあ、何もないということで安心しました。シルバーセンターや区民集会所を使っての事業ということで、２つのコースがあると言われました。これがＡコースとＢコースとあるそうなんですけれども、ＡとＢとではどこかに違いがあるのかどうか。参加するのに抽選会が行われるほど人気があるのであれば、もっともっとメニューを増やすようなお考えはあるのかどうか。","respondent":"小川健康課長","answer":"ただ、抽選が行われていない地区が満杯かといいますと、そうでもございませんで、地区によってやはり多少の波がありますので、基本的にはこの状態で今後も実施してまいりたいと考えています。","voiceIndex":110,"id":"exchange-048"},{"speaker":"木村委員","kind":"質問","question":"ＡとＢがあるということですけれども、Ａが１万６,８００円、そしてＢが８,４００円とお聞きしました。これもトリム連盟に払うお金のことでしょうけれども、年間どれくらいトリム体操にお金を支払っているのか。そして、この値段がまるっきり半額になっています。これとの差はどうして生じたのか、教えてください。","respondent":"小川健康課長","answer":"Ｂコースは引き続き対象者が変わるだけで、準備等がないという理由のもとにこういった金額の設定になっているものです。トリム体操連盟に年間どのくらいの委託料を支払っているかですが、健康塾につきましては、６５５万２,０００円ほど委託料としてお支払いしているものです。","voiceIndex":112,"id":"exchange-049"},{"speaker":"木村委員","kind":"意見","question":"６５５万円ということでトリム連盟に払っているということです。１コースの参加人数、そして健康体操２２カ所の会員の総数、年々これが増えているのかどうか。例えば、以前月に数回病院に通っていたような高齢者の方々がいた。そして、健康体操に参加することで、親しい友人ができ、毎週楽しみになった等のことで、お年寄りたちの変化のデータを健康課は把握をしているかどうか、お答えください。","respondent":"小川健康課長","answer":"参加者の何か変化等ですが、直接口伝えで聞いているところによりますと、実際に今までつえをついている方がつえが必要なくなったとかというようなお話は伺ってはありますが、システム的にデータとしてきちんと把握をしているというものではなく、実際に対面でお話を伺って。","voiceIndex":114,"id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"大変低いあれなんでしょうけれども、これを毎年、３０名ぐらいの方々が、資格というのか、修了証を受け取るというようなことなんですけれども、これを毎年、１２年もやっているわけですから、３６０名ぐらいということで、この方々の、今現在それだけの数の方がいるんですけれども、この事業に対して、将来的に発展があるのかどうかということで、私としては、打ち切る、もしくは打ち切らなくても。","respondent":"小川健康課長","answer":"こちらにつきましても、トリム体操連盟と共催してございまして、卒後にトリム体操連盟に加入される方が多いと聞いてあります。それなりに成果のある事業と考えていますので、引き続きこのように実施してまいりたいと考えています。","voiceIndex":116,"id":"exchange-051"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、武蔵小山の創業支援センターなんですけれども、武蔵小山と２９１ページの創業支援センター、別個にここに書かれているんですけれども、その理由について教えていただきたいのと、１つ確認は、武蔵小山で起業した方がたしか５０人ぐらいいるということの答弁が前あったと思うんですけれども、その辺の確認をさせてください。","respondent":"工藤生活衛生課長、福島ものづくり・経営支援課長、米田商業・観光課長","answer":"そういった意味では、いわゆる区民の安心・安全を守り続ける重要な役割を担っていると認識しております。融資制度、特に信用保証協会についてご説明します。商店主につきましては、マイスター店を中心とした、これまでやる気のあるという個店につきまして調査を行いまして、そういった中で、先ほど申し上げました。","voiceIndex":120,"id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"ただ、焦げつきの話をすると、ちょっと難しくなっちゃうんですけれども、回収率が１００％というのは、じゃあ、焦げつくのであるならば貸さなければいいじゃないかという話にはイコールならないと思うので、その辺の難しさというのがあると思うんですが、その辺がどうでしょうかということが１点と、もう一つ、これも確認になってしまうんですけれども、いわゆる区の負担は直接ないという考えなんですが。","respondent":"福島ものづくり・経営支援課長","answer":"区の状況でいいますと、こちらの不実行といいますか、融資あっせんしても、信用保証協会が否決しまして、実行できないというケースがあります。平成２２年で６.７％が不実行になっていますし、また今年度につきましても、７.１％が不実行。そのように審査を厳しくしています。","voiceIndex":124,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２５８ページの環境衛生費、２６８ページの環境対策費になるんでしょうか、放射能の対策についてお伺いするのと、２７６ページ、清掃費のがれきの焼却についてお伺いします。区内の計測を継続的に行っていただきたいことと、地表の１メートルだけじゃなくて、地表５センチの数値の公表も求めますが、いかがでしょうか。","respondent":"野呂瀬環境課長、工藤生活衛生課長","answer":"そういうことで、５センチについて、もう一度測るような区の考えは今のところございません。今後とも、国、都道府県レベルでしっかりとした、今、検査体制が、今まで以上に密度を濃くして行われているというふうに認識しております。","voiceIndex":127,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、こういった実態をしっかりとらえて、地域にたくさんまだまだ残っているのが、いろいろまだらになってホットスポットを生むわけですから、ぜひ危機感を持っていただきたいと思います。ぜひ台数を増やして、貸し出しも３月３０日で終わるのではなく、ぜひ延長していただきたいんですが、いかがでしょうか。そして、測定結果を地域センターに表示してほしいという願いが届いています。いかがでしょうか。","respondent":"野呂瀬環境課長、工藤生活衛生課長","answer":"本当にそれはありました。団地につきましても、基準値を下回っているということで、今後も継続的に、お問い合わせいただければ、高い値であったようでお不満であれば、環境課から測りに行きます。今後ともホームページ等で、信頼できるサイト、例えば消費者庁のホームページ等にリンクするなどしまして、そのような啓発を図っていきたいと考えています。","voiceIndex":132,"id":"exchange-055"},{"speaker":"山内委員","kind":"質問","question":"私のほうから、衛生費のところで、花粉について伺います。今、花粉が飛散していますが、何か放射線セシウムが付着した花粉が飛散しているということで、ただ、学識経験者によりますと、これはほとんどというか、ゼロと言っていいほどの体に対する被害はないということ。それから、そういった的確な指示をしっかりと出しているかどうかということを伺います。","respondent":"野呂瀬環境課長","answer":"花粉についての放射線のお問い合わせは、今、環境課には来ておりません。","voiceIndex":136,"id":"exchange-056"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。体に被害はないということをしっかりと周知をしていただきたいなと、これは要望をします。次に、産業経済費のほうから２８１ページの被災者雇用助成、それから、２８５ページの中小企業ＩＴ化推進事業、それから、２８９ページのものづくり活性化事業費の海外進出のあたりをお伺いをします。被災者雇用助成について、これは新規ということでありますけれども、この内容を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの被災者雇用ですけれども、国、ハローワークが行っています同様な事業に対しまして、その２分の１を品川区として補助するというものです。","voiceIndex":138,"id":"exchange-057"},{"speaker":"山内委員","kind":"質問","question":"そういった中で、行政と雇用先との連携というものをどうやってとっているのか。それから、そういった方が、この予算でいくと大体どれぐらいの見込みで相談に来られ、それで就職につなげていけるのかという区の意気込みというものを教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"したがいまして、件数としては、それほど伸びないのではないかというふうに予想しています。ただ、実績としましては、ことしにつきましては、今まで３名の方から実際に雇用があったということで、品川区でも助成をする予定です。","voiceIndex":140,"id":"exchange-058"},{"speaker":"山内委員","kind":"質問","question":"３名の方が雇用をされたということですよね。そういった中で、メンタルケア的な、例えば相談をされたときに、仕事の内容とか、それからパワハラとか、まあ、そういうことはないと思うんですが、そういったときに相談をされたときに、例えば相談先というものが区になるのか、ちょっとわからないんですけれども、そういったときの何か対応とかというものはされているのかなというのを伺います。","respondent":"福島ものづくり・経営支援課長","answer":"それにつきましては、親身になり丁寧に対応しています。","voiceIndex":142,"id":"exchange-059"},{"speaker":"山内委員","kind":"意見","question":"２８５ページの中小企業ＩＴ化推進事業、これ、４８０万円から７５６万円ということで予算増がされています。この内容と、それから、このＩＴ化というのは日進月歩いろいろと技術も向上しているということで、１つパソコン講座を例に挙げますと、平成２２年が４４回、平成２３年が４５回、で、今回は何回になるのかということ。","respondent":"福島ものづくり・経営支援課長","answer":"さらに来年度につきましては、イラストレーターという、チラシを自分でできるようにということで、そういったものも取り組んでいきたいと考えています。","voiceIndex":144,"id":"exchange-060"},{"speaker":"山内委員","kind":"質問","question":"過去にこの事業を経験したというような企業が、また新たにリピーターとしてそういったことをされる、先ほど申し上げたように、技術というものが日進月歩なので、そういった企業というものが結構あるのかどうかということを伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"メニューがたくさんありますので、ワード、エクセル、パワーポイント等々ありますので、あるいはホームページビルダー、そういったものにいろいろなものを持ち込まれるという方も多いと思いますし、また、企業によりましては、複数の人間をこちらに受講させているということで。","voiceIndex":146,"id":"exchange-061"},{"speaker":"山内委員","kind":"質問","question":"ものづくり活性化事業のところに移ります。海外進出のほうも、平成２１年からスタートして３回目ですか、昨年はちょっといろいろタイのほうでああいった水害のこともありますけれども、１１月にメタレックスですか、出展をされる企業もあったということで、そちらに行かれたということであります。そろそろですね、３回やりました。そこら辺を伺います。","respondent":"福島ものづくり・経営支援課長","answer":"平成２３年度で３回目、実施したところです。","voiceIndex":148,"id":"exchange-062"},{"speaker":"山内委員","kind":"質問・要望","question":"そういう要望もあるということ。これが非常にやはりうまく運営がされているということでありまして、今、答弁ありましたけれども、改めて、アジアはタイだけではないというところもあると思うんですけれども、今私が言いました、タイ以外の各国についてをどのように考え、それからビジネスにつなげていけるような、そういった手だてがとれるのか、そのあたりを伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"したがいまして、私どもとしまして、国際化対応推進ということで、さまざまな東南アジアへの取引について支援していきたいというふうには考えてあります。","voiceIndex":150,"id":"exchange-063"},{"speaker":"山内委員","kind":"質問","question":"国際化対応、その専門員という方、これは多分いろんな経験をされてきた方ですよね。ある意味資源ですよね。最後ちょっとお時間ありますので、消費者被害防止啓発についてを伺いたいなと思います。平成２２年で２,４４３件の相談があったということですね。今年度、平成２３年度はどんな推移でいっているのか。なかなかこれが減らないのが現状なのかなと考えていますので、そのあたりを伺いたいなと思います。","respondent":"米田商業・観光課長","answer":"特に高齢者の相談が増加している、あるいは若者の相談が増加しているというような状況にあります。それから、１階の啓発展示室につきましては、消費者団体のほうが適宜使っているというようなことになってあります。","voiceIndex":152,"id":"exchange-064"},{"speaker":"金野委員","kind":"質問","question":"よろしくお願いします。私のほうからは、２５９ページの環境衛生費、アレルギー等居住環境調査、２つ目に、２６３ページの保健所等管理運営費、この２つをお伺いいたします。１つ目のアレルギーの居住環境調査。これはどのような調査が行われているのか、調査の内容と目的をお知らせください。","respondent":"工藤生活衛生課長","answer":"アレルギー等居住環境調査の件につきましてのお尋ねです。こちらの事業は、いわゆる住まいというものは、私ども、健康と快適な生活を支える重要な空間だという認識のもと、住まいに起因する健康障害等のトラブルを防止するための支援を行うというものです。","voiceIndex":155,"id":"exchange-065"},{"speaker":"金野委員","kind":"質問","question":"住まいの快適な空間を、それによっていろいろな症状を起こす方のそういう対処の調査をしてくださっているということで、そうすると、その中の１つになるんでしょうか。余りご相談の件数はないかもしれないんですが、でも、やっぱりこれで悩まれている方やご相談を私も受けたことがありまして、どのような調査で、どういった対応をされているのか、教えてください。","respondent":"工藤生活衛生課長","answer":"場合によりましては、いわゆる原因としましては、住居内で、例えばリフォームとか、いわゆる家具等を買いかえて発症されるとか、いろんなケースがありますので、やはり個々のケースを聞きながら、適切に対応しているです。","voiceIndex":157,"id":"exchange-066"},{"speaker":"金野委員","kind":"質問","question":"とても丁寧に対応してくださっているということがわかりました。でも、測定してくださって、適切に対応してくださるということで、引き続きよろしくお願いしたいと思います。これは以上です。２点目に、保健所等の管理運営費をお伺いいたします。こちらの管理運営費、まず現状なんですけれども、３保健センターに保健師の方は何人ぐらいずついらっしゃるのか、その内訳をまず教えてください。","respondent":"矢野品川保健センター所長","answer":"保健センターの部分ですが、平成２３年４月１日現在の配置状況では、品川保健センターが１２名、大井保健センターが５名、荏原保健センターが１０名です。","voiceIndex":159,"id":"exchange-067"},{"speaker":"金野委員","kind":"質問","question":"例えば精神保健の相談が最も多いと。ものすごい業務が多いんだなというのと同時に、実習生も受け入れていらっしゃるんでしょうかね。実習生、保健師の実習生、実績でいうと、平成２２年度は２８名受け入れられているという、こういった実態で、まずこの実習生、どのような内容で実習をされているのか。あるいは、お１人の保健師で２８名を指導されているのか。その辺の状況を教えてください。","respondent":"矢野品川保健センター所長","answer":"３保健センターで分担いたしまして、大学によって違うんですが、１週間、２週間というような実習期間がございまして、それぞれのセンターで研修担当保健師というのを毎年決めまして、その者が中心として指導しております。","voiceIndex":161,"id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"そういう理解でいいんでしょうか。そうなると、保健師が働きやすい保健所の体制とともに、地域医療ということの観点で、もっと区民の皆さんにできるのではないかなと、こう思うんですけれども、その辺、その業務、実習生を受け入れる業務と保健所の体制というのはどのようにお考えでしょうか。","respondent":"矢野品川保健センター所長","answer":"ただ、保健師というのもなかなかいろんなことをやらなきゃいけないので、力をつけなければいけないというところで、数をきちんと確保していくという努力も大切ですが、やりがいを持って仕事をしていくということで、多少困難があっても。","voiceIndex":163,"id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"その人材育成というところでの、私は思うんですが、育成をしていく環境というのは、やっぱり研修を受けたからとか、あるいは、場を踏んだからということじゃ、もっと専門的にされているんだろうと思うんですけれども、働く環境というところも非常に大事なのかなって思うと、育成とともに環境も整え、そして働きやすい環境がより一層その人の向上をされるのではないかなという、そう思うんですけれども。","respondent":"矢野品川保健センター所長","answer":"なかなか保健師というのは大変技術の要る仕事ですが、育成に関しましても、この厳しい状況の中で、工夫して、しっかりと新人を育成してまいりたいと考えています。","voiceIndex":165,"id":"exchange-070"},{"speaker":"向委員","kind":"質問","question":"よろしくお願いします。２８５ページのほうですが、中小企業のワークライフバランス支援事業、平成２３年度の予算が１,０６０万円余ぐらいで、ことしは６３０万円ということで、４割ぐらいぐっと減っていると思うんですが、このあたりの、どういう理由で予算がこのように随分変わっているのかなというところをまず教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"中小企業ワークライフバランス支援事業の予算減の要因ですけれども、こちらにつきましては、事業所内育児施設整備補助金です。こちらが、実際に、今年度予定していたよりも少なかったということもございましたので、実績に合わせまして減らしたものです。","voiceIndex":168,"id":"exchange-071"},{"speaker":"向委員","kind":"質問","question":"この整備補助金というのは、ワークライフバランスを考える上ではとてもありがたい制度だなと思っているんですけれども、ここまでぐっと減るとなると、スタート時、こういった補助金を始めたときのスタート時のニーズの把握とか、そのあたり、どうだったのかなと思って、どれくらい調査をされていたというか、例えば区内のそういった中小企業の子育て支援に関する課題をヒアリングをして。","respondent":"福島ものづくり・経営支援課長","answer":"大体私どもが日ごろほかの中小企業といろいろ懇談する中で、どういったニーズがあるのか、そういったものを探りながら、大体予想した件数が、平成２３年度につきましては、整備費助成が１００万円の３事業者と予定していたんですけれども、実際はもう少し。","voiceIndex":170,"id":"exchange-072"},{"speaker":"向委員","kind":"質問","question":"例えば最近いろんな事業所とかでも、大きな企業とかだと、事業所内で保育所を設けているような、そういった大規模な保育を行っている企業もあれば、もう少し資金がそれだとかかるので、幾つかの企業で共同で保育所をとか、そういう考えを持って実際やっている企業とかもあると思うんですけれども、こういうベビーシッター経費の助成となると、あくまでも単独の事業所が必要だからという。","respondent":"福島ものづくり・経営支援課長","answer":"特に中小企業に対してどういうふうにできるのかということを調査検討いたしました。いわゆる事業所内保育園をつくるとなりますと、相当整備にもお金もかかりますし、また、都の検査等がありまして、なかなか中小企業については難しいだろうということでした。","voiceIndex":172,"id":"exchange-073"},{"speaker":"向委員","kind":"質問・要望","question":"わかりました。特に中小企業となると、人材の確保、女性の人材が持っているノウハウとかも、とても１つの、何といいますか、アピールにもなりますし、女性人材の流出防止を図る企業のためにも、このあたりは引き続ききちんとしていって、頑張っていただきたいなと思います。なので、そのあたり、ちょっとどういうふうに考えていらっしゃるのか、教えてください。","respondent":"小川健康課長","answer":"先ほども申しましたように、区独自で若者世代への健康診査というアプローチの仕方は考えてございませんが、区には健康センターという施設が２カ所、荏原と品川にあります。そちらは比較的若者にも多く利用されているようなところです。","voiceIndex":174,"id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"２８９ページのものづくり活性化事業費全般で伺っていきますけれども、平成２１年、平成２２年、平成２３年というのは、このものづくりの部分、さまざまな事業をいろいろされてきていて、成果がすごく上がってきていると思います。特に２つに絞って伺いますが、２８９ページのところの、まず、ものづくり地域企業ネットワーク再生支援。","respondent":"福島ものづくり・経営支援課長","answer":"ものづくりの地域企業ネットワーク再生事業ですが、こちらにつきましては、実は年１回商談会をやろうと行っていたんですが、さきの大震災があった関係で、少し早めまして、第１回目の商談会を６月に実施しました。その結果、４７社が参加されまして、商談をしたものです。","voiceIndex":177,"id":"exchange-075"},{"speaker":"渡部委員","kind":"質問・要望","question":"１回目、２回目終わって、何社か奨励賞ですとかの賞をいただいた。でもって、これ自身が今後製品開発から実は販路拡大までを面倒見ていくぞというような触れ込みのあるすごいものなんですが、どのような形で今、１回目、２回目の企業に対して進んでいるのかと、この先どういうふうに継続していきそうなのか、実際販路開拓まで行けそうなのか、あわせて教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"ビジネス創造コンテストですけれども、おととし第１回を行いまして、５０件の応募がございました。平成２３年度につきましては、全部で８５件の応募があるということで、年を重ねるごとに増えているです。","voiceIndex":179,"id":"exchange-076"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひ、ものづくりのほうのホームページも、一発で目につくような、こんなこと品川でやっているんだというような仕組みに変えていただきたいと思うのが１つと、やはり先ほども国際的な競争力をつけるという意味では、品川区、一生懸命頑張っているんですが、やはり昔ありました京浜クラスターですね、品川区、大田区、川崎市、横浜市という、この地域一体となってやっていくことによって。","respondent":"福島ものづくり・経営支援課長","answer":"京浜クラスターにつきましては、産業経済省で行っていた事業なんですけれども、こちら自体は終了していますが、品川区、大田区、川崎市、横浜市、この４地域につきましては、今後も連携を持って国際的に進めていきたいというふうに考えてあります。","voiceIndex":181,"id":"exchange-077"},{"speaker":"吉田委員","kind":"確認","question":"母子歯科衛生事業についてなんですけれども、先ほど平成２４年度は予算を減らした理由を、先ほどユニットの買いかえという、平成２３年度、ユニットの買いかえということをお伺いしたので、それはわかりましたが、ちょっと確認の意味を込めまして、実施回数と年齢を教えてください。そして、この年齢に行う理由を教えてください。","respondent":"矢野品川保健センター所長","answer":"母子歯科衛生事業に関しましては、３歳未満について保健センターで実施しています。歯科衛生相談の実施回数は、平成２２年度では、３保健センターで合計１２１回、月三、四回実施しているという状況です。","voiceIndex":185,"id":"exchange-078"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの場所なんですけれども、北品川にある品川保健センターと大井二丁目にある大井保健センター、そして、荏原二丁目にある荏原保健センターで実施なさっていると思うんですけれども、区民の方々からちょっとお話がありまして、ベビーカーや抱っこで行くのに、遠いし、そして危険もあって、待ち時間も長いというお話がありまして、特に品川保健センターなど、隧道を通らなくてはならない母子の方が。","respondent":"矢野品川保健センター所長","answer":"ただ、３歳未満ですので、泣いてしまったりするということで、なかなか地域の医療機関では、泣いてしまうと、もう少し大きくなってからねとかいうので、やっていただけないようなこともありますので、こちらでも実施しているという状況です。","voiceIndex":187,"id":"exchange-079"},{"speaker":"吉田委員","kind":"質問","question":"それで、今お話お聞きしたんですけれども、希望すればできるというお話なんですが、品川区の小児歯科医は、専門でもないんですけれども、１６３軒、一応小児歯科を受け付けていらっしゃるお医者さんがいらっしゃいまして、そして、歯科衛生士の方もいらっしゃるので、私としては、地域の歯科医院の方が、お子様、これから大きくなる上で、まめに健診を行うということで。","respondent":"矢野品川保健センター所長","answer":"この歯科衛生相談というのは、虫歯を減らすというような目的で、１歳半と３歳半の間に実施しているものですが、こういうものをやっているということで、品川区の３歳の虫歯罹患率というのは２３区で３番目にいいという状況もありますので、これも続けていきたいと考えていますが。","voiceIndex":189,"id":"exchange-080"},{"speaker":"吉田委員","kind":"質問・要望","question":"環境保全事業の中の品川区の、ちょっと先に読ませていただきたいんですけれども、環境計画の中に５つの基本目的というのを発見しまして、かけがえのない地球を大切にするまちである、水やみどりのあふれる自然のあるまち、健康で安全な生活環境のまち、環境に配慮した快適なまち、環境への思いやりを皆で育てるまちという、こういうすばらしい５つの基本目的を拝見させていただきまして。","respondent":"野呂瀬環境課長","answer":"環境計画、これは１０年の計画なんですけれども、それが平成１５年に策定したものが計画期間を終えますので、来年度、新たな環境計画として策定していくというものです。","voiceIndex":191,"id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"じゃあ、これからいろいろまた案を練っていただいて、その環境計画をやっていただけるというお話なんですけれども、この間一般質問のほうで私挙げさせていただいたんですけれども、みんなの党の東京湾内の議員の取り組む地球温暖化対策のブルーカーボンの必要性について、前々から品川区では理解していらっしゃるというお答えをいただきました。","respondent":"野呂瀬環境課長","answer":"ただし、それとは別に、環境教育のほうで、例えば生活用水を、そのまま、食器やフライパンの油汚れはふき取るだとか、生ごみを減らすとか、そういう教育については今後も繰り返して、さまざまなところで周知を図りながら、環境保全に努めていきたいと、こう考えているところです。","voiceIndex":193,"id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"明るい将来の世代に引き継いでいけるようによろしくお願いいたします。最後に、マイスター店等の支援事業についてちょっとお伺いしたいんですけれども、平成２３年度が１,１８６万円、そして平成２４年度が４１０万円という、マイナス７７６万円という数字が出ているんですけれども、ちょっとその理由をお聞かせください。","respondent":"米田商業・観光課長","answer":"来年度につきましては、その調査を踏まえて、マイスター店等の支援事業を行っていこうということで、この分が減っているものです。","voiceIndex":195,"id":"exchange-083"},{"speaker":"吉田委員","kind":"意見","question":"それに、住民による投票者が１万６,９４０人という、この数字で、票としては５万５,６４７票ということ。積極的な参加が見られるんですけれども、これからマイスター店にどういうふうに行政はバックアップして、だから、統一化というのはどういうふうにお考えなのかな。広がってばかりいてはどうかなと思うんですけれども、ちょっとその辺はどういうふうな方向性かお教えください。","respondent":"米田商業・観光課長","answer":"一定のマイスター店の選定が行われましたので、マイスター店２００店を軸とした、今後、そちらがいわゆる商店街の核となって、互いに連携しながら、これから事業を展開していこうということになっておりますので、当面の間は、この２００店を中心として、また。","voiceIndex":197,"id":"exchange-084"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、そこの次に言いたいのは、ちょっとこれは款がまたぐんだけれども、例えば３０１ページの水とみどりの整備事業とか、これはないんだけれども、国道の歩道の中の緑、こういうところの連携とか、あとは、街路樹の維持管理費って、緑の関係が出てくるわけだけれども、ここの３つの部分と、だれが中心になってやっているのかということ。","respondent":"小川健康課長、太田品川区清掃事務所長、藤田水とみどりの課長","answer":"学校利用を中心に、間を縫って区としてもいろいろプログラムの展開を今後も考えてまいりたいと考えています。し尿処理にかかわるご質問にお答えをいたします。品川区でし尿処理をしている世帯は１７戸です。みどりと花のボランティアの関係ですけれども、例えば公園ですとか、道路ですとか、あるいは、地域センターとか。","voiceIndex":200,"id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、なぜあそこでやっている意味があるのかということをもうそろそろ一組で話してほしい。学校の優先というのはもちろん、それを優先にしていただきたいと思います。漏れ伺うところによると、学校の予定が出てくるのはどうしても１月とか、今回は特に土曜のことがあったから遅かったという話は聞きました。みんなよく、皆さんのところに我々も何か言って、こんなに下草伸びてと言うじゃないですか。","respondent":"太田品川区清掃事務所長、小川健康課長、藤田水とみどりの課長","answer":"それ以外にも、今ご指摘いただきました、処理量減少に対応した事業運営を、民間活力を活用して、施設の運営委託、それから、雇上車両についても。委員ご指摘の民間活力を導入して、お子さんから高齢者まで学校の温水プールをさらに活用したらというご提案ですが、そういった趣旨に基づきまして。その辺の中で、区のできることはしっかりやっていきたいと、このように考えているところです。","voiceIndex":204,"id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"提案","question":"別に平成３２年というのはわかりますけれども、それまでにやっぱりそのままでいいのかという、それがあるのはわかりますけれども、やっぱり関係区、そういう施設を持っている関係区とも、これは区長にお願いするしかないかもしれないけれども、やっぱりそこら辺ともう一度話を詰めていただいて、少しでも区民のために、それは区の横暴だと言われればそれまでかもしれませんけれども、ある区としては。","respondent":"久保田行財政改革担当課長、安藤文化スポーツ振興課長、藤田水とみどりの課長","answer":"本格的な活用に向けて、東京都と調整はしていますけれども、なかなか難しい状況もありますので、関係機関等含めまして。先ほど委員ご指摘のとおり、学校にまず予定をお伺いしまして、それから地域の学校の中で、一般開放、また貸し切り。ボランティアを立ち上げる際に、私どもが仲介して、国や東京都につなげたところもありますけれども、直接国や都とやっているところもありますので。","voiceIndex":208,"id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"提案","question":"最後に１つだけお願いしておきます。そう考えると、プールも、もちろん学校があって、その中で使わせていただく、そういう形の中で、もっとこういう形でやれるだろうというのは、私はやっぱり提案なり何なりを受ける体制づくりを区のほうにつくっておくべきだと思いますので、それはぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":212,"id":"exchange-088"},{"speaker":"稲川委員","kind":"質問・要望","question":"２８３ページ、観光アクションプランに関連してお伺いをいたします。今後の区の動きを教えていただきたい。あわせて、私も聞く話であれなんですが、品川浦の船だまりのところのまちづくりというんでしょうか、方向性が今どのようになっているのか。それとあと、羽田空港の国際化、同時に跡地の利用というんですかね、開発も含めて、近隣、大田区をはじめ、臨海副都心において観光誘致が白熱していると。","respondent":"山崎マスタープラン担当課長、米田商業・観光課長","answer":"品川駅の周辺がそのエリアになってございまして、品川浦の、今、まちづくりを考える上で、そうした国際戦略に即したまちづくりの方向性等々を、マスタープランを策定する中におきましても。広域観光まちづくり支援事業費等補助ですけれども、こちらは、品川区と大田区での連携事業ということで、１００万円をその連携の協議会に支出をする予定です。その中で、ホームページの多言語化等を行う予定です。","voiceIndex":214,"id":"exchange-089"},{"speaker":"稲川委員","kind":"質問・要望","question":"それで、品川浦は一部特区構想に含まれているということなんですが、品川区は、ご存じのように、運河が多いので、ほかのところももし追加指定という、そういう手法があるのであれば、ぜひそういうのにも取り組んでいただきたいと要望しておきます。ですから、Ａから乗船して、東京湾を回りながら、また、乗船所に戻ってくるという不定期航路であります。","respondent":"米田商業・観光課長","answer":"ぜひとも品川区のほうへ、これから桟橋等の整備ということも、まちづくり事業部と協力しながら、ぜひとも不定期航路を品川へ導き、またあわせて、品川から発で、大田羽田空港沖、それから、今ありましたディズニーランド、もしくは。","voiceIndex":217,"id":"exchange-090"},{"speaker":"稲川委員","kind":"質問・要望","question":"行く行くはしながわ水族館にウェルカムゲートがつくれるような部分で働きかけをしていっていただきたい。品川区単独では無理だと思いますが、ぜひそこは大田区と連携をとって、大田区の上を行っていただきたいと私は思っております。","respondent":"米田商業・観光課長","answer":"観光協会のほうに舟運の事業者の方も入っております。そういう方々とも連携を十分とりながら、今後進めてまいりたい、このように考えてあります。","voiceIndex":219,"id":"exchange-091"},{"speaker":"浅野委員","kind":"質問","question":"２５７ページ、各種がん検診、２６９ページ、温暖化対策事業、２８１ページ、中小企業センター等運営費、時間があれば、２８１ページ、新製品開発助成について質問します。最初に温暖化対策事業ですけれども、地域推進計画の進捗状況についてお伺いしたいと思います。計画と実績でお願いいたします。","respondent":"野呂瀬環境課長","answer":"品川区の温暖化ガスの排出量推移です。２００６年が約１,９４１万トン、２００７年が２,２３９万トン、２００８年が２,２３８万トン、それぞれの計画に基づいては、１４％、１３％ぐらいのプラスで推移しています。","voiceIndex":222,"id":"exchange-092"},{"speaker":"浅野委員","kind":"質問","question":"２００８年度比で１.６％の減、２０００年度比で８.４％減っていると、このように言っているわけですけれども、この数値、都は２００２年度以降の原子力発電所の長期停止の影響を除くため、電力、ＣＯ２排出係数を２００１年度の低い係数に固定して算出をしたということで、この数字が一番最初に載っているわけですけれども。","respondent":"野呂瀬環境課長","answer":"特に産業とか運輸部門につきましては、それぞれ都の政策で減っているという、これは確認とれておりますので、問題は家庭部門の温室効果ガスをどれぐらい減らすかですので、これは区としましても、しっかりさまざまな啓発を通じまして、温室効果ガスの削減に努めていきたいと。","voiceIndex":224,"id":"exchange-093"},{"speaker":"浅野委員","kind":"質問・要望","question":"ただ、併記をした高いほうの排出係数のほうは、１０という考え方になっていると思いますが、このような手もあるかと思いますが、区民にわかりやすいような形でぜひともこの目標も設定をしていただきたい。平成２４年度、この１年間でそこら辺をしっかりと論議をしながら、明確に決めていっていただければよろしいかなと思いますが、この件についてもご答弁をお願いします。","respondent":"野呂瀬環境課長","answer":"それと、地域推進計画につきましては、これはご案内のとおり、６２区市町村で全体でまとめていくですので、東京都の発表に対して、今後、６２区市町村の中で、いろいろ調整、検討して、発表されるものだと了解しています。","voiceIndex":226,"id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"ぜひともわかりやすいようにしていっていただければと思います。最初は生活協同組合、こちらが早くから実施をしておりまして、昨年は東京電力が参加をするといいましょうか、スタートをしました。そしてもう一つお伺いしますが、今回太陽光発電システム等の助成、対象枠を拡大しております。平成２４年度の目玉事業というのは何かあるのかどうか、お伺いします。","respondent":"野呂瀬環境課長","answer":"それと目玉事業につきましては、やはり省エネ診断につきましては、今回は、いわゆる節電の関係で、いろいろ緊急政策で都のほうも打ち出しているかと思うんですけれども、省エネ診断につきましては、目玉というよりも、今後とも継続して、やはりただのＣＯ２だけじゃなくて。","voiceIndex":228,"id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"温暖化対策事業、地道な取り組みではありますけれども、絶対に必要な事業ですので、引き続きよろしくお願いします。各種がん検診に移ります。胃がんのリスク検診、スタートをさせていただけるということになりました。告知方法ですけれども、どのように考えているのか。受診できる医療機関というのはどのぐらいあるのか。こちらからお伺いします。","respondent":"小川健康課長","answer":"このたび新たに胃がんリスク検診を導入するものですが、こちらの年齢対象者、５０歳から７５歳までの５歳刻みの方に対しましては、直接受診券を送付する予定です。そのように告知をするつもりです。","voiceIndex":230,"id":"exchange-096"},{"speaker":"浅野委員","kind":"質問","question":"今回のハイリスク検診、胃がんのハイリスク検診につきましては、厚生労働省の見解がどこまで出ているか、私も存じ上げないところですけれども、これは胃がんの対象件数には入らないと私は認識しておりますが、もし万一これがカウントできるとなった場合、従来の胃がん検診と合わせましてどのぐらいのパーセントが見込めるものなのか、算出した結果があれば教えてください。","respondent":"小川健康課長","answer":"委員ご指摘のとおり、新たに導入いたします胃がんリスク検診につきましては、国のガイドラインに沿った形の検診ではございませんので、そういった形での厚生労働省の数値ということでカウントできるものではございませんが、仮にカウントした場合、今の区の見解といたしましては。","voiceIndex":232,"id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"何とか国のほうにもこれをカウントしてもらうように声を上げていっていただければと思います。大腸がんについてはそのような質問も前させていただきましたけれども、やはり特定健診も平成２４年度は５４％という、そういう目標を掲げて、かなり積極的に取り組むという方針も出ておりますので、がん検診についても、大きく前進する取り組みをお願いしたいと思いますが、いかがでしょう。","respondent":"小川健康課長","answer":"平成２３年度につきましても、かなり伸びている状況ということで認識しています。","voiceIndex":234,"id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"中小企業センター等運営費に移ります。こちら、大震災で天井が破損して、応急処理を施して、６月の補正で介護福祉専門学校の５階、６階の天井改修、こちらのほう、完璧にやったと、完全に復旧したというふうに伺っております。今回、天井補強等の工事、これを具体的に教えてください。「等」という文字には何が含まれているのか、こちらも教えてください。よろしくお願いします。ご答弁お願いします。","respondent":"米田商業・観光課長","answer":"今回の天井補強等の工事につきましては、私どもの事務所のスペース、２階の商業・観光課、ものづくり・経営支援課のスペース、それから４階のテナントが入っているところ、そちらの天井補強を行わせていただくものです。","voiceIndex":236,"id":"exchange-099"},{"speaker":"高橋委員","kind":"意見","question":"２８３ページのサポしながわと品川区シルバー人材センターです。サポしながわのほうで、求職者の登録数が、平成１９年、平成２０年、平成２１年、平成２２年と３００人、２００人ずつ増えていたんですが、平成２１年から２２年、１,１００人から６８０人というふうに５００人減っているんですが、これは何かの間違いなのか、その辺の事情がわかりましたら、すみません。","respondent":"福島ものづくり・経営支援課長","answer":"こちら、求職者登録数ですけれども、簡単に言いますと、カウントの仕方を変えたというものです。新たに来たものだけを数えるという形にして、合同面接会ですとか、そういうところで来たのはカウントしないという形をとってみました。","voiceIndex":239,"id":"exchange-100"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、ある一定の方々は常に求職をされているという状況で、はい、わかりました。ですから、連絡体制がとれてきたのか。それから、あとさらに、これは款をまたいじゃいますけれども、サポしながわ、シルバー人材センターの立場でお願いしたいんですが、生活福祉課、年金受給者の方々等の就業支援、そちらとの連携といいますか、連携、調整、そういったことはどのようにされていたのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"生活福祉課との連携ですが、直接的には、サポしながわ、あるいはシルバー人材センターとはこれまで余りなかったと思いますけれども、今後、就業センターができますので、そこでは一体となりまして生活支援を行っていく、就業。","voiceIndex":241,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"その課題をやはり解決するというような側面があって、やはり就業センターのほうに今回、平成２４年度新設される、繰り返しというか、そういう形の中で、どのような効果といいますか、今言った連携に関してどのような効果が期待されていくのでしょうか。何か今までの課題がどのように劇的に解決されていくのか、その辺の期待も含めて、お願いしたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"そこでは、１名増強しまして、こちらの就業センターそのものの運営にも携わっていただく予定になってあります。","voiceIndex":243,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"その点においては、今のほうはサポしながわのほうの話だと思うんですが、センターを立ち上げたんですが、人事的な面で、ここのセンターの運営を強化しているという、その意気込みといいますか、人事的な側面での新たな取り組みといいますか、それをご説明いただきたいんですが。","respondent":"福島ものづくり・経営支援課長","answer":"４月１日から品川区としまして就業支援担当主査という１つの係を設置いたします。そのような形で、新たな組織を設置することで、この就業支援、あるいは一体的なさまざまな支援、中小企業に対する支援も含めてですけれども、支援を行っていきたいと考えています。","voiceIndex":245,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問・要望","question":"就業支援担当主査は係長になるのでしょうか。２３区として、就労問題は広域的な問題でもあるので、２３区としてどのような取り組みができていけるのでしょうか。２３区内でも温度差があると伺っています。基礎自治体としてどこまで踏み込んでいくのかということ、それから、２３区として、広域的な就労問題についてどのような取り組みができていくのでしょうか、その点をお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"私たちは、それらと一体となりまして、側面支援等を行っていくというものです。その他、中小企業の雇用支援、そういったものにつきましても、力を入れていきたいと考えています。","voiceIndex":247,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"非常に意気込みを感じさせていただきました。頑張っていただきたいと思います。最後に、中小企業センターの人の流れ、あるいは対流状況が少し変わるのではないかと思います。そのことに関してどのような対応を想定されているのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"確かに、想定では１００人程度増えるのではないかということで、にぎわいも増えるというふうに私どもは考えてあります。ただ、混乱が生じないようにということで、受付の者を１名雇いまして、それによりまして十分流動させていきたいと考えています。","voiceIndex":251,"id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"私からは、産業振興の買物支援の関係でお尋ねしたいと思います。今、区内には１０８の商店街がありますけれども、１０年前と比べると、商店街の数というのは、同じなのか、減っているのか、ちょっとそのあたりを教えていただきたいと思います。それと、生鮮品を扱うお店のない商店街は幾つあるのか、ここについても教えてください。","respondent":"米田商業・観光課長","answer":"平成９年のときは３,８５０ということになっておりますので、商店の数は減っているものと認識をしています。それから、生鮮を扱っていない商店街ということですが、こちらのほうにつきまして、詳細は私どものほうでははっきりしたものはつかんでございません。","voiceIndex":255,"id":"exchange-106"},{"speaker":"南委員","kind":"質問","question":"商店街として伺ったので、まあ、個人の商店数ということでお答えして、減少がされているという、そういうことでした。そして、なくなった背景は何なのかということを、区としての見解を教えてください。","respondent":"米田商業・観光課長","answer":"商店街の数ですが、平成２２年、１０８でしたが、平成１２年のときに１０５という数字になってあります。全体的に商店の数が減ってあります。","voiceIndex":257,"id":"exchange-107"},{"speaker":"南委員","kind":"質問","question":"その辺について、きちんとした支援体制をつくるべきだと思っているんですけれども、１つには、買物というのは、私も以前の質問の中で申し上げてきましたけれども、社交の場、情報交換の場だというふうにね。高齢化社会の中で、高齢者が生鮮食料品をどういう形で手に入れたらいいのかということの検討をぜひするべきだと思っているんですけれども、そこもあわせてお考えを伺いたいと思います。","respondent":"米田商業・観光課長","answer":"この商店街支援の施策を今後も継続するとともに、商業者の方々も、いわゆる地域の方々の利便性にたつにはどのような方法があるのかというようなことを考えられ、私どもと一緒にその辺の商店街の活性化および地域の活性化に取り組んでいるです。","voiceIndex":259,"id":"exchange-108"},{"speaker":"南委員","kind":"質問・要望","question":"区としても取り組んでいくというふうに受けとめたいと思います。そういうことで困っておられる、そういう高齢者世帯に対しては、送迎バス、こういうものをぜひ仕立てていただいて、そんな大きなものじゃなくていいと思うんですけれども、２０、１５人乗りぐらいのものでいいと思う、十分だと思うんですけれども、そういうものをつくって、あるいは、補助金を出して検討していただきたいなと思っています。","respondent":"米田商業・観光課長","answer":"区といたしましては、そういう商店の商店主、あるいは商店街の動きを引き続きこれまでと同様に支援してまいりたいと考えています。","voiceIndex":261,"id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"２６９ページの環境対策費に関連をして、それから、２７１ページのマイガーデンに関連をして、それから２８３ページ、観光施策に関連して質問します。品川区の考え方をお伺いしたいんですが、計画停電の影響によって品川区が税金を使ってシルバーセンターを開放することであるとか、それから、公園の照明灯を一定程度暗くして、結果として区民サービスの低下を招くということ。お願いいたします。","respondent":"野呂瀬環境課長","answer":"それについては、今後も取り組みの中で、やはり環境課だけでなくて、区が一体となってこれからも節電等には取り組んでいく考えです。","voiceIndex":265,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"国政の話ですから余り踏み込みませんけれども、私は、本来はそういうところに責任があると思っていますので、これは意見として述べします。当然適切な目標を設定していかないといけないと思うので、このことについての品川区の考え方と、それから、区内施設、幼稚園、保育園、それから、小学校、中学校等への省エネ機器の設備の導入計画を教えてください。","respondent":"野呂瀬環境課長","answer":"それと、各施設の節電の状況等は、環境課を含めてですけれども、庁内の中でいろいろ検討会を開いて、連絡調整を図りながら進めていっているところです。","voiceIndex":267,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"すいません。それも改めて答弁お願いいたします。それから、成功ノウハウ、つまり、こういうふうにしたら省エネが達成できましたよと、成功例がどこの区施設もあるわけでしょうから、それを庁内で共有していくと言ったらいいのかな、あそこでこうだったら、じゃあ、今度こうしようとか、そういうふうに具体的に展開をしていく考え方についてお聞かせください。お願いいたします。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"目標等設定につきましてです。来年度、新規に環境計画等が策定されるところです。あわせて、地球温暖化の区の実行計画というのもあわせて策定していきますので、その中で明確な目標を定めていきたい、このように考えているところです。さまざまな節電のアイデアみたいなものを、庁内でもＩＳＯの会議がありますので、庁内施設におきましては、そういったアイデアをそこで集約することもできますし、また一方、去年の節電コンテストの中で。","voiceIndex":269,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問","question":"これは品川区の方向性なんだから、やっぱりそのことについては、単年度で終わるのではなくて、経年をしていくとか、それから、区の区有施設の表彰を何で考えないんですかね。それも、単年度ではなくて、例えば何年かやっていく。やっぱりそうすることによって、多くの区民の皆さんの先頭に品川区は立っていますよということになるわけでありますから、そのことについてあわせて答弁をお願いいたします。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"節電についてのＰＲについてです。節電コンテストは昨年やりましたけれども、引き続き平成２４年度につきましては、例えば商店街、区の商店街連合会と連携しまして、節電キャンペーンという形で、これは取り組んでいく考えです。一般区民の方向けはちょっと別にしまして、区のさまざまな施設の中でどういう努力をしたかということは、現状の制度の中でも、区の職員を表彰する規定がございまして。","voiceIndex":272,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問","question":"私が指摘したのは、品川区のことです。節電コンテストの結果ではなくて、品川区の職員が努力をして、結果としてこれだけ節電しましたということを区民にＰＲすれば、皆さんもすごく納得するんじゃないですか、それをしたらどうですかということの質問ですので、答弁をお願いいたします。","respondent":"野呂瀬環境課長","answer":"今現在、それぞれの施設においてどれぐらい節減をしたかという資料が手元にありますけれども、区民の皆さんに対しては、全体としてどれぐらいという公表の仕方ですので、今後、委員ご指摘のとおり、どれくらい各施設で節電頑張ったとか、やったとかいう。","voiceIndex":277,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"確認","question":"ぜひよろしくお願いいたします。このマイガーデン、非常に人気があるんですよ。６.３倍だったかな、去年は。だけど、東京都の事情で半分になっちゃったんだけど。やっぱりこれは、品川区はちゃんと責任を持ってやってもらいたいと思いますので、去年の決算特別委員会でご答弁いただいていますから、その後、検討を進めた結果どうなったんでしょうかという確認をお願いいたします。","respondent":"藤田水とみどりの課長","answer":"そういう中で、例えば花海道のところの、ちょっと斜めになっていますけれども、ああいうところが使えないかとか、そういう検討も行ってありますけれども、なかなかやはりああいう土地の中で、安全性を確保しながらやるのは難しいということも考えてあります。","voiceIndex":279,"id":"exchange-115"},{"speaker":"伊藤委員","kind":"確認","question":"だから、ぜひそのことについてはちゃんとしっかりと対処していっていただきますことをお願いをしておきます。なもので、確認したいのが、まずＪＡＬ機内の配布の掲載については、これは定期的に掲載するんでしょうかということの質問と、それから、羽田空港、それから、立会川、坂本龍馬、屋形船の観光ルート開発のことを考えていくと、すいません、どうしても浜川砲台のことが出てきます。","respondent":"米田商業・観光課長","answer":"今後もその辺のところにつきましては、考慮に入れつつ検討を行ってまいりたいと思います。","voiceIndex":281,"id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"私は、環境対策費、２７１ページのマイバッグ運動推進事業、２７３ページのリサイクル推進費の資源回収事業の中の拠点回収、それから、観光アクションプラン推進事業について伺います。２点目は、拠点回収ですが、受付等委託費ということで、８８０万円ありますが、これの内訳と委託先を伺います。３点目は、観光アクションプラン推進事業の推進事業委託７１５万円の内容を教えてください。","respondent":"野呂瀬環境課長、太田品川区清掃事務所長、米田商業・観光課長","answer":"今回、今までの使い捨て文化の象徴であるレジ袋というのがあったんですけれども、これについては一応一定の効果が出たということで、見直すということで。２点目の拠点回収における受付等委託経費、８７５万６,０００円ですけれども、拠点回収については、現在２６カ所あります。羽田空港の国際化に対応いたしました水辺を中心としたイベント、このような４事業で分かれているものです。","voiceIndex":284,"id":"exchange-117"},{"speaker":"井上委員","kind":"提案","question":"わかりました。ほかにもいろいろな回収部分のところがある中で、この拠点回収事業の事業評価はことしはどういうふうな評価をされているのか、この先をこのまま継続する必要があるのかということを検討する必要があるという視点で事業評価を伺います。そこで、今回のこの２,３００万円について、協会からの申請の内容と算定基準が適切であると判断をされた理由をお伺いしたいと思います。","respondent":"野呂瀬環境課長、太田品川区清掃事務所長、米田商業・観光課長","answer":"基本的にエコスポットについては、今設置してあるものが老朽化によって、相当今でも老朽化しているんですけれども。残りました古着、廃食用油、それから不用園芸土等については、ステーションでの回収ができないということから、拠点回収を実施しているものです。そちらのところで、情報センター機能の充実と来訪者の増加を目指すというようなことで、今回も被災地支援ツアーを。","voiceIndex":288,"id":"exchange-118"},{"speaker":"井上委員","kind":"質問・要望","question":"教えてください。やっぱりこれは最終年度にこの報告を求めるべきではないかというふうに思っていますが、お考えをお伺いしたいということが１点。それからもう一つ、補助金の一覧表を見ますと、個人への補助と団体へ補助ということがありましたので、交付規則の１２条、１４条を適用する可能性のある団体への補助が何団体あって、今までに近況報告や実績報告などを求めた件数があれば、件数を教えてください。","respondent":"太田品川区清掃事務所長、米田商業・観光課長、榎本企画財政課長","answer":"シルバー人材センターに委託している単価、ちょっと雑駁ですけれども、１,１００円から１,２００円ぐらいかなです。お尋ねの件ですが、補助金ですので、最終的にはその実施の内容について報告を求め、必要に応じて精算も行っていく、このような考えです。個人の場合については、それぞれ申請の段階できちんとその補助にあたるかどうかというのを確認した上で出しているということなので、適正に執行しています。","voiceIndex":292,"id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"わかりました。拠点回収の部分ですけれども、集団回収と拠点のこれに違いがこれだけあるということをどのように、要因というか、どういうふうに分析をされているのか、ちょっとそのことだけ教えてください。","respondent":"太田品川区清掃事務所長","answer":"その部分でなかなか団体によっては、集団回収自体が維持していくのが難しいというところがあるのかなと思っているところです。","voiceIndex":296,"id":"exchange-120"},{"speaker":"井上委員","kind":"質問・要望","question":"同じような事業が圧迫をしてしまわないためにも、独自で集団回収の場合には、そういう業者を探すとか、そういった困難があるのであれば、そういうところも含めて区が情報提供するとか、やりやすい仕組みで、限りなくごみの、こういったもののリサイクルを推進するということは同じ目的だと思いますが、内容を精査していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"１点目は、２６８ページのところに入るんでしょうか、環境学習講座というのがあると、その中に、放射能に関する講演会をするというふうに聞いております。今、放射能に対するいろんな考え方あるものですから、どういう形のものをしようとしているのか、お聞きします。３つ目は、２８３ページの消費者センター。これは、消費者団体の方たちの活動に対して、区はどういうふうに考えているのか。","respondent":"野呂瀬環境課長、工藤生活衛生課長、藤田水とみどりの課長、米田商業・観光課長","answer":"委員ご指摘の環境学習講座、これは環境課で主催して、環境情報活動センターの講座としてやっているんですけれども、平成２４年度。食品にかかわるいろいろなお問い合わせですけれども、私ども保健所の食品衛生部門に入っているお問い合わせとしましては。民間の菜園ですとか学校等で展開しているもの、これらにつきましては、民間については、サポートをする人たちがいたり、学校では。あわせまして、消費者センターの啓発展示室ですけれども、消費者センター自体は大井一丁目にもありますが。","voiceIndex":300,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"しかしながら、やはり菜園をやりたいという方の、区民の方々の要望が多いものですから、そういう場所がなかなかとれないという場合には、また新たな展開という形で、その方々だけじゃなくても、支援する輪というのもできる可能性もあるのかなと思いますので、ぜひとも、今学校で展開している屋上菜園について見直しを図って。","respondent":"工藤生活衛生課長、米田商業・観光課長、藤田水とみどりの課長","answer":"そういった中で、講演会の内容としましては、放射線においての正しい知識という部分を提供する、いわゆる食品に関する知識。あわせまして、本日から消費者センターのこの前の生活展のパネル展を本庁舎、消費者センターの啓発展示室の中と外でこの２週間展示を行って。そういった観点からいうと、建物の上の活用ということは、違う制約もありますので、そういった点もしっかり検討しなければいけないかなと思ってあります。","voiceIndex":305,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"放射能に関する講演会、これはいろんな、学術的にも統一されてないところがありますので、誤解ないように、弊害がないような形で選定をしていただいて、広げていただきたいと考えています。消費者センター、最後にお聞きしますが、なぜ防災センターの中じゃだめなんですかということなんです。それも少し変えればいい話だと思うんですよね。そこが変える、考える余地あるのかどうかをお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"庁舎管理規則にやはり従って、物品等の販売はふさわしくないだろうと考えています。消費者団体からもそういう声も聞こえております。","voiceIndex":309,"id":"exchange-124"},{"speaker":"武内委員","kind":"質問・要望","question":"私は４点、２５７ページの胃がん検診、それから２７１ページのエコライフ普及事業、３点目が２８５ページの商店街活性化事業費、４点目が２５５ページの任意予防接種、子宮頸がんについて伺います。胃がん検診につきましては、何回かほかの委員の方からも出ましたけれども、まず胃がんリスク検診、新しい検診の内容と、また導入の背景、経緯について教えていただきたいと思います。","respondent":"小川健康課長","answer":"その２つについて、いわゆる陰性か、陽性かということを判定いたしまして、両方が陰性の場合はＡ、そのほか、どちらかが陰性、陽性ということで、Ｂ、Ｃ、Ｄまでの検査結果が４つの総合判定の仕方をされるものです。","voiceIndex":312,"id":"exchange-125"},{"speaker":"武内委員","kind":"質問","question":"どちらかというと、じゃあ、この次の質問でまた伺いますけれども、国のほうでこれがピロリ菌と胃がんのリスクの因果関係というのが最近になって背景には、何ですかね、つかんできたというのがあると思うんですね。いわゆる世界の中では１９９３年にＩＡＲＣというところがこの因果関係を認めたという。それから随分おくれて、国のほうでは２年ぐらい前にそういう見解になったんじゃないかなと。","respondent":"小川健康課長","answer":"このほど、新しい胃がんリスク検診を導入するに当たりまして、国のガイドラインに沿った形で４０歳に、正しい形に合わせたというものです。","voiceIndex":314,"id":"exchange-126"},{"speaker":"武内委員","kind":"提案","question":"受診率に関係ない、今のところ、こちらの検診のほうは新しくなると。その部分の率というのは本当に微々たるものだとは思うんですけれども、その辺がちょっと整合性が私の中では整理つかないなと思いますので、もしあれば、もう１回お話をいただきたいのと、あと、先般の本会議のときに、うちの阿久津副委員長が、ピロリ菌関係の若い世代への検診の拡大ということでお話をご提案させていただきました。","respondent":"小川健康課長","answer":"もともと３０歳代の受診率というのは、本当にわずかの人数ですので、受診率には直接反映しないというふうに考えておるところです。","voiceIndex":316,"id":"exchange-127"},{"speaker":"武内委員","kind":"質問","question":"一定程度理解させていただきました。比較的胃がんに比べていいわけですから、しかも、年齢が４０歳からになっています。だから、今、５０歳からピロリ菌やろうとしているけれども、その１０歳下の４０歳から大腸がんやっています。この検便のキットのこの検査の中でピロリ菌もできるという手法があるというんですけれども、これを活用していくという考えはあるのかどうか、ちょっと見解を教えてください。","respondent":"小川健康課長","answer":"今、区で導入しようとしておりますのは、ピロリ菌とペプシノゲンをあわせた形のリスク検診を考えているものです。大腸がんの検便キットでの手法というご提案ですが、こちらについては今のところ考えてはございません。","voiceIndex":318,"id":"exchange-128"},{"speaker":"武内委員","kind":"質問・要望","question":"節電キャンペーンということで、先ほどほかの委員との答弁の中で、節電コンテストのほうはやらないようなニュアンスでしたけれども、そのキャンペーンの内容と、あと、平成２３年度の予算書には電力量測定機器貸し出しというものがあったんですけれども、今回載ってないというのは、恐らくもう購入して、あと貸し出すだけなので、あえて予算が載ってないのか、それとも。","respondent":"野呂瀬環境課長","answer":"それと、昨年度載っていました電力測定器、エコワットという小さいものなんですけれども、これにつきましては、昨年度もう購入しておりますので、継続事業ということで、あとは貸し出しするだけということで、購入金額等はここに載せていないです。","voiceIndex":320,"id":"exchange-129"},{"speaker":"武内委員","kind":"質問","question":"電力量測定機器のほうは安心しました。いろいろ効果は、後でまた伺えれる時間があれば、教えてもらいたいと思います。そうすると、ことしの夏は昨年と比べて、区民の方々に対する節電というのは、もっと厳しくなってくるのかどうか、そこだけ方向性をちょっと見解を教えてください。","respondent":"野呂瀬環境課長","answer":"それと、どれぐらいの、何ていうんですか、東京電力のほうから、昨年は結構上目に言われた、最高電力量がですね、ということもありますので、ことしにつきましては、去年の意識を持ったまま取り組んでいく。ただし、無理をしない範囲でということで考えているところです。","voiceIndex":322,"id":"exchange-130"},{"speaker":"武内委員","kind":"質問","question":"ぜひその辺のところを見ながらよろしく適切にお願いしたいと思います。それで、款が違いますけれども、民生費の中でこの買物弱者支援というのが出てくるんですけれども、まだ、やると決めたわけじゃないとは思うんですけれども、こことの連携とか、今後の考え方というのだけちょっと教えてください。","respondent":"米田商業・観光課長","answer":"品川第二のほうでそういうやりとりがあるということは聞いてあります。こちらについては、現状どのような運営がなされているか、こちらのほうの情報もしっかり取得しながら、今後の商業・観光課としての政策に結びつけていきたい、このように考えてあります。","voiceIndex":324,"id":"exchange-131"},{"speaker":"武内委員","kind":"質問・要望","question":"最後要望ですけれども、もちろん商店街振興といわゆる高齢者対策というんですかね、これとまたちょっと趣旨が逆のところになる場合もあるとは思うんですけれども、ただ、事業としては同じような事業になってくるので、しっかりその辺の、もしやるのであれば、整合性を持って、二重にならないように積極的に進めていただきたいと。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"２８３ページ、被災地観光促進経費、３８０万円、それともう１点、２８７ページ、商店街活性化事業、小規模商店街活力づくり支援事業についてお伺いしたいと思います。１点目、被災地観光促進経費、これの事業目的と内容について教えてください。","respondent":"米田商業・観光課長","answer":"こちらにつきまして、年度が変わりまして、観光協会で引き続き続けていきまして、被災地域の観光等による経済的な復興支援、こういうようなことを行っていこうと、こういうことで実施するものです。","voiceIndex":328,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"初年度の地域活動課から、今度観光協会に委託して、３０万円委託費が出ていますよね、観光協会。この委託費というのはどのような形になっているのか、使い方というんですかね、そこをちょっとお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"そちらの１件につきまして、観光協会に事務取扱手数料ということで、１,０００円につき１００円相当を委託費としてお渡ししていく、そういうような仕組みです。","voiceIndex":330,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"最初はやっぱりちょっと観光というと抵抗があったんですけれども、いつだったですかね、南三陸町に行ってきたんです。議会関係の仕事があったものですから、私はおくれて新幹線で仙台まで行って宿に泊まり、次の日観光バスで回ったんですけれども、向こうの、何というのかな、残ったホテルの広間で語り部さんから話を聞いたり、ＤＶＤ見たりしながら、そしてまた市街地を回ってきたんですね。","respondent":"米田商業・観光課長","answer":"そういうような趣旨も踏まえて、今年度実施に至りますが、参加状況等勘案しながら、今後検討してまいりたい、このように考えてあります。","voiceIndex":332,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"きのう、おとといですかね、防災フェア、やっぱり宮古市の物産展、参加して、たくさん買わせていただきました。宮古市は遠いんですよね。やっぱり防災協定結んで、宮古市と本当にこれだけ親しくなっているんですから、やっぱり自分たちが義援金を送った、その復興、被害の状況をしっかりと見ておきたい。ですから、この辺、しっかりと金額を上げて行けるような形、よろしくお願いをしたいと思います。","respondent":"米田商業・観光課長","answer":"そういった中で、過去に３商店街ほど実施をしてまいりまして、ある種それぞれの商店街特有の取り組みの中で、一定の集客効果を見込める方策等がある程度判明してきたということがあります。","voiceIndex":334,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"時間がないものですから。今のまいばすけっとという、これは何ですかね。ミニスーパーというんですかね。すごいですよ。話を聞きましたら、１万世帯に１軒。すさまじいですよ。もう本当５０メートル以内にまいばすけっとがあるんですから。本当にこれからの商店街活性化策なんていうのは、まいばすけっと、そういうのを見ずに、語らずにできないと思うんですから。その点だけお聞きしておきたいと思います。","respondent":"米田商業・観光課長","answer":"そういった意味では、近所の商店街の商店主さんがその場で新鮮なものを手に入れた、値段ではかなわないかもしれませんけれども、そういった品質のよさというようなことで、まいばすけっととの差別化が図れる、このようなこともあるのではないかと考えています。","voiceIndex":336,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問・要望","question":"これからせっかく小規模商店街活性化資金、つくったんですから、しっかりと活用していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":338,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"私は２８４ページ、中小企業対策費についてお聞きします。そしてまた、商店街へさまざまな支援をしております。共通商品券発行事業もあり、一定の区内経済への波及効果はあると思いますが、たくさんある商店街振興にはつながっているんでしょうか。それについてご見解をお聞かせください。","respondent":"福島ものづくり・経営支援課長、米田商業・観光課長","answer":"特に新製品・新技術促進事業では、これは今度メードイン品川ＰＲ事業につながると、支援したものがさらに製品として売れ、さらに広がっていく。それで、経済効果がもたらされる。そのように認識しています。商店街、特に個々の商店の方々、現在の経済状況におきまして厳しい状況に置かれているということは認識しています。その中で、区といたしましては、さまざまな補助、支援の仕組みを構築いたしまして行ってまいっているものです。","voiceIndex":340,"id":"exchange-139"},{"speaker":"須貝委員","kind":"意見","question":"ものづくりのほうは、これからだんだん新製品をつくって、そしてうまくいけば、区内経済の発展につながっていけるように努力してほしいんですが、まあ、これはあくまで国の施策というのが一番大きな要因なので、国内空洞化等を考えると、大変だと思いますが、ちょっと効果はこれから見します。商店街のほうなんですが、毎年商店街活性化事業費を助成しております。毎年毎年しているわけですよね。","respondent":"米田商業・観光課長","answer":"私どももそのご努力におこたえするような形で、これは継続的に支援をするものにつきましては、引き続き継続して支援をしてまいりたいと考えておりますし、今後新たな施策の展開があれば、また事業の組みかえ等、こういうことも十分検証してまいりたい、このように考えてあります。","voiceIndex":343,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"一生懸命努力されている。次に、区内企業の実態についてお聞きしたいと思います。ところで、ここで、品川区、余り出てこないんですが、品川区内の企業はどうなんですか。実際何件、区内企業が、小さいところも含めてあって、実際倒産件数、これは少ないようですが、休業、廃業、解散している企業数、こういうものについてちょっと数字を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"こちらにつきましては、比較はなかなか難しいんですけれども、平成１８年に行いました事業所・企業統計調査では、２万１,６３８社、ちょっと調べ方が違うので、一概には比較できませんが、品川区内の事業所は増えている傾向にあるのではないかというふうに理解しています。","voiceIndex":345,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"実際、今、先ほど国のことを動向お話ししましたが、品川区は区内経済、区内でちゃんと営んでいる企業の数というのは、私は一番直近であるんだから、やっぱりきちんと調べるべきだと思うんですね。実際この数字だと、日本全体では、休業、廃業、解散が倍以上ある。これからやるのかどうかわかりませんが、その辺について、今まできちんとした報告がないんですが、それについてどのようにお考えでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"実態調査につきましては、平成２４年度に区内、製造業ですけれども、データベースを更新する際、悉皆調査をする予定ですので、その中で実態を十分把握していきたいと考えています。","voiceIndex":347,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"その方たちを我々は支えなきゃいけない。中で、実態がどうなの？いや、いいようですよ、倒産減っていますよと言うんだったら、ちょっと議論のしようがないじゃないですか。できるだけ早めに、まして大震災以後、これからますます大変になるということならば、そういう実態を調べて、そしてこういう予算の議論とか、そういうものに対して生かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-143"},{"speaker":"阿部委員","kind":"質問","question":"私からは、２８３ページの消費者センター、大井一丁目の修繕積立金について、それから、２８５ページの武蔵小山創業支援センター、および、関連して、２９１ページの西大井および天王洲の創業支援センターについて、その後時間がありましたら、品川ビジネスクラブ等についてもお伺いしたいと思います。端的に伺います。いつまでこのような形でやっていくのかというお考えを伺いたいと思います。","respondent":"米田商業・観光課長、福島ものづくり・経営支援課長","answer":"あわせて、都市計画課で、区民住宅を持っておりますので、都市計画課でも面積に応じた修繕積立金、それから、その他の権利者の方々も、面積に応じた修繕積立金を行っていくものです。今後、区として続けていくかですけれども、確かに民間で行っている施設等もあることは十分知ってありますけれども、やはり区内企業の活性化、あるいは起業により区内で成長していく、企業を育てていく。","voiceIndex":351,"id":"exchange-144"},{"speaker":"阿部委員","kind":"質問","question":"大井一丁目のほうは、この６３０万円の中に、例えば社協の分の面積分というのは入っていないんですかね。要は、どこからどういう名目で、何て聞いたらいいんでしょうか。多少手間というのもあるかもしれませんが、予算の立て方、組み方という考え方からして、いろいろ入っている団体のものをすべて消費者対策費の中でくくってしまうというのはどうなんだろうかと、そこら辺もう少し伺いたいと思います。","respondent":"榎本企画財政課長、福島ものづくり・経営支援課長","answer":"その中で商業・観光課が３分の２、住宅が３分の１持っているということで、実際に社協が使用している部分は１５％ぐらいということで、かなり少ない部分です。そういった意味で、大きく２つのところで修繕積立金を計上しているものです。創業支援につきましては、こういった施設での支援以外にも、融資あっせんですとか、あるいは、経営相談の中で起業相談等を行っておりますので、そういったことも含めまして、区内での起業について支援をしていきたいと考えています。","voiceIndex":354,"id":"exchange-145"},{"speaker":"阿部委員","kind":"質問・要望","question":"消費者センターについては、ちょっとまだ違和感は残るところではありますけれども、一応の合理性ということで伺いました。それから、創業支援センターについては、要望です。今後のビジネス社会の変化、さまざまな創業支援の変化等々にできるだけ機敏に対応して、今後も考えていってほしいと思います。これは要望です。残った時間で端的に伺います。今後のこの２つの事業の方向性について教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、平成２７年に施設ができたときに、実際にそれをどうするのか。それについては今後も検討は必要かと考えています。","voiceIndex":357,"id":"exchange-146"},{"speaker":"若林委員","kind":"質問・要望","question":"小規模商店街のほうも、先ほど金額のお話、私も聞きたかったんですが、流れましたので、いわゆるプレス発表でいう事業費助成（補助金）の１５０万円が予算書ではどうなっているのかというのはちゃんとお聞きしておいたほうがいいかなと思いますので、とりあえず２点。","respondent":"小川健康課長、米田商業・観光課長","answer":"申しわけございません。障害者歯科検診の「検」の字ですが、健康の「健」という字に訂正します。心からおわびを申し上げます。プランの策定を来年度速やかに行い、事業も当該年度に速やかに行うというようなことで、プレス発表のほうで、プラン策定費ということで２５０万円、事業費ということで１５０万円計上させていただいてあります。","voiceIndex":360,"id":"exchange-147"},{"speaker":"若林委員","kind":"質問・要望","question":"昨年の決算でも質問して、ちょっと答弁のお時間がなかったので、そのままになりましたけれども、この共通商品券が来年度も３億円の３億円、合計６億円というふうになります。もしとられていなければ、今後、データをしっかりと調査、データをつくって、今後の小規模商店街等への施策の、これは大事なデータになると思いますので、ここについての統計、調査、分析、ちょっとお聞かせいただきたい。","respondent":"米田商業・観光課長","answer":"そういった意味では、完全なものではないかなというふうには思っておりますが、どこで購入されたか。こういうようなものについては、商店街連合会で統計をとっているものです。","voiceIndex":363,"id":"exchange-148"},{"speaker":"若林委員","kind":"意見","question":"商店街の方々のお仕事がもしかしたら増えるということになるのかもしれませんが、これは逆に商店街の方も喜んでいる事業。区のほうも、そして区民のほうも、みんなが喜んでいる事業。商店街、約１０８の商店街があります。区にとって、この商店街は、例えば防犯、それから、今、防災、これについて、区は商店街にどのようなことを期待され、また、今どのような評価、存在なのかというのをお知らせください。","respondent":"米田商業・観光課長","answer":"そういった意味では、子どもの通学等の時間帯における見守り、あるいはそこを通られる方のいわゆる何かしらの事故があったときのすぐの対応というようなことで、安全なまちづくりに商店街の方々は非常に寄与していただいているというふうに考えているところです。","voiceIndex":365,"id":"exchange-149"},{"speaker":"若林委員","kind":"質問・要望","question":"そのとおりだと思います。そこで、都内の各所で商店街と行政との防災協定みたいなものが結ばれているというふうに、そういう事例があると。品川区ではいかがでしょうか。数字だけで結構です。多くの人が通られる。そういう中で災害が起こるということで、商店街の防災について品川区はどのように、もし具体的なことがあれば、教えていただきたいし、今後の考え方をお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"不勉強で大変申しわけございませんが、防災協定については、私のほう認識してございません。アーケード等についてですけれども、アーケードに限らず、各商店街、自主的、あるいは町会と協働しながら防災訓練等を行っていると聞いてあります。","voiceIndex":367,"id":"exchange-150"},{"speaker":"若林委員","kind":"質問・要望","question":"大型店の連携、ぜひ防犯、また防災の点で、お互いにまたＷｉｎ－Ｗｉｎの関係になれるように、しっかりと知恵を出していただきたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":369,"id":"exchange-151"},{"speaker":"須藤委員","kind":"意見","question":"２７３ページのリサイクル活動支援事業に関連して、先ほどご答弁いただいた廃油、油は拠点回収で回収してリサイクルしているというのは聞いたと思っているんだけれども、どのくらいの量が回収されているのかな、ちょっとお聞かせください。","respondent":"太田品川区清掃事務所長","answer":"廃食用油です。年間で平成２２年度の実績で約５,９００キロぐらい、平成２１年度で同じく５,３００キロ、こういうことで推移をしてきているところです。","voiceIndex":371,"id":"exchange-152"},{"speaker":"須藤委員","kind":"質問","question":"これは多くはこうやって回収されているというふうに理解していいのかな。それとも、一般家庭で下水の中に流しちゃっているよというのもかなりあるよというような考え方で見といていいのかな。５,３００キロと５,９００キロという数字がどうかなというような思いがあるんだけど、いかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"それからあとは、固められれば、固めていただいて、燃やすごみで出していただきたい。あるいは、個々の拠点回収としての廃食用油でお出しいただくと、こういうことです。申しわけございません。全体の量というのは把握しきれませんので、廃食用油として出てくるのは一部かなです。","voiceIndex":373,"id":"exchange-153"},{"speaker":"須藤委員","kind":"意見","question":"東京都で下水道で、ミドリムシを養殖してどんどんきれいにするとかというような話をちらっと聞いたので、ちょっと言明したんです。それから、２８９ページの海外進出推進事業で、これはどういうことをどういうふうにやっているのか、お聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの海外進出推進事業ですが、国際ビジネス支援講座の開催、ならびに実務セミナー、さらには品川バンコクビジネスサポートセンターの運営等を行っているものです。あわせて、国際化対応専門相談員を配置しまして、各種相談に乗っているものです。","voiceIndex":375,"id":"exchange-154"},{"speaker":"須藤委員","kind":"質問","question":"区の職員のＯＢで、毎年２回ぐらいタイに行っているのがいるので、そういう人たちと連携とったら、また違う仕事ができるのかなと思っているんだけれども、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの支援につきましては、別途うちのほうで契約した現地のスタッフが支援をしているというものです。区のＯＢ、よく行かれるＯＢの方を使ってですが、この場ではどういう事業ができるのかよくわかりませんので、今後研究、あるいは考えたいと思います。","voiceIndex":377,"id":"exchange-155"},{"speaker":"須藤委員","kind":"質問","question":"まあ、今はいわゆる産業振興というのが、商業・観光課とものづくり・経営支援課という２つに分かれている。昔は商工課、産業振興課というので、１つだった。そのこと自体が品川区の全体の産業振興に対して、いいと思っているからやっていらっしゃるんだろうと思うんだけれども、そのドッキングをどこかでまた組み合わせてやる必要があると思うんだけれども、その辺はいかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、マイナスといいますか、難しい面は、１つの課がやはり小さいということもありますので、なかなか人的な問題では難しい面もあるというのも事実です。","voiceIndex":379,"id":"exchange-156"},{"speaker":"須藤委員","kind":"質問","question":"そのあたりが連携するのが、やはり３つの条件というかな、３つが了解しないと前へ進まないよというようなところがあろうかと思うんだけれども、その辺は、こういう時代になっちゃったんだから、工場協会を一本化してもらって、先ほどのものづくり・経営支援課と一緒になってしっかり進めていくという仕組みは、これはまちの人に対してだけど、なかなか難しいでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"これの一本化の問題ですが、何年か前から検討を重ねておりまして、来年には一本化されるのではないかというように聞いてあります。一本化して、また私どもとの関係も新たにしまして、より品川区の産業の育成のために努力していきたいと考えています。","voiceIndex":381,"id":"exchange-157"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろんな仕組みが、しっかり整理するところは整理をしながら、区民全体に還元できるようにさらに図っていっていただきたいと思います。それから最後に、ものづくりと製造業というのが予算書の中にいろいろ両方書いてあるんだけど、どういうふうに見ればいいのかなというところ。同じことだよね、ものづくりと製造業とかというのは。予算書には仕分けしてこう出てきているんだけど、何か理由があるのかどうか。","respondent":"福島ものづくり・経営支援課長","answer":"ものづくりと製造業ですが、製造業だとより限定されたものだというふうに考えてありますし、ものづくりの場合は、ことづくりも含めたさまざまな仕組みをつくっていく、産業の仕組みをつくっていく言葉だというふうに理解しています。","voiceIndex":383,"id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=972#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":116396,"voices":385}},{"id":"h24-20120313-3","meetingId":"h24-c-budget","date":"2012年3月13日","dateIso":"2012-03-13","committee":"予算特別委員会","time":"午後５時３９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"結果は、費用対効果等が非効率であったということで、そのままＬＥＤ灯の導入には至らなかったかと思うんですけれども、震災が起きて、状況が変わってきたかと思うんですが、やはり費用の部分では、いろいろ負担があったということだったかと思うんですけれども、庁舎の電気代も８億円で、１７％増えるかもしれないという中で、節電という意味で、ＬＥＤ街路灯というのが、今後。","respondent":"稲田道路公園課長","answer":"引き続き、コスト面、それから技術面を検討しながら、職員も見本市等に行ったりして、直接そういう情報を集めたりしておりますので、今後も、アンテナを張ってやっていきたいと思います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"やはり街路灯のほうも、節電という意味の観点から、技術の部分はあるかと思うんですけれども、これからぜひ進めていっていただきたいと思います。災害強化をしていくという中で、減額をされたという、その理由について、まずお伺いさせていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"減額のほうの理由ですが、やはり来年度に向けて、用地、どの場所を取得できるかという見込みによって、予算計上はしております。それぞれの土地の広さ等がありまして、その辺の関係で、今回は減額ということになっている状況です。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"この事業は、前にも質問させていただきましたけれども、平成３０年までということに一応なっていますけれども、その見通しということも含めて、平成２１年度からやっておりまして、３年間の整備状況、７.２ｍを１０ｍにするという中で、今の整備状況についてお伺いしたいんです。","respondent":"品川防災整備担当課長","answer":"対象物件は、１３５棟になります。今現在できていますのが、平成２１年からやっておりまして、現状で、３棟となっております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"現状、７.２ｍあって、確かにちょっと狭いという感じはするんですけれども、東京でも、地震が４年以内に７０％起きると言われている中で、拡張が先なのか、それとも近隣の建物の耐震化を進めていくのが先なのかという、その政策的な優先はどうなっているのか気になるんですけれども、その辺を含めて、ちょっと教えていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"耐震と拡幅と、どちらが優先かということなんですが、防災まちづくりというのは、こういうものを一体的に進めていく事業です。どちらが優先というものでもなくて、すべてのことについて、徐々に進めていかなければいけないという事業と考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"それは、どっちも進めていくことは大切だと思いますし、そのとおりだと思うんですけれども、皆さん、建て替えるときに、耐震か、それとも拡張か、両方とも進めていくと。この道は、避難道路としては、池上通りに出た後に、またもう１回右に曲がって、左に曲がって大井競馬場まで行くと。５０年かけても、やっていくと。特に期限を区切らないで、計画道路ということで進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鶴委員","kind":"確認","question":"最初に、道路安全施設費関係ですけれども、遮熱塗装関係について、お尋ねいたします。そうした効果が確認されたことを受けて、平成２３年度、準歩道等への効果を検証したいということだったと思いますけれども、それがどこの準歩道で行われたのか、またその効果がどうだったのか、まず教えてください。","respondent":"稲田道路公園課長","answer":"遮熱性塗料による舗装の件なんですけれども、平成２２年度、第二駐車場で実施しました、水溶性塗料による遮熱性舗装なんですけれども、スクールゾーンとかによく使っております道路の脇の部分に色を塗っていくという方法なんですけれども、今年度、旗の台四丁目６番先、それから。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鶴委員","kind":"質問・要望","question":"それぞれ４カ所で、平均６℃ということだったのでしょうか。後で、それを教えてください。効果があったという評価だと思います。平成２４年度、それぞれどこに施すのかということで、施工する箇所が飛び飛びであるのであれば、主なところだけでも結構なので、それを教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"といいますのは、水溶性アクリル樹脂系の塗装なんですが、耐用年数がまだはっきりとわかっておりませんで、一般道路上で、供用している道路で、車を通しながら、どの程度もつか、そういうところとか、あとは温度の低減効果等もあわせてはかっていきたいというところで。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鶴委員","kind":"質問・要望","question":"私も、ネットで言葉を調べたら、標示のほうなのかなと思いましたので、それで合わせていただければと思います。それから、今ご答弁いただいたところの、準歩道カラー標示で、効果の検証でありますけれども、ちょっと私もお聞きしていて混同してしまって、涼のみちというか、水溶性遮熱塗装剤が、準歩道カラー標示に一緒になっているのか、その辺をちょっともう１回、教えていただきたい。","respondent":"稲田道路公園課長","answer":"一般的に、交通安全施設である準歩道のカラー標示というのは、ニート工法という遮熱性塗料ではない、別の交通安全用の舗装剤です。それにかえて、遮熱性塗料で準歩道をやっていこうというのが、今年やったものです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"わかりました、理解しました。そのうえでなんですけれども、遮熱性塗装が、今年度から含めたものということなんですけれども、そうではないタイプの、いわゆる安全上の意味合いで施していたというところでお聞きしたいんですけれども、表現の仕方が正しいかどうかあれなんですけれども、通学路になっているところで、準歩道のところでは、すべてカラー標示になっているのかどうか、その辺を教えてください。","respondent":"稲田道路公園課長","answer":"スクールゾーンが準歩道のカラー標示に、すべてなっているかというところですが、すべてなっているというわけではございません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"そのうえで、平成２４年度は、準歩道についても、そうした遮熱性がある塗装剤を使っていくということでありますけれども、どういった塗装剤を使うかは、実験結果とか、検証結果にゆだねるという形になると思うんです。涼のみちの事業そのものは、ヒートアイランド対策の一環ということで始まったと思うんですけれども、この辺あわせて実施できないか、その辺の可能性をお伺いしたいと思います。","respondent":"稲田道路公園課長","answer":"準歩道の遮熱性塗装というところですが、今、実験中でございまして、費用対効果等を今後検証したうえで、また検討していきたいと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"次に移ります。そのうえで、３１９ページの安全・安心の公園づくりとありますけれども、その財源と事業内容を、簡単で結構ですので、教えていただきたいと思います。あわせて、事務事業概要を見てみますと、平成１９年から始まったのかなと思いますが、毎年２カ所ずつの整備実施なんですけれども、その理由と、実施済みの公園がどこであるのか、わかれば、教えてください。","respondent":"稲田道路公園課長、榎本企画財政課長","answer":"既に、安全・安心の公園づくりでやった公園なんですが、平成１９年には西の森公園、後地公園、それから、滝王子公園といきまして、年２カ所ずつやっております。平成２３年度は葦山公園、広町公園です。財源のほうの話ですけれども、都の福祉のまちづくりのほうの包括補助が入っております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鶴委員","kind":"確認","question":"財源については、よくわかりました。公園については、ちょっとまた改めて確認します。それぞれ２カ所ということで、理由は、今の財源との絡みなのでしょうか。","respondent":"稲田道路公園課長","answer":"これは、私ども全公園をチェックいたしまして、計画的にやっていっているものです。財源はもちろんあるんですけれども、バリアフリーとあわせて、年間２カ所程度やっていくという計画で進めているものです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"こうした区内の公園で、今まさに安全・安心の公園づくりの施策の中で、順次やっていると思うんですけれども、準歩道に面しているとか、また、子どもが公園から容易に飛び出せて、自転車とか車に接触する危険性が伺えるようなところ、そうした準歩道に面した公園の数などを、数字的に押さえているのかどうか、この辺を教えていただきたい。","respondent":"稲田道路公園課長","answer":"申しわけないのですが、その数というのは、現状では出てこない状況であります。ただ、２カ所ずつの少ない数とは思われますが、優先順位としましては、そういう交通安全上の危険な場所というところを選んでいきながら、やっていっている次第です。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"その基準というのは、どこが優先なのかという問題もあると思うんですけれども、そうしたところをよく検証していただいて、的確な整備を進めていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"},{"speaker":"木村委員","kind":"質問","question":"３１３ページの真ん中から少し下に、やさしいまちづくり推進費というのがあります。１,５３４万１,０００円ですが、この中の事業名、平成２３年度と平成２４年度では、項目は変わっていますし、平成２３年度、１億１６２万９,０００円、そして、平成２４年度は１,５３４万円余と、大きく減額しています。ハードの面でも、ソフトの面においても、大変大事だと思います。","respondent":"山崎マスタープラン担当課長","answer":"国のほうでは、高齢者、障害者等の移動等の円滑化の促進に関する法律、いわゆるバリアフリー新法ものですが、こうした法律の中に、先ほどご説明したユニバーサルデザインの考え方が根幹に入っているです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問","question":"しながわお休み石設置事業、８基とありますけれども、平成２３年度と平成２４年度の予算が丸きり同じです。もし間違っていたら申しわけないのですけれども、大井町駅から区役所までのアーケードのついていない反対側、そちらのほうに８基、円形の丸いいすがついているんですけれども、そのいすがしながわお休み石ということで、よろしいでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"委員ご指摘の場所ですけれども、現在、区役所と反対側のほうで、大井町西地区の再開発事業が行われておりますけれども、その歩道の前から、ちょうど駅のほうに向かいまして、イトーヨーカドーの入口、東急のバス停がございまして、この間に５カ所、２基ということで。","voiceIndex":35,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"点状ブロック、一般歩道にも、点状ではなく、棒線状の突起がありますけれども、大井町駅から区役所までにもたくさんつけてありますよね、アーケードがついているほうですが。反対側の歩道にはありませんけれども、そういうところにも、障害を持った方々が歩く機会もあると思うんです。どうして反対側の歩道に設置していないのか、何か訳でもあるのか、教えてください。","respondent":"山崎マスタープラン担当課長","answer":"例えば車いす使用者等の通行が悪化する等の問題もあります。そうした観点で、原則１経路に基づいて設置をしているです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"わかりました。横断歩道の前には、必ず点状ブロックがあります。実際に、この点状ブロックがあることで、障害を持った方々にとっては、大変心強いことだと思います。すべてとは言わなくても、取付け可能な道路や横断歩道、そして、歩道などにもしっかりとつけていただく計画があるかどうか。そして、もしないのであれば、これからぜひ、前向きに検討をいただきたいと思いますが、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"したがって、大井町につけてもう２年経ちますけれども、この是非について、この懇談会の中で、今、議論をしている最中です。今後、積極的に進めるにあたっても、この７団体の方々の意見をよく聞きながら、設置場所等については、厳密に選定していきたいと考えております。","voiceIndex":39,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"なぜならば、急行が通過する駅というのは、特に先につけるべきではないかと思います。私も、実際に飛び込んだところを目の当たりにしたことがあるんですけれども、そういう意味で、自殺防止にもつながりますし、また、ホームが下り坂になっているところがありますので、今、いろいろな対策がとられておりますが、そういう通過する駅こそつけたいと思いますが、いかがでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"具体的には、１日の利用者が１０万人を超えるような駅については、そうした転落防止の危険性も高いというようなことで、そういった考えがあるものですけれども、委員おっしゃられたとおり、通過駅こそ、ホームの進入速度も速いというようなこともありますので。","voiceIndex":41,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"２９９ページ、補助２０５号線整備ですが、これは決算特別委員会でも伺いました、東京浴場の交差点の信号ですが、あのとき、区としては、ただ交通管理者にお願いするだけではないと、積極的に設計からかかわって行動していくんだという答弁をいただいたんです。今まで全くなかったんですけれども、この辺、区もどういう状況であるか、教えていただきたいのと、理由があったら、教えてください。","respondent":"藤木交通安全担当課長、武藤都市整備下水道課長、品川防災整備担当課長","answer":"どちらもすぐに解決できない問題で、しかも身近な問題だと思いますので、その辺に大変頭を悩ました２年間でございました。ただし、今、委員ご指摘ございましたように、区としましても、当該交差点における信号の必要性につきましては、強く認識しているところでございまして。耐震シェルターのほうですけれども、今までの実績では、品川シェルターが３件、それから一般のシェルターのほうで１件です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"補助２０５号線の信号は、楽しみに結果を待っておりますので、よろしくお願いします。そういうマスコミに出ることによって、シェルターというのは独自性もあると思うんですけれども、区民の方が興味を持ってくださるというのは、ものすごい効果だと思うんですけれども、その辺について、どうですか、ということ。その辺について、お伺いします。","respondent":"藤木交通安全担当課長、品川防災整備担当課長","answer":"自転車につきましては、健康に効果があるですとか、震災による交通困難を機に、交通手段としても脚光を浴びているところではありますが、区内のこのような狭隘な道路状況を考えて、安全ということを第一に考えますと。さすがに全国ネットのテレビですと、今回も、区外からの問い合わせがかなり多かったです。そういった方々も関心が強いということで、品川シェルターも、これからどんどん啓発活動を進めて、普及をしていきたいと考えています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる品川区が、生活および交通に力を入れていると思うんですけれども、やっぱり、その中において、警部でもいいかもしれないし、警部補でもいいかもしれないという思いもあるんですけれども、やっぱり警視だからよかったということも、場面的にあったと思うんですけれども、その辺については、いかがですか。","respondent":"藤木交通安全担当課長","answer":"単なる力作業みたいな、例えば自転車撤去で一緒になって運ぶとか、そういうのだったら若い人のほうがいいんでしょうけれども、いろいろな警察署との交渉事とか、ときには無理なお願いをすることも多々ありますので、その点。","voiceIndex":51,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"３２１ページの武蔵小山駅周辺地域整備事業について、お伺いします。１４０ｍのスカイラインが庶民のまちと言えるのか、どうか。それから、住民意向を無視した方針づくりは認められないと思いますが、いかがでしょうか。こういった環境悪化は問題ではないでしょうかと質問させていただいたんですが、環境悪化についてのご答弁がなかったので、これもあわせてよろしくお願いします。","respondent":"三宅都市開発課長","answer":"こういったことで、地域住民から賛同を得られると考えております。それから、環境のほうですけれども、こちらは、今まだ具体的な環境影響の評価はやっていない段階ですので、その状況の説明はまだできる状況にないです。","voiceIndex":56,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、こういった面をしっかりと受けとめて考えるべきであると思いますし、密集を解決するのが、なぜ１４０ｍなのか。高度利用といって、その高度利用がなぜ１４０ｍにもなるのか。大崎は副都心の位置づけで、都市再生特別措置法に基づいて開発がされていますが、武蔵小山も、その副都心のような開発を進めていくのかどうか、その点もお伺いをします。進めてはならないと、私は思いますが、いかがでしょうか。","respondent":"三宅都市開発課長","answer":"市街地整備基本方針で定めております拠点には、多くの人が集まる武蔵小山は、より多く集まるべきような場所であると考えておりまして、そういう場所では、道路、広場といった空間をはじめ、さまざまな床の需要、必要性があって。","voiceIndex":58,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"風の害も最大限考えていくと言われていますけれども、現実的に、悪化をしているのは事実です。それから、地域の意向を無視して進める、こういった計画は直ちにやめるべきであると思いますし、何よりも、地域の人の総意で進めるといった観点が必要です。ぜひ、今回の方針、皆さんに説明会を開いて意見を聞いていただきたいと思いますが、いかがでしょうか。","respondent":"三宅都市開発課長","answer":"環境が悪化するようなまちづくりはすべきでないという１点目のお尋ねですけれども、私どもは、風害という形のものは基本的には発生していないと考えております。従前の土地利用のやり方と比べれば、変化するものですが、そのように考えております。","voiceIndex":60,"id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、３１５ページ、公園・児童遊園維持管理費のところで伺ってまいります。今日、伺いたいのは、公園の管理のところ、使い方の中で、特に昨日まで話も出ていましたペットという視点、それから、子どものボール遊びの視点等で伺いたいと思います。公園の基本原則で、いつでも、だれでも自由にという、この確認、まず公園の基本原則の定義を伺いたい。","respondent":"稲田道路公園課長、井浦土木管理課長","answer":"現在の公園なんですけれども、４月１日の公園調査では２４５カ所となっておるんですけれども、今年度途中で若干増えまして、委員のご質問の犬が入れる公園、それから、入れない公園ですけれども。犬等で利用者に迷惑がかかるというものについては、公園の管理に支障がある行為をすること、ということで明文で定めている。このような根拠に基づいて、円満な利用調整に努めているところです。","voiceIndex":63,"id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問・要望","question":"公園の観点に絞って、幾つか伺います。罰則強化の必要性、また、都市公園法においても、該当する、あるいは適用できる、あるいは参考になるものもあるのかどうか、伺いたいと思います。それからもう１点、すべて行政任せではない部分、区民との協働の観点になるかと思いますが、管理をすべて職員でできない部分が、どうしても出てくるかと思います。この２点を、お知らせください。","respondent":"岩田都市環境事業部長","answer":"それでもマナーの悪い公園については、一時期、啓発期間中禁止という、暫定的な方法も取り入れて柔軟に運用ができないかということを、今、検討させておりますので、近々、たばこと同じように、所管からの結論が出てまいりますので、経営会議にかけまして。","voiceIndex":66,"id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それぞれ公園のことは検討をなされているという見解がありましたので、もう１点だけ、直近で要望として多いところ、特に戸越公園があって、そして今、国文学研究資料館跡地が整備される。やはりあれだけの中規模、大規模なところで、ぜひとも棲み分け、共存の可能性を探っていただきたい一つの例というか、象徴的な場所でもありますので、これはぜひお願いしたい要望なんです。この点を伺いたい。","respondent":"武藤都市整備下水道課長、稲田道路公園課長、岩田都市環境事業部長","answer":"先ほど、都市環境事業部長のほうから答弁しましたとおり、犬の関係につきましては、我々も一定の配慮を考えておりまして、これまでも、地元の説明会の中で。キャッチボール等を禁止している公園の数についてですが、まず、キャッチボールというとらえ方なんですけれども、硬いボールで本格的に投げ合ったり。例外的に鳥かごのようなものが設置してあるところが何カ所かあるんですけれども、そこ以外は、基本的に禁止です。","voiceIndex":68,"id":"exchange-028"},{"speaker":"渡辺委員","kind":"意見","question":"あるいは、ボール遊びの定義の問題になってきて、ここまで言わないとだめなのかというぐらい、ほんとうに細やかなルールづくりが、現実問題、必要なのかなと思っています。高齢者との棲み分けも、ほんとうにしていかないとつらいんだなということを切実に感じていますので、その辺のエリアの分け方とか、時間による区分けのルールづくりが、遊び方も必要かと思いますので、その点で、一言お願いします。","respondent":"岩田都市環境事業部長","answer":"この問題も、先ほどの犬と同じようなことですので、今、検討している中で、十分に議論していきたいと思います。","voiceIndex":72,"id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"時間がありましたら、３３１ページの借上型区民住宅管理費の借上料について、お伺いしたいと思います。それから、不燃領域率というのが、どういうメッシュというのですか、どういう単位というのですか、面積というんですか、細かさという言い方のほうがわかりやすいのかもしれませんけれども、はかられているのか、捉えられているのか、ここを２点、まず、お伺いしたいと思います。","respondent":"品川防災整備担当課長","answer":"２点目の整備地域ですが、東京都が出しております防災都市づくり推進計画というものがあります。この中で、一定の条件として、地域危険度が５に相当し、老朽木造建築物棟数率というものがあります、これが４５％以上、それから平均不燃化領域率が６０％未満というものです。","voiceIndex":75,"id":"exchange-030"},{"speaker":"塚本委員","kind":"確認","question":"一般に７０％を目指しましょうということを不燃化促進の中ではあるかと思うんですけれども、７０％といった場合は、前提として、そういう地域を区切っての話をしているのか、あるいは品川区全体というような形で話しているのか。その辺はどういう地域をもとにしての７０％という目標を言われているのか、そこの２点を、お伺いしたいと思います。","respondent":"品川防災整備担当課長","answer":"これは当然、八潮のほうを含めば出る数字だということは、ご理解できるかと思います。ということで、７０％を目指しているというものは、あくまでも整備地域だったり、一つの町丁目の地域だったり、そういうところを考えております。","voiceIndex":77,"id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、地域を一番わかっている品川区独自で、費用対効果というのを考えながら、ここに延焼を防ぐための集中的な遮断帯とまで言えるのか、言えないのかわかりませんけれども、そういった形での不燃化政策というのでしょうか、独自の不燃化領域率の上げ方というか、改善の施策、こういったものを考えていく必要があってもいいのではないかと思うんですけれども、その辺について。","respondent":"品川防災整備担当課長","answer":"この事業エリア内での不燃化領域率を出しまして、これを約何％上げていくかとか、そういった形の一つの指標として、不燃化領域率のほうは使っております。品川区としても、エリア内に限っての不燃化領域率を出しまして、一つ不燃化の進んでいる状況というものを見ております。","voiceIndex":79,"id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"燃え広がらないようにする、今後も、今やっていらっしゃることに加えて、さまざまな独自の施策を新たな部分でも検討していっていただきたいと思いますので、よろしくお願いいたします。そこで、樹木が防災林という言い方が正しいのかどうか、これが実際に防火、延焼防止に役立つということでのご説明というか、その辺、どういうふうにとらえていらっしゃるのか、お話しいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"火が出たときに周りに熱を放出します。当然、火は危ないんですが、その周りにいてもかなりの熱量になります。そういった熱を遮蔽するひとつの効果として樹木が非常に有効であるということは、広域避難場所の人数の計算をする中でも、そういう算定に入れているような状況です。","voiceIndex":81,"id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。品川区内、ここ数年の間で、たくさん防災公園が整備をされ、あちこちにできているかと思います。植える、植えないの考え方というんですか、前提というのは、どういうところで決めていらっしゃるのか、そういったところをお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"先ほども防災整備担当課長の答弁にありましたとおり、樹木の持つそうした機能について、ただいま、マスタープランを策定しておりまして、防災部門とも連携しながら、そうした防災性の向上に資する都市緑化という観点で、いろいろ検討しているところでおります。","voiceIndex":83,"id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。大変に効果があるですので、効果を最大限に発揮できるような形で、防災公園における樹木の活用というものも考えていっていただきたいと思います。ちょっと時間がないので、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-035"},{"speaker":"稲川委員","kind":"質問・要望","question":"３２５ページ、住宅・建築物耐震化支援事業に関連して、ちょっとページが前後しますが、３２３ページの密集住宅市街地整備促進事業について、３０１ページの細街路拡幅整備事業について、３１９ページの市街地整備事業費の大井町駅周辺の整備について、お伺いをいたします。八潮向けだという話はお伺いしているんですが、改めて、この相談窓口を設置した経緯。","respondent":"柏原住宅担当課長","answer":"実際に住み替えをした実績等々ですけれども、大井林町の高齢者住宅は住み替えで枠を持ってありますけれども、住み替え相談センターの相談の中から、現在のところは８件、住み替え予定になっているところです。","voiceIndex":87,"id":"exchange-036"},{"speaker":"稲川委員","kind":"質問・要望","question":"しかしながら、木造密集市街地においては、その性質は全く違うものでありまして、やっぱり八潮と木造密集市街地を一緒にとらえた相談窓口では、私はいけないのではないか、別々につくるべきだと思うんですが、その辺、区のお考え。多分、密集整備の担当と住宅の担当で分かれると思うんですが、各々の課長から思いをお聞かせいただきたいんですが、よろしくお願いします。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"ただ、政策の喫緊の課題となっている部分が、八潮にはございましたので、まずはこちらからということで進めさせていただいているところです。こういった住み替え窓口、どういうふうにやっていくのかという点につきましては、やはり先進的に八潮で事例があるということで、こういった事例を参考にしながら。","voiceIndex":89,"id":"exchange-037"},{"speaker":"稲川委員","kind":"質問・要望","question":"新たに相談窓口をつくるというのも、またいろいろな費用な面でもかかってくると思いますので、そこはぜひ、一体的に考えていただいて、逆に言えば、今、八潮にあるのであれば、その支店という言い方がいいのかどうかは別にしても、荏原地域にも同じような流れで、地域の不動産関係の方と連携をとって窓口をつくるべきだと、これは要望も含めて、そこのところで、もう一言何かあれば、お願いします。","respondent":"品川防災整備担当課長","answer":"そういった面は、地域の状況によって、いろいろ総合的に考えて、今後検討していきたいと考えています。","voiceIndex":92,"id":"exchange-038"},{"speaker":"稲川委員","kind":"質問","question":"３２３ページ、密集住宅市街地整備促進事業について、お伺いいたします。地域における防災広場の必要性が、ほんとうに伺えるところです。このことから、今後の防災広場の整備について、お伺いをしたいと思います。この数年、そして、平成２４年度においても、多くの防災広場が整備されると思います。具体的に言いますと、私の近くだと二葉三丁目でしょうか、そこは全く公園がない。","respondent":"品川防災整備担当課長","answer":"委員おっしゃるとおり、二葉三丁目地区、または、火災危険度で今ナンバー１とされています豊町五丁目とか、そちらについては、区としても防災広場を何とか設置していきたいと考えております。","voiceIndex":94,"id":"exchange-039"},{"speaker":"稲川委員","kind":"質問・要望","question":"それに関連してもう１点、二葉公園の北側というのでしょうか、暫定整備をした７５０m2ぐらいの土地があります。約１年が経過しております。せっかく空地を確保できたわけですので、積極的に事業を進めていただきたいのですが、今後、どうなるのか、どのようにコーディネートするのか、どこの代替地として利用するのか教えてください。","respondent":"品川防災整備担当課長","answer":"こういったところを、まだいろいろ検討しながら、どうやって使っていくかということを、現状としては、考えているような状況です。","voiceIndex":96,"id":"exchange-040"},{"speaker":"稲川委員","kind":"質問・要望","question":"整備をするその７００m2近くのところ、そこに隣接をした土地が、ご存じのように、非常に袋小路というか、突き当たりになってしまっていますので、もしそこの整備をするときにも、一体的に考えていただいて整備をするか、もしくは道路の出入り口をつくるとか、道路付けをしっかりとしていただきたいと思います。そこを簡単に、ご答弁をお願いします。","respondent":"品川防災整備担当課長","answer":"こちらは、委員おっしゃるとおり、まちの状況、それからどのような手法で考えていったらいいかというところも、十分に検討しまして、そういった状況によりまして、道路の整備だとか、そういった方向も考えていきたいと考えています。","voiceIndex":98,"id":"exchange-041"},{"speaker":"稲川委員","kind":"質問","question":"３０１ページ、細街路拡幅整備事業について、お伺いいたします。あわせて、これはちょっと款はそれるんですが、みどり豊かなまちづくり助成事業で、昨日ですね、平成２２年度中の助成の中で、２２件が生け垣助成ですか、細街路の拡幅整備とあわせ技で行っております。この２２件という件数、整備地域、新防火地域別に教えてください。","respondent":"中村建築課長","answer":"ほとんどは自主施工によるものかと思います。それから、新防火地域の件数なんですけれども、平成２１、２２、２３年度で、それぞれ２７、２２、１６件です。","voiceIndex":100,"id":"exchange-042"},{"speaker":"渡部委員","kind":"確認","question":"３２７ページ、午前中に藤原委員のほうからありました、耐震シェルターのことで、ちょっと確認します。いろいろレスポンスがあって、お問い合わせがあったということで、今回、この予算書でも３２件という強い数字を打ってありますけれども、一つ確認は、知的財産の部分、パテント、意匠、商標登録等をされているのか、どうなのか、ちょっと確認。","respondent":"品川防災整備担当課長","answer":"品川シェルターにつきましては、幅広く広めていきたいということもありまして、商標登録のほうは、してございません。","voiceIndex":104,"id":"exchange-043"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり模倣品といいましょうか、似たようなものが出て、品川シェルターという名前だけ先行して、何かあって、つぶれたなんていうことにならないように、やはり実証結果とか、品川区は持っていますから、その辺しっかり取って、区内業者、もしくは他の自治体等から問い合わせがあったときに、すぐにお出しできて、正確なものができるように努めていただきたいと思いますが、その辺はどうでしょうか。","respondent":"品川防災整備担当課長","answer":"その辺は、開発した日本大学と、施工していただいた業者ともいろいろ話し合いをして、今後、どういうふうにしていったらいいかということは、検討してまいりたいと思います。","voiceIndex":106,"id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"３１７ページです。公園用地取得費、５億円。見た目でばっと追っていったときに、５億円、わあすごいな、５億円の公園の土地を買ってくれるんだなんて思っていたんですが、お話をちょっと伺ったときに、予定地は特段決まっていないということだったんですが、どのような考えで５億円と挙げられているのか、教えてください。","respondent":"武藤都市整備下水道課長","answer":"しかし、現時点では適地がないことから、用地の情報等を見ながら検討をしている状況です。","voiceIndex":108,"id":"exchange-045"},{"speaker":"渡部委員","kind":"提案","question":"ある程度つくって、新たな提案とか受けてないと思うんですが、今後また用地がありましたら、そのような考えで進めるとなったときに、新たに子どもたちを集める、もしくは学校なのか、すまいるスクールなのか、児童センターなのか、そのようなところで大がかりにまた子どものアイデアを活かした公園をやっていただいて、もっと啓発をしていただきたいと思うんですが、その辺はどうでしょうか。","respondent":"武藤都市整備下水道課長","answer":"ただし、このアイデアをすべて活かす公園につきましては、やはり一定の広さが必要になることから、我々としましては、引き続き、そういった適地が見つかるように、用地情報等、幅広くアンテアを張りながら、今後も検討してまいりたいと考えています。","voiceIndex":110,"id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"子どもたちが笑顔で遊んでいる、そこに高齢者の方々も一緒になって、その場所で同じ時間を過ごしているというところがたくさんできるといいと思いますので、ぜひ、適地を見つけて、５億円を使ってほしいと思います。それから、ページ数がちょっと当てはまらないのかもしれませんが、一般質問でもありましたが、空き家の対策についてお伺いしたいと思います。把握されていれば、どれぐらいあるのか。","respondent":"柏原住宅担当課長","answer":"さまざまございまして、例えば建物が倒れそうになっているとか、危ないというときには、そういう通報を受けた後に行って、建築課のほうで調査するとか、防犯上危ない等々がありましたら、パトロールであるとか、警察や消防との連携等々でございまして、こういったことで。","voiceIndex":112,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問・要望","question":"１件ご相談があったときに、深くお伺いしたときに、やはりそのご家庭の複雑な事情で、ご主人が亡くなった。ただ、亡くなったのは実は４０年も前だった。だけれども、その反面やはり、地域からしてみると、そこが老朽空き家になっているのは間違いなくて、何をどういうふうに手を打っていったらいいのかわからないというときに、地域に対して、行政としてできるアドバイスというのがあれば、教えてほしい。","respondent":"柏原住宅担当課長","answer":"そういったところをご紹介しながら、あとは弁護士であるとか、個別の対応にはなってこようかとは思いますけれども、そういったところを中心にお話をすることになろうかと思います。","voiceIndex":114,"id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"先ほどのご答弁の中で、消防、警察等ともあわせて、防犯上のパトロールを続けていただけるということですので、ともかくまず一番身近な自治体として、やることをやっていただいていると思います。これからも、それを続けていただいて、何か方策があれば、新たな方策を、国等々を絡めて練っていただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-049"},{"speaker":"山内委員","kind":"質問","question":"３１８ページ、都市開発費の中から、主に再開発について伺います。そういった中で、再開発に対する行政の関わりを、改めて伺いたいと思います。それから、予算書を見ていますと、駅周辺の再開発といったことが多く出ております。このＪＲを含めた鉄道事業者の再開発に関する際の関わりといったものを、どんな感じでされているのかという点を、伺います。","respondent":"三宅都市開発課長","answer":"さらに進みますと、権利返還計画ということで、従前の資産を、どういう形で返還するかという、これも都知事の認可です。そして、一体的な事業になってまいりますと、敷地の共同化というようなケースでは、補助支援をする場合もあります。","voiceIndex":118,"id":"exchange-050"},{"speaker":"山内委員","kind":"質問","question":"今、品川区でも、大崎駅周辺やそういったところで開発がされているといった、比重がそちらへ移ってしまうと、これはちょっと問題かなというところもあるので、さっき私が申し上げた、経済的な効果があるということを考えますと、今、区内にある駅の周辺をしっかりやるということが、いろいろな意味で、やはり効果が生まれる、そんな思いがしたので、そのあたり、新しい駅ができるということへ。","respondent":"山崎マスタープラン担当課長","answer":"と申しますのは、特定都市緊急整備地域という形で、品川駅周辺が指定のエリアになっています。そのエリアにつきましては、それぞれの田町の新駅の部分も含めたプロジェクトを強調しつつ、品川駅周辺のまちづくりを進めていこうと、こういうような観点で進めているものです。","voiceIndex":120,"id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"そうなると、何を申し上げたいかというと、いわゆる動線の確保をどう取るかということなんです。ですから、今からＪＲのほうに、これはＪＲ東海だと思うんですが、しっかりと、今、品川区でこういった機運が高まって、これからやろうとしているんだといったことをアピールしていかないといけないと思います。そのあたりを、リニアの新駅と結びつけて、どのように考えているのか、伺います。","respondent":"山崎マスタープラン担当課長","answer":"現在の品川駅周辺のまちづくりにつきましては、その地域の基盤整備も含めまして、東京都、あるいは港区、品川区、それからＪＲも含めた検討会ができています。その検討会の中におきましては、先ほど申し上げたような品川区としての考えを、発言しております。","voiceIndex":122,"id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２９７ページの街路灯建替事業について、関連してお伺いします。その後、いろいろ伺ったところによると、試験設置はされましたけれども、その後の設置はされていないというふうに聞いております。その辺の状況について、教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"青色防犯灯につきまして、平成２２年１０月４日から平成２２年１１月１７日にかけて、試験設置して調査を実施してきました。場所なんですが、桐畑地下道、南大井六丁目、八ツ山アンダーパス北側歩道、北品川一丁目、それから、区道上の街路灯、東大井三丁目です。","voiceIndex":125,"id":"exchange-053"},{"speaker":"武内委員","kind":"提案","question":"実は、この件については、平成１８年の予算特別委員会等で、私どもの先輩議員が、静岡県磐田市を視察しまして、防犯の観点から提案させていただいた経緯もありましたので、期待をしていたんですけれども、今、お話しいただいた限りだと、薄気味悪いとか、薄暗いということでした。こういうことについて、区のほうは何かつかんでいますでしょうか。","respondent":"稲田道路公園課長","answer":"私どものほうでは、踏切で青色灯で自殺が激減したというような情報は、ちょっと残念ながら、得てないんですけれども、先ほどの青色の実験結果、科学的実証がされれば、その辺を考えることもできるというところでございまして、踏切の安全性は、区道におきましては。","voiceIndex":127,"id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"私も、そういうお声をいただいたので、いろいろ自分でわかる範囲で調べてみましたら、実は、ＪＲ西日本が、２００６年１２月から２０１１年３月末まで、９４カ所で踏切に青色灯を設置したと。原踏切は、私も１０年ぐらいの間に、やっぱり同じようなことが起きているということを知っています。そういった意味で、例えば、こういったことをＪＲのほうに訴えていくというようなことは、いかがでしょうか。","respondent":"稲田道路公園課長","answer":"ＪＲのほうでそのような実績があるというお話ですので、その辺は、ＪＲのほうに、どのような状況で、どのようなことで設置したのかという調査等をやっていきまして、青色については注視して、研究していきたいと思います。","voiceIndex":129,"id":"exchange-055"},{"speaker":"武内委員","kind":"提案","question":"これは質問ですけれども、４月６日から１５日まで、春の交通安全運動が始まりますけれども、これはちょっと趣旨が違うかもしれませんけれども、交通安全協議会の中に、いろいろな構成団体が、警察だとか、消防とかさまざまな構成団体がありますけれども、その中に鉄道事業者は入っていないんですけれども、これはやっぱり理由があるんでしょうか。それをあわせて教えてください。","respondent":"藤木交通安全担当課長","answer":"交通安全協議会のほうには、特に委員となっておりませんが、毎年度の交通安全計画を策定する交通安全対策会議のほうには、鉄道事業者も委員として入っておりまして、年間の踏切も含めました安全対策など、計画を立てて一緒に策定しているという状況です。","voiceIndex":131,"id":"exchange-056"},{"speaker":"武内委員","kind":"質問・要望","question":"決して入ってないからどうのこうのというわけではないんですけれども、こちらからすると、入っていないので、もしかすると、あまり鉄道事業者と交通安全についての連携が図られてないのかなと、ちょっと危惧したものですから、やはり通学路の中には踏切もあるでしょうし、それに付随したところもあると思いますので、ぜひ、連携を密にとって、先ほどのことは、鉄道のほうとも連携をとっていただきたい。","respondent":"稲田道路公園課長","answer":"私ども、昨年度の実施結果におきましては、効果がそれほどないですので、他の自治体等の情報も得ながら、その辺は研究していきたいと考えています。","voiceIndex":133,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３０３ページの私道整備事業と、それから、３２３ページの密集住宅市街地整備促進事業について、お聞きしたいと思います。それから、今年度、申請された件数のうち、住民が１割負担しなければならないという２.５ｍ未満の私道が何件あったのかということ。それから、２.５ｍ未満の私道が私道のうちで何割ぐらいを占めるのかということについても、お聞かせいただきたいと思います。","respondent":"中村建築課長","answer":"今年度申請がありました４９件ですけれども、そのうち９割助成、つまり地元が１割負担しましたのが６件です。それから、地元が負担する道路の割合ですけれども、全体の話をしますと、申請の数から見合って、大体１割から２割ぐらいになっているのかなと考えております。","voiceIndex":136,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１、２割ということは、これは、申請の件数からは割り出せないのではないかと思うんですよ。そのときの議事録を読みますと、既に２３区中８区が、幅員の要件をなくしているということで述べられていたんですが、２３区の中で、現在、幅員の要件をなくしている区が幾つぐらいあるのか、わかったら教えていただきたいと思います。とりあえず、そこのところでお願いします。","respondent":"中村建築課長","answer":"２３区内の１００％補助をしている区ですけれども、今、私どもで把握しておりますのは、港区のみ１区だけです。","voiceIndex":138,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、品川区でも、２.５ｍ未満でも、全額区の負担でできるように、そして、なかなか合意ができなくて、ほんとうに１０年以上そのままになっているという道路も、地域の中には残されていて、ほんとうに何とかしたいという思いがあるんですけれども、ぜひ、区の負担で整備できるように求めたいんですけれども、いかがでしょうか。","respondent":"中村建築課長","answer":"ただ、同意を取るうえにおきまして、やはりこの私道の所有者が１名だけということは少なくて、複数の方が共有しているというようなこともございまして、こういった関係で、所有者を調べたり、あるいは関係権利者の方々に説明に伺って、同意を取りやすく協力をしていくという形で。","voiceIndex":140,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"３２３ページの防災広場整備工事費について、お尋ねいたします。質問するうえで、他の款に話が入ることもありますが、関連しているので、申しわけございません。この上に仮設トイレを設置するということで、この便槽の中をのぞきましたら、水が３分の２ぐらい入っておりまして、このまま使うのか、水を抜く装置がついているか、それが疑問だったんですが、まずその単純な疑問をよろしくお願いいたします。","respondent":"稲田道路公園課長","answer":"順次たまっていくというものです。それから、水の入った原因なんですけれども、マンホールのふたがありますが、開け閉めするために、ふたのところにやっぱり若干の隙間があります。そこを雨水等が伝って入ってきているです。","voiceIndex":145,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"この便槽は、防災広場以外にも、学校など他の施設などにもつくられていると思うんですが、ほかの学校施設等では、開けたら上まで水がいっぱいあったというお話も聞きました。このポンプがなければ使えない。そういう意味で、パッキンの耐久性なども、ちょっとお伺いしたいんですけれども、その辺はどうなんでしょうか。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"マンホールトイレなんですけれども、基本的には、そのように満杯になるほどたまるというふうには考えてございませんでした。何か原因があるのではないかというところで、今後、追究していきたいとは思っております。ちょっと原因がわかりませんので、大至急原因を追究いたしまして、改善方、検討してまいります。","voiceIndex":147,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"ごめんないさい、款は違うんですが、学校では、平成２２年度では５７個とかいう数字が出ておりましたけれども、どのぐらいあるのか。具体的に、またはちょっと対策をお伺いしたいけれども、それを調べて、変えるということですか。ちょっとその辺のところを、もうちょっと詳しくお願いいたします。","respondent":"岩田都市環境事業部長、稲田道路公園課長","answer":"収容場所になっている学校もありますし、防災活動広場もありますし、いろいろなところに設置しておりますので、一度、私どものほうで、実態調査を全カ所やりまして、不備があったところはすべて直してまいります。防災広場、公園等におきましては、数なんですけれども、１６公園、７８基あります。","voiceIndex":150,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"かまどベンチは使ってみないとわからないので、耐久性とか、例えば大地震がきて壊れてしまっては、何も使えないと思うので、そういうところは検証済みなのか、どうかお伺いしたいです。","respondent":"稲田道路公園課長","answer":"かまどベンチ、壊れているですが、これもちょっと大至急原因を調べまして、対応したいと思います。","voiceIndex":153,"id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"こういうお話なんですけれども、チェックの報告は受けているはずなんですよね。そういう連絡等のカリキュラム等はないのか、お伺いしたいので、お願いいたします。","respondent":"稲田道路公園課長","answer":"今回のこの件につきましては、報告が入ってございませんで、大変申しわけございません。巡回点検、毎日、回っておるんですけれども、ちょっと見逃したです。以後、気をつけたいと思います。","voiceIndex":157,"id":"exchange-065"},{"speaker":"吉田委員","kind":"確認","question":"続きまして、街路灯管理費なんですが、２９７ページをお願いいたします。電気料なんですけれども、確認の意味でお願いいたします。平成２３年度が１億１３５万円から、平成２４年度が９,５００万円に、マイナス６３５万円になっています。そして、照明灯明るさ検証なんですけれども、新規ということで、どういう事業なのか、この検証によって、どうしていきたいのか、方向性をお願いいたします。","respondent":"稲田道路公園課長","answer":"照明灯明るさ検証におきましては、今回、震災等もございまして、そのきっかけで節電をやっていこうというところで、夜の街路灯、あるいは公園灯のあり方、その辺を考えていきまして、人感センサー、通常は５０％の明るさでついているんですが。","voiceIndex":159,"id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"明るさの検証なんですけれども、やはり地域の方々によく聞いていただきまして、自転車に乗っている方、または歩いている方、高齢者、子どもがいらっしゃる方に、ご意見をぜひ聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"二つ目の質問が、２９４ページ、道路維持費、そして、２９７ページ、今の街路灯、飛びまして、３２９ページの分譲マンションの管理支援ということで、４点、端的に聞かせてください。最初に、工事請負費と原材料費、二つ、節のところに区分をしてありますけれども、そもそも工事請負費と原材料費というのは何なのか、教えてください。","respondent":"稲田道路公園課長","answer":"原材料費ですが、日常の維持管理の中で点検や維持修繕しておるんですが、そのときに使うモルタルとか、アスファルトの簡易なもの、そういう原材料を入れているものです。","voiceIndex":163,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"今の説明をいただきました、道路公園課長ですから、道路ということですが、この項目全部、最後のページ、すなわち土木費の最後のところまでいくと、道路、橋梁、河川、そして公園ということであります。２９２ページから追っていきますと、この項目は全部で１２項目あります。そのうち、原材料費と工事請負費が抱き合わせ、二つになっているのが４項目、工事請負費だけになっているのが８項目あります。","respondent":"岩田都市環境事業部長","answer":"今は、道路も公園も巡回点検で、これは区内業者なんですけれども、トラックで巡回をしておりまして、そのときに見つけた簡単な補修工事に使う材料費、この原材料費の中から購入して支給をしているです。","voiceIndex":165,"id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"政策的なものになるので、ちょっと質問が適当かどうかわかりませんけれども、昔からの名残ということで、原材料費で、比較的簡易な工事については、材料費が計上されているということですけれども、ここの二層構造、二つになっている、これはすべて請負に入れて一本に絞るということ、工事請負の項目に入れるというのは、私は建築とか、そういうのは素人なのでわかりませんけれども。","respondent":"岩田都市環境事業部長","answer":"請負契約でも可能は可能なんですが、これを請負契約で、メンテナンス契約というんですけれども、年間単価契約で業者にやらせますと、区内業者が一定のストックを自社で保有をしながら、持ち歩かなければならないということで、区内の業者は小さな業者が多いものですから。","voiceIndex":167,"id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"この件に関しては、土木工事のみならず、区内業者の発注ということ、いろいろな経済的なものも含まれているということの理解でよろしゅうありますでしょうか、お願いします。","respondent":"岩田都市環境事業部長","answer":"他の施設管理の方法は、ちょっとここでは申し上げられませんけれども、道路、公園、河川、こういったものの維持補修については、常にこういう二通りのやり方を使い分けながら維持管理をしているです。","voiceIndex":169,"id":"exchange-071"},{"speaker":"大沢委員","kind":"質問","question":"そもそも道路において、平成２３年３月１８日に、東京都で緊急輸送道路というか、災害時の道路の耐震というか、道路の強度を増しましょうという条例が公布されましたけれども、この中を見てみますと、おのおの舗装道がありますけれども、簡易舗装道をはじめ砂利、コンクリート平板なんていうのは、ここのところは弱いと思うんですけれども、東京都との兼ね合いもあろうかと思いますけれども、区独自で。","respondent":"稲田道路公園課長","answer":"区の道路におきまして、ある程度交通量のあるところ、それから、そうではないところといろいろあるんですけれども、地盤の支持力等を検討してやっておりますので、舗装等の構造は大丈夫だと認識しております。","voiceIndex":171,"id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"品川区では、八潮のほうの液状化は免れたということ、荏原地区は台地ということなんですけれども、そこに乗っかっている道路ということで、いろいろと区によっても、道路そのものを、造成地盤の違いはありますけれども、今、非常に騒がれております、４年以内に大地震が起こるだろう確率が７０％以上ということで、報道等々でありますけれども、この件について、道路を含めて、今後、道路政策のあり方。","respondent":"稲田道路公園課長","answer":"ただ、それをやることが、果たして今、いいのかどうかというところで、浦安市では、専門家も入れていろいろ検討しているようですけれども、現在のところはまだ、液状化に対する答えというのは、私どものほうで考えておりません。","voiceIndex":173,"id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に移ります。街路灯ですけれども、これはもう単刀直入に聞きます。下が傷むんです、傷んで穴があいていたりとか、維持をしていても、ここだけは防ぐことができないような事象だと思いますけれども、これについて、何か対策を既に打たれているようなことがあったら、教えてください。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"委員おっしゃるとおり、犬とかのオシッコの問題ですが、大変問題です。私ども、年に１回、全体的な街路灯の点検調査をやっております。そういう中で、根元のほうを金づちでたたいたりとか、そういうふうなチェックの方法をしております。今、課長が申しましたのは日常点検とか、そういうレベルの話でして、過去に、犬のオシッコだけではなくて、雨水や何かで街路灯が転倒したという事故がありましたので、それ以降については、柱の一番道路に面するところから上１ｍまで。","voiceIndex":175,"id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"それにもかかわらず、周りをペットボトルで囲んで防いだりとか、町場の中ではいろいろ工夫をされている人がおりますので、そこのところもお酌み取りいただきながら、やはり排泄物というのは酸が多いので、尿酸というぐらいですから、普通の水とは違って非常に溶かしやすいです。ですから、そこのところは、すみませんけれども、検証、検討を重ねていただきながらやっていただきたいと思います。","respondent":"柏原住宅担当課長","answer":"築４０年以上ですけれども、ただいま、住宅市場動向調査というのをやっておりまして、その結果を整理しています。細かい数字につきましては、ちょっと今、手元にございませんので、何棟というのは、ちょっと今、お話しすることはできません。","voiceIndex":178,"id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"高度経済成長が終わり、そしてまた、団塊の世代の人口増加とともに団地が建てられ、大阪府の千里ニュータウン、あるいは多摩に見られる、各地のニュータウンが、今、人口減少とともに老朽化し、またスラム化しているのが現状であると考えています。この予算の中で、直近においては、どのように対応され、また考えていかれるのか、ご披露いただきたいと思います。","respondent":"柏原住宅担当課長","answer":"今後の対応ですが、品川区は、４月から東京都のほうから事務移管ということで、マンションの建替えの円滑化等に関する法律で事務が移管されてまいります。","voiceIndex":180,"id":"exchange-076"},{"speaker":"大沢委員","kind":"意見","question":"本予算の中で、新規事業として、木造一戸建て、あるいは木造アパートの除却費用に対して、３分の１、５分の幾つ助成するということでありますけれども、先ほど、マンションの耐震化ということはありましたけれども、非常に大きな金額にはなりますけれども、老朽化対策に向けた、マンションに対しての除却費用の補助というのも、今後、促進のために大事な問題になってくるのではないかと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-077"},{"speaker":"大倉委員","kind":"質問","question":"私からは、３２１ページの武蔵小山駅周辺地域整備事業に関連して、お伺いします。２カ所バス停がございまして、その１カ所、五反田行きのほうのバス停にだけ傘がないというか、そこだけ雨にぬれるような形になっておりますが、そこがどうしてそうなっているのか、計画では、もともとなかったのか、それとも何か理由があってなくなってしまったのか、そこについて、ちょっとお伺いできればと思います。","respondent":"井浦土木管理課長、岩田都市環境事業部長","answer":"武蔵小山駅のロータリーのところの２カ所のバス停ですが、区道の上を道路法の占用許可ということで、鉄道事業者に貸しています。その後、東急バスのほうから、もう１路線欲しいということで、区は、そのときに現在の雨避けを東急の費用で延長するのを条件に許可をしたわけですけれども、その後、２年経っておりますけれども、東急は履行しませんので。","voiceIndex":184,"id":"exchange-078"},{"speaker":"大倉委員","kind":"質問・要望","question":"３０３ページの私道整備事業について、お伺いしたいと思います。先ほどもちょっと質問がありましたが、この考え方について、ちょっと教えていただきたいと思います。私道整備なんですが、優先順位があるのか。その視点として、安全性とか、防災とか、そういったさまざまな視点があると思うんですが、その中で、どういった優先順位があるのか、基準があるのか、そこを教えていただきたいと思います。","respondent":"中村建築課長","answer":"どういったところかと申しますと、陥没などが著しい場所、あるいは、枡のふたが割れて落ちて、足が挟まれてしまうような、こういった緊急性が非常に高いものは早急に優先してやるという形です。","voiceIndex":187,"id":"exchange-079"},{"speaker":"大倉委員","kind":"質問","question":"私道は、聞いているところによると、区道よりも長いというお話も伺ったことがある中で、やっぱり、公道とつながっている私道に関しては公共性が高いので、ぜひ、安全性という部分でも、利用しやすい環境づくりが必要なのではないかと考えています。","respondent":"中村建築課長","answer":"民有地の使われ方もさまざまですので、建物のすき間なのか、そういった微妙なところもありますので、そういったものまで含めると際限がなくなってしまうというところもあります。この幅員要件によって、１割負担というのは、今のところ、継続をしていきたいと考えております。","voiceIndex":189,"id":"exchange-080"},{"speaker":"大倉委員","kind":"質問・要望","question":"私道の整備ですが、区としては、基本的に申請をされて、受け付けて、整備をするという形ですが、こういった道の方には、ぜひ早めに整備の申請を出していただきたいとか、そういった考えがもしあれば、教えていただきたいと思います。砂利道とかさまざまな道があると思いますので、どういった道には、ぜひ早めの整備をお願いしたいか、お聞かせいただきたいと思います。","respondent":"中村建築課長","answer":"ぜひ申請いただきたいのは、まず、足のご不自由なお年寄りですとか、あるいは車いすなどを使われている方が、その道を使っている場合で、傷んでいるようなときには、ぜひとも、私どもに申請をいただければと考えております。","voiceIndex":191,"id":"exchange-081"},{"speaker":"大倉委員","kind":"質問・要望","question":"私道の整備、成果があれば、生活環境や安全性の確保、都市環境が向上するという思いがありますので、ぜひとも、今後も、計画的にやっていただきたいと考えています。その中で、最後にちょっとお聞かせいただければ、今後もしっかりとした整備を進めていく中で、予算もどんどん増えていっておりますので、その熱い考えがあれば、最後にお聞かせいただきたいと思います。","respondent":"中村建築課長","answer":"そういったところで、ほんとうに困って申請をいただいているものと考えておりますので、今、申請をいただいた分につきましては、これはもう必ずやらせていただくということで、またこれからも、そういった公道、私道を問わず。","voiceIndex":193,"id":"exchange-082"},{"speaker":"浅野委員","kind":"質問","question":"３０３ページの、今、質問がありました私道整備事業、３０９ページ、公共溝渠整備事業と、雨水流出抑制推進事業、時間があれば、３１７ページの旧荏原平塚中学校跡地多目的広場整備工事について、お伺いします。この理由について、お伺いしたいと思います。平成２４年度は３件で、１件が継続となっておりました。この内容について、教えてください。","respondent":"中村建築課長","answer":"排水ですけれども、こちらの予算といたしましては、来年度行うべき計画の中で、排水工事の内容が多くなっているのが理由です。","voiceIndex":196,"id":"exchange-083"},{"speaker":"浅野委員","kind":"質問・要望","question":"件数からしても、何か中身が違うのではないかなという感じがしたので、その点、変化があれば、後で、再度教えていただきたいと思います。私道で申請されているけれども、道路になっていないところもあるやに聞いております。私道というのは、一体、区内に何件という言い方が適切かどうかは不明ですけれども、総延長とか、数字がわかれば、教えてください。","respondent":"井浦土木管理課長、中村建築課長","answer":"私道の延長につきましては、品川区は現在、１０万５,１０８ｍ。面積数にしますと、２６万５,５７８m2と、このように把握しています。それが、排水に限らず、舗装でもそうですが、毎年、規模が大分上下するというところがありますので、こういった大きな開きになったかと考えております。","voiceIndex":198,"id":"exchange-084"},{"speaker":"浅野委員","kind":"質問","question":"私道も、勘定すると１０５km余もあるということですけれども、先ほどの、地域の方も存じ得ない、ほんとうはここが私道に申請をされているけれども、知らなかったというケースも、私も聞いております。それとも、やはり個人が家を建て替えるとか、そういうときにしか関与できないのか、そこら辺についても、お伺いできればと思います。","respondent":"中村建築課長","answer":"私道を整備していただく機会というのはいろいろあるかと思いますが、一つは、建築確認申請のときに、セットバックをしていただいたりする場合、舗装の整備が絡んでまいります。","voiceIndex":201,"id":"exchange-085"},{"speaker":"浅野委員","kind":"質問","question":"公共溝渠整備事業ですけれども、今回、２カ所、大井と二葉の２カ所が出ていたんですけれども、これも、防災計画を見たら、延長は７０kmぐらいあるというふうに聞いております。この総延長を、再びお伺いしたい。もしくは、名前はあるけれども、どぶでなくなったというのでしょうか、そういうものがあれば、どのぐらいの距離があるか、教えてください。","respondent":"井浦土木管理課長","answer":"延長につきましては、１万１,９４６ｍということで把握しています。それから、いわゆる暗渠と申しまして、ふたがありまして、その下に雨水がたまるというようなものについて、現在、把握しているのが１２路線ございまして、延長で１,０６０ｍです。","voiceIndex":203,"id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"利用されていないのが、どれぐらいなるか。すべて利用されていると考えていいのか、どうか。もし利用されていないところがある場合には、どのような役立て方があるのかということについて、お伺いします。この公共溝渠、通路ともなっておりまして、ふだん使われている部分も多いかと思いますけれども、こちらの整備の基本的な考え方、ローテーションでやっているのか、壊れたらやるのか、お伺いします。","respondent":"稲田道路公園課長","answer":"旧公共溝渠なんですが、例えば来年度、２カ所やるんですけれども、現在、ふたがかかっておりまして、その下を水が流れるような構造になっているんですけれども、現在は水が流れていないということで、埋めて通路化する。","voiceIndex":205,"id":"exchange-087"},{"speaker":"浅野委員","kind":"確認","question":"昔使われていたけれども、使えなくなったというところもあるかと思いますが、ふだん、生活通路というような形で、これからも区民の方に影響のないようにといいましょうか。それから、平成２４年度の予算も出ておりますけれども、事業としての目標値というのは、果たしてあるのかどうか、これをお伺いしたいと思います。区としては、どれぐらいまで広げていこうと考えているのか、教えてください。","respondent":"武藤都市整備下水道課長","answer":"目標についてですけれども、こうした浸透を含む浸水対策につきましては、東京都を含めて総合治水対策ということで目標を定めておりまして、一定程度、具体的には、降った雨の１割程度を浸透させていくという考えのもと、事業を進めているという状況です。","voiceIndex":207,"id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"街路灯管理費は、大井町のきゅりあんの前のデッキと、大井町の線路沿いに坂があるんですが、あそこの街路灯が、朝７時半ぐらいでしょうか。明るくなってからも点いていたということで、町場の方から「税金のむだ使いではないか」と、「明るくなったんだから電気が消えるようにしてくれないか、俺は大田区民だけど」というふうに言われたんですけれども、この街路灯のつき方の状況を教えてください。","respondent":"稲田道路公園課長","answer":"大井町駅東口ペデストリアンデッキの部分なんですけれども、一般的な感知報知式で点けたり消したりというものです。あそこは、自動点滅器というものを壁面につけておりまして、明るさを感じて、消えるというようなシステムです。","voiceIndex":210,"id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"７時半になってもついていたという状況は、そのセンサーの問題だったのでしょうか。ほかの街路灯も、そういった形で起き得ることなのでしょうか。","respondent":"稲田道路公園課長","answer":"ほとんどの区の街路灯が、この自動点滅器というもので行っておりまして、ほかでも、自動点滅器のセンサーが汚れたりすると、あり得るです。","voiceIndex":212,"id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"ほかの街路灯、センサーの汚れのチェックでしょうか、せっかく多くのところで節電をしたり、省エネをされているわけですので、センサーの汚れを定期的にチェックするようなことは、やられているのでしょうか。","respondent":"稲田道路公園課長","answer":"巡回の点検作業班がおりまして、そちらで、昼間つきっ放しのところはよくわかるんですけれども、そういうものがありましたら、その周辺をチェックしてみる、同じようなことがないかチェックしてみるという具合で、巡回点検の中でチェックしています。","voiceIndex":214,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"今後も、節電や省エネの状況から、街路灯については必要なチェックだと思いますので、万全にお願いしたいと思います。次に３１５ページの、公園・児童遊園維持管理費なんですが、天王洲公園、東品川公園、品川南ふ頭公園に駐車場があるんですけれども、その管理運営の仕組みと、その料金が、どのように区のほうに入ってくるのか、契約の内容等を含めて、ご説明いただきたいと思います。","respondent":"井浦土木管理課長","answer":"ただいまの三つの公園につきましては、都市公園法に基づきまして、設置管理許可という制度の仕組みを使いまして、民間の活力を導入いたしまして、利便性の向上、それから一方で、一定の歳入の確保という仕組みをとってあります。","voiceIndex":216,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"今、無料で貸し付けて、区のかわりに管理をして、その料金収入は区のほうへ、ということだと思うんですが、款があれですけれども、三つのこれらの駐車場の料金収入は、三つ合わせて幾らぐらいになるのでしょうか。そして、今、契約されている仕組みは、何年間というのでしょうか、どういったスパンで契約されているのでしょうか。","respondent":"井浦土木管理課長","answer":"契約につきましては、単年度です。ただ、どの業者を選定するかという部分につきましては、プロポーザルということでオープンに公募いたしまして、初期投資という部分の費用、あるいは耐用年数という部分もありますので、５年を区切りに運用しています。","voiceIndex":218,"id":"exchange-093"},{"speaker":"高橋委員","kind":"確認","question":"３カ所で２,５００万円。同じ民間企業が運営していると思いますが、そして、それは歳入のときにお話があったんですが、これは雑入の雑入に、たしか入ってくるということでよろしいでしょうか。その確認です。それから、２,５００万円というのは、収入全体の何対何なのか、例の健康センターの比率等も、以前、お尋ねしましたが、その辺の比率も教えていただければと思います。","respondent":"稲田道路公園課長","answer":"駐車場運営費は雑入の節、雑入です。","voiceIndex":220,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"また後ほどお尋ねするとして、２,５００万円余が区に入ってきているということですので、税外収入として貴重な収入だと思います。ですから、先ほどの比率のところで、見直しが図れる状況を働きかけていってほしいと考えています。","respondent":"井浦土木管理課長","answer":"しながわ区民公園の駐車場につきましては、シルバー人材センターに運営をお任せしているという状況です。仕組みとしましては、やはり都市公園法の設置管理許可という仕組みを使いまして、無料でお貸しいたしまして、収支については、シルバー人材センターに取っていただく。","voiceIndex":223,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"収支計算書を見せていただいたんですが、駐車場の使用料が、平成２１年度だと１,１５６万円、平成２２年度が１,１００万円、これは昭和３６年から続けてシルバー人材センターのほうに設置管理許可を与えているということですから、もう二十数年間、以前はもっと少なかったかもしれませんけれども、このような形で１,０００万円余が、１年間にシルバー人材センターに行っているわけですね。","respondent":"井浦土木管理課長","answer":"しながわ区民公園につきましては、昭和６２年に開設した当初から、シルバー人材センターに、駐車場についてはお任せするというような形で行ってまいりました。法律的な権限としましては、土木管理課です。","voiceIndex":225,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"先ほどの三つの駐車場で２,５００万円、しながわ区民公園で、１年間で１,０００万円ということなので、先ほどのお話から出ている税外収入という観点から言うと、相当な収入になってきます。スタートは、しながわ区民公園の駐車料金なんですが、そういうふうに、シルバー人材センターのほうに働きかけることはどうなんでしょうか。","respondent":"岩田都市環境事業部長","answer":"お年寄りの雇用の確保のためにシルバー人材センターにお貸しするわけですから、お金もうけのためだけであれば、貸す根拠を失い、有料でお貸しするということになってしまいますので、当分の間は、今と同じように、高齢者の方がきちっと労働していただいて。","voiceIndex":227,"id":"exchange-097"},{"speaker":"高橋委員","kind":"意見","question":"ちょっと時間があるので、最後に、先ほども、ほかの委員からもお話があったんですが、品川駅の南地域ですが、こちらの周辺の開発に関して、先ほど、マスタープランの検討のお話があったんですけれども、品川区は、駅周辺の開発にどのぐらい意気込みを持ってかかわっていくおつもりであるか、その辺のご説明をお願いいたします。","respondent":"山崎マスタープラン担当課長","answer":"何を申し上げたいのかといいますと、品川のルーツは品川の区域内にありということを、強く思っております。こうした観点で、この地域のまちづくり、新しさと歴史が調和した、風格のあるまちを目指して努めてまいりたいと、このように考えてあります。","voiceIndex":229,"id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、２９９ページ、補助１６３号線整備について、３１９ページ、大崎駅周辺地区再開発事業、それから、同じページの北品川五丁目第１地区について、お伺いします。シルバーセンターについては、利用率が高くて、地域の要望も高いし、使う頻度も非常に高い。そこら辺の見解を、まず教えていただきたいと思います。これは合っているのか、現状はどうなっているのか、教えていただきたいと思います。","respondent":"武藤都市整備下水道課長、久保田行財政改革担当課長","answer":"今の交差点につきましては、大崎のほうからきたときに右折ができないという状況もあります。歩道も非常に狭いという状況もありますので、これにつきましても、早期に事業認可を取得して整備を進めていきたいと考えております。そこの部分は、高層住宅の日影になる部分ですので、校舎や校庭等の利用には適さない土地であるという認識を持ってございまして、今後、どういう利用が可能か検討していきたいと考えているところです。","voiceIndex":232,"id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"空き地でいかないで、何かしら考えていく、校庭とかにしないというのであれば、やっぱり全区的なところを見渡していただいて、例えば、今、いろいろなところで、高齢者の施設だ何の施設だという話が出てくるのであれば、だから高齢者の施設をつくってくださいとは言わないけれども、これから３年後ぐらいの中で整備をされてくるなら、やっぱり３年ぐらいかけた中で、地域の人の意見も聞いていただいて。","respondent":"松代都市計画課長、久保田行財政改革担当課長","answer":"そういった中で、東急と構造的なものを含め、鉄道本体が行う耐震化工事と、私どもの街路事業と綿密な打合せをして、お互いに齟齬がないような調整を図って、工事を進めたいと、このように考えておるところです。その一方で、御殿山小学校の周辺は、北品川五丁目地区の地区整備計画にも入ってありますので、そうした中で、文化教育機能の充実を図るといったような指定もかかってありますので、そうした点も視野に入れながら、今後。","voiceIndex":235,"id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"意見","question":"大崎第二地域センター跡地のところは、お願いをしておきます。北品川五丁目はこれからなので、よろしくお願いします。同じ時期に広くなるというぐらいのことだけは、やっぱり区役所の前だし、それはやっていくべきだと思うんですけれども、そこだけ最後、もう一度聞かせてください。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり、鉄道事業、道路事業ということで、今現在も、十分に協議をしながら、同時期に事業を進められるよう調整を図っているところです。引き続き、調整をしていきたいと考えています。","voiceIndex":238,"id":"exchange-101"},{"speaker":"中塚委員","kind":"質問","question":"私からは、３１３ページのまちづくりマスタープラン策定費より、都市計画道路２９号線、３１号線について、伺いたいと思います。つまり、この路線がないことによる地域住民の弊害について、お考えを伺いたいと思います。それから、２９号線、３１号線の計画路線上についてですが、現在の住宅戸数、商店街の数、また、路線上にある幼稚園など、公共施設、児童遊園など、公園は幾つあるのか伺いたいと思います。","respondent":"松代都市計画課長","answer":"商店街のほうで言いますと、２９号線が、これは縦方向、横方向いろいろとかかわりがありますけれども、１０商店街です。３１号線の商店街はございません。","voiceIndex":241,"id":"exchange-102"},{"speaker":"中塚委員","kind":"質問","question":"私は、２９号線、３１号線の整備の掲げているもの、すべての人にやさしい便利で安全な交通歩行環境の整備、このものは必要だと思います。しかし、問題は、なぜそれが２９号線、３１号線なのかということです。どうしてこれが、すべての人にやさしい、便利で安全な交通なのか、私は疑問でなりません。住民の反対を押し切って進めることは間違っていると思いますが、いかがでしょうか。","respondent":"松代都市計画課長","answer":"加えて、道路幅員の広い道路をつくることで、延焼を防いで、避難する区民の方々の安全を守る、これが私どもが進める２９号線、３１号線の道路整備、都市計画道路の目的です。","voiceIndex":243,"id":"exchange-103"},{"speaker":"中塚委員","kind":"質問・要望","question":"２９号線の計画廃止を求める意見書ですけれども、ここには、区民の願いが、こう書かれています。多くの区民の生活や商業活動に多大な影響を与える都市計画道路補助第２９号線の計画を廃止するよう強く要望いたします」と。区長は、実効性ある対策と掲げますけれども、この二つの路線は、次に起きる首都直下型大震災に向けての実効性ある対策だと、そういう位置づけなのかどうか、伺いたいと思います。","respondent":"松代都市計画課長","answer":"特に先ほど来、申し上げていますように、都市防災の強化というのが、ここにきてさらに高まったですし、区長の施政方針でも、防災ということを重ねて申し上げております。私どもも、この点、さらに２９号線、３１号線実現に向けて取り組んでまいりたいと思っているところです。","voiceIndex":245,"id":"exchange-104"},{"speaker":"中塚委員","kind":"質問","question":"防災の観点を強調します。もちろん、区民の生命を守らなければならないのは、言うまでもないと思います。その防災上の理由についてですけれども、延焼を食いとめたいとの説明です。安全に、短時間に数万人もの区民を、それこそ障害者も、高齢者も含めて避難させる計画を立てなければ、生命は守れないと思うんですけれども、そういう計画をどのようにお持ちなのか、伺いたいと思います。","respondent":"松代都市計画課長","answer":"そういったことから、道路の必要性というのは強く感じているところですし、その必要性は、改めて、私どもは進めていきたいと思っているところです。","voiceIndex":247,"id":"exchange-105"},{"speaker":"中塚委員","kind":"質問","question":"結局、道路だけをつくっても、先ほど、お話したように、数万人もの区民の方々、とりわけ高齢者、障害のある方の避難計画が伴わなければ震災対策は進まないと思うんですよ。しかしながら、個別プランはいまだに一つもできておりません。そこをどう考えているのか、伺いたい。そこをしっかりと位置づけなければ、それこそ最悪の想定に対応できないと思いますけれども、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"防災観点をきちっとやると同時に、道路をつくるだけではありません、周辺の地域についても、不燃化を含めて、道路ができれば高い建物もできますし、それにより利便性がきちっと高まるといった中で、バランスを取って耐震もあわせて進めていきたいと考えています。","voiceIndex":249,"id":"exchange-106"},{"speaker":"中塚委員","kind":"意見","question":"どんなに道路を広げても、一つ一つの住宅の耐震化が進まなければ、生命は救えません。とりわけ、災害弱者の方々へは特段の支援が必要です。そこをしっかりと位置づけるべきだし、この２路線はやめるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":251,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"最初に、２９３ページの交通安全啓発費の中に、普及啓発経費ということで、さまざま書いてあります。その中に、今回、シミュレーターを利用した自転車安全教室と、それから同じく３歳児の母親交通安全教室とが新規事業となりましたけれども、どのような事業なのか、具体的にお教えいただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"通常、単なる講義的な安全教育だけですと、どうしても効果があまり上がらないということで、実際に実地訓練などもやっているわけですが、場所の制約ですとか、そういうものがありまして、なかなかできないということもあり、こういう狭いスペースでもできるものということで。","voiceIndex":254,"id":"exchange-108"},{"speaker":"山元委員","kind":"質問・要望","question":"シミュレーターは、そうしますと、個人的にというか、町会とか、自治会とか、そういう貸し出しとかは可能なのか、どうか。それから、先ほど保健センターの３歳児健診の母親とおっしゃっていましたけれども、一応、予定というか、そういう教室をやっていこうという目標があれば、教えていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"もう１点の、３歳児の母親のほうの目標ですけれども、保健センターのほうで、今のところ、見込みですけれども、計５４回程度で、２,０００名程度の方に交通安全教育ができればと考えております。","voiceIndex":256,"id":"exchange-109"},{"speaker":"山元委員","kind":"質問・要望","question":"普及啓発経費の中に、幼児用交通安全絵本７,０００部ということがあるんですけれども、実際にこれは毎年配付なさっているようなんですが、いつも、どのぐらい配付されているのか。そして、幼児というのは、大体何歳ぐらいまでの方たちに配付をしているのか、その辺も教えていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"部数につきましては、約７,０００部でございまして、区立、私立を問わず、保育園、幼稚園の３歳から５歳児全員にお配りしているものです。","voiceIndex":258,"id":"exchange-110"},{"speaker":"山元委員","kind":"質問","question":"いかに自転車の安全利用のことを徹底しようとしているのかと思うんですが、今、いろいろ絵本のお話とかされましたけれども、例えばこの五則が載っているんですが、そういうのを、例えばシールとか、ワッペンとか、自転車に張るとか、何か目で訴えて、規則を守ろうよ、みたいなことができると、もっと自転車の乗り方が変わってくるのではないかと思うんですが、その辺はいかがでしょうか。","respondent":"藤木交通安全担当課長","answer":"区のほうでも、やはりそのような形で啓発を考えております。自転車のマナーアップのカードみたいなものをつくりまして、その中に自転車の安全利用五則みたいなものを盛り込んだり、それから、各種いろいろなチラシなどにも盛り込むようにしています。","voiceIndex":260,"id":"exchange-111"},{"speaker":"山元委員","kind":"質問・要望","question":"ともかくやはり、目に訴えるしかないかなと考えています。同じページなんですが、その下の放置防止指導啓発のことで、ちょっとお伺いいたします。実は、今回、予算では６００万円ちょっとなんですが、１年前の予算は１,２００万円余、そして決算は２,０００万円余ということで、この数があまりにも違いすぎているのはどういうことなのか、ちょっとご説明いただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"平成２３年度から平成２４年度にかけまして、最初に申し上げました、駅前の放置が問題になっている駅での街頭での指導みたいなものにつきましては、撤去台数が、ここ数年減少傾向にあるということの実態を踏まえまして、来年度は曜日とか、場所を絞って。","voiceIndex":262,"id":"exchange-112"},{"speaker":"山元委員","kind":"質問","question":"人数とか、それが３分の１ぐらいに減ってしまうのですが、やり方は、そういうものは変わらなく、今までどおりというわけにはいかないと思いますが、今までどおりやれるのでしょうか。","respondent":"藤木交通安全担当課長","answer":"実態としまして、日数などが減少したり、駅数も、今までよりも減らす方向で、ただいま考えておりますので、若干、人員のほうも減少すると考えております。","voiceIndex":264,"id":"exchange-113"},{"speaker":"山元委員","kind":"質問・要望","question":"道路バリアフリー事業の中の視覚障害者用誘導ブロック設置のことで、お聞きしたいと思います。一つ質問は、去年も、設置が１００ｍと書かれて、今年も１００ｍ。しかし、去年の決算では４５０ｍ設置をしたということで、設置方法というか、これはどのように決めるのか、教えていただきたいということ。それから、ブロック１枚幾らぐらいするのか、教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"これは毎年、道路改修工事とあわせながらやっていくものです。その中で、１００ｍと計上していますが、実績としましては、維持工事も合わせまして、そのような数値が挙がってきているです。大体、１枚１万５,０００円ぐらいです。","voiceIndex":266,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、大きなところの管理体制を変えるのは難しいのかもしれないけれども、こういう事例に関しては、品川区が権限を調整して、第一義対策ができるとか、そういうふうにしていかないと、いつまで経っても、品川区はこういう案件に関しては、当該の事務所へ話を通していく、事態はなかなか改善されないということが、おそらく、この地域だけではなくて、ほかの地域でもあると思うので。","respondent":"稲田道路公園課長","answer":"管理者が違うというところで、非常に難しいところですが、現在、区のほうでも、国道であろうが、都道であろうが、現場を確認して、その管理者に強く申し入れていくというスタンスで臨んでおります。","voiceIndex":269,"id":"exchange-115"},{"speaker":"伊藤委員","kind":"提案","question":"だけれども、こちらの質問の意図としては、それを調整をとって、もちろん全部が全部できるとは思わない、だけれども、こういう事例は、だれだって避けたいわけですよ。となるならば、それこそ、東京都、国等と調整をとって、この案件については、品川区が第一義的に対応できるとか、そういう新たな行政の仕組みづくりを検討してはどうですかという提案ですので、改めて、答弁をお願いいたします。","respondent":"井浦土木管理課長","answer":"公道上の監督処分のお話ですので、道路法の規定にのっとりまして、東京都、あるいは国道を司る国土交通省と、このような案件については、区のエリアですので、区としても責任を持って、東京都、あるいは国に働きかけて。","voiceIndex":271,"id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"管理区分が違うだけであって、その問題は解決しない。それは、区議会議員として理解できる部分もあるんだけれども、同時に、区議会議員だからこそ、こういう提案をさせていただいて、縦の系列の中で権限の調整をとって、できれば、品川区の対応の中で解決できる仕組みがあったらいいなと思うんですが、もう少し、答弁をいただきましょうか。今のことを加えて、答弁をお願いいたします。","respondent":"岩田都市環境事業部長","answer":"したがって、私どもが行う場合は、福祉事務所とタイアップをして、その人個人の心の悩み、あるいは、体の悩みの解決に向けて努力をしながら、人の迷惑にならないように、生きてくださいと、こういうことで、品川区の場合はやっております。","voiceIndex":273,"id":"exchange-117"},{"speaker":"伊藤委員","kind":"質問","question":"こちらの思いは伝わったと思いますので、ぜひ、調整方をよろしくお願いしておきます。それから、次に立会川雨水放流管建設であります。改めて、これから立会川の将来構想、それから浄化等の見通し、将来的な水辺の環境整備等について、長年このことに対応していただきました都市環境事業部長にお伺いします、答弁をお願いいたします。","respondent":"岩田都市環境事業部長","answer":"その実現が、もうあと１０年ちょっとで、先が見えてきたということで、私としては非常に嬉しい思いがしております。","voiceIndex":275,"id":"exchange-118"},{"speaker":"伊藤委員","kind":"意見","question":"１０年かかるかもしれませんけれども、ゴールが見えてきたということは、地域の皆様は非常に感謝しておりますので、改めてお話をしておきます。それから、立会川は水門がないということは、地域の皆さんは非常に心配をされていますので、そのことについての見通しをお聞かせください、お願いいたします。","respondent":"武藤都市整備下水道課長","answer":"その一部を、区が連携して協力するために、受託して進めるものです。委員お尋ねの水門につきましては、洪水ではなくて、高潮、いわゆる海側から来る水を防ぐために設置するものですが、雨が降ったときに上流側から来る洪水を、まず処理しなければなりません。","voiceIndex":277,"id":"exchange-119"},{"speaker":"伊藤委員","kind":"質問","question":"計画は、確かにいろいろあるとは思うんですが、心配の種を少しでも早く取り除いていただきますように、できれば計画の前倒し等も検討していただければと考えています。津波・高潮対策に関連してでありますが、標高マップをつくって、標高の掲示板を設置する。これは、確かに正しいことなんだけれども、一面、我が党の石田秀男委員も一般質問しましたが、地域の方々にとっては不安を増強することもある。","respondent":"武藤都市整備下水道課長","answer":"あわせまして、逃げる場所として、津波の避難ビルの指定につきましても、企業と連携して対応場所を検討するなどの対策を考えていきたいと考えています。","voiceIndex":279,"id":"exchange-120"},{"speaker":"伊藤委員","kind":"質問・要望","question":"たまたまここにあるんですけれども、これで見ても、海沿いの相当部分が低いですよね、３ｍ以上４ｍ未満というところがほとんど。だから、この地域の相当広いエリアの方々に対して、まさにそのことをやっていかないといけない。これは、ぜひ区長に答弁をいただきたいんですが、ある意味、区民の生命、財産に直接かかわる話ですので、区長の意気込みといいましょうか。お願いいたします。","respondent":"濱野区長","answer":"そうしたことが、この地域にお住まいの方々に浸透していけば、いざというときは、こういうふうにすればいいんだということが頭の中に入っていれば、落ち着いて行動ができると考えていますので、そういった作業を着実に進めてまいりたいと思っているところです。","voiceIndex":281,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"２９７ページの街路樹等維持管理費。この対応をどうされるのか、街路樹の目的とあわせて、今後の対策についてお聞きします。二つ目は、３０５ページの下水道管改修事業です。あわせて、これは下水道管なので、水道管はどうするのかと、ちょっと疑問に思いました。水が出なければ、いくら下水道を整備しても、水が流れないので、使用できませんから、そちらはどういうふうに考えてますか。","respondent":"稲田道路公園課長、武藤都市整備下水道課長、品川防災整備担当課長、山崎マスタープラン担当課長","answer":"区では、約４,０００本弱の高木の街路樹を管理しております。品川区につきましては、避難所等約１８０カ所を超える対象箇所につきまして、順次、今、耐震整備を進めておりまして、平成２５年度には。その状況に応じて、避難場所を変更するような形で考えております。昨年は、そうした面で施策を打ちまして、ユニバーサルデザインの推進の中の重点事業の一つとして、おたがいさま運動の推進ということがありまして。","voiceIndex":285,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、今後、道路整備をしていく中で、街路樹に対してどういう考え方でやっていくのか、いろいろ問題点はあるし、ただ、緑化対策なんかもありますし、地域の皆様方の要望もあるかと思うんですけれども、今後どういう形で道路事業を進めていくのかということを聞きたいと思います。それのお考えを、もう一度聞きます。避難所の件ですが、広域避難場所は変更するんですか。その辺のことを教えてください。","respondent":"藤田水とみどりの課長、原高齢者福祉課長、中山防災課長、武藤都市整備下水道課長、品川防災整備担当課長","answer":"これから樹種を選ぶときには、そういった観点も考慮しながら、品川区らしい樹種を選んでいきながら、維持管理についても。もう一つ、おたがいさま運動ということで、一つは、地域の方にもわかりやすい標語を区民から募集をさせていただいて、その標語をもとに。それらの結果を見据えながら、広域避難場所の変更といっても、今度は代替地が必要になってまいりますので、その辺も含めまして。","voiceIndex":290,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"おたがいさま運動、これは非常に大切なことだと思います。ですから、そこを東京都、これから動きがどんどんいろいろ出てくるかと思いますので、それをなるべく皆さんに伝えられるような形をとって、せっかくハザードマップ、それから具体的な行動について、これから平成２４年度はしっかりと取り組みをされると思いますので、それにあわせて説明等々をしていただきたいと考えています。","respondent":"柏原住宅担当課長","answer":"納付促進委託です。こちらのほうは、滞納されて退去されてしまった古い債権について、なかなか職員等々では回収が難しいということで、弁護士に委託をしまして、その分を回収するという委託です。","voiceIndex":296,"id":"exchange-124"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは、都市計画費３１３ページ、やさしいまちづくり推進費と、道路橋梁費、道路維持費の２９７ページ、街路灯建替事業の照明灯明るさ検証について、伺います。先ほど、木村委員から点字ブロックのお話がありましたので、それに関連して１点。こちらのほうの検討は、全然進んでいないのか、どうなのか、お伺いをいたします。","respondent":"山崎マスタープラン担当課長","answer":"まだ、はっきり設置ということは決まっておりませんけれども、区役所通り側のサンピア商店街から社会福祉協議会側、反対側に向かっての横断歩道に、設置前提で検討させていただいているというような状況です。","voiceIndex":299,"id":"exchange-125"},{"speaker":"井上委員","kind":"質問・要望","question":"やさしいまちづくりなんですけれども、推進協議会については、歳入の款でもお伺いいたしましたけれども、この協議会の設置要綱では、メンバーは任期が２年ということで、補欠の委員の任期は前任者の残任期間とするということで、私は、この要綱、再任に触れていないということで大変評価をしています。実際に２年任期で要綱どおり適切に行われているかどうか、伺います。","respondent":"山崎マスタープラン担当課長","answer":"やさしいまちづくり推進計画の進捗状況等々をお図りする推進協議会の構成のお尋ねです。推進協議会につきましては、現員４４名の構成ということで、住民団体関係者としまして、ふれあいサポート活動会議の代表、各地域というようなことで選出をされています。","voiceIndex":301,"id":"exchange-126"},{"speaker":"井上委員","kind":"提案","question":"その構成を見ると、地域の充て職とか、関係機関の充て職、福祉関係の代表というようなことになっているので、委員の選任には、区長が委嘱、または任命するというふうにありますけれども、やさしいまちづくりを推進するということで、この場合には、４５人の委員がいて、年１回しか行われていないということなんですが、ぜひ、この協議会で推進にもう少し力を入れていただきたいという要望があります。","respondent":"山崎マスタープラン担当課長","answer":"委員のご提案につきましては、広く、そうしたおたがいさまの意識を啓発するような運動の中に、より多くの区民の皆様の多様な意見を聞かせていただくような場を、というような趣旨ですので、そうしたことを勘案して、いろいろ検討、研究してまいりたいと考えております。","voiceIndex":303,"id":"exchange-127"},{"speaker":"井上委員","kind":"意見","question":"職員はそこに一人だけついて、声を聞く。そういうことこそ、コンサルタントがいても構わないけれども、職員の方たちがもっと積極的にかかわる必要があると思います。平成２２、２３年、職員研修をこの中からされているということでしたけれども、この計画については、どうもやり方がちょっと違うのではないかと思っていますが、その辺を、もう改善する余地があると思いますが、課題はありますか。","respondent":"山崎マスタープラン担当課長","answer":"そうしたところ、もうひと工夫、高齢福祉のソフトの部分とさらなる連携をしながら、本件につきまして、進めてまいりたいと考えています。","voiceIndex":305,"id":"exchange-128"},{"speaker":"井上委員","kind":"質問","question":"照明灯明るさ検証なんですけれども、プレス発表の資料では、８４万円で、地域住民にも参加してもらうとなっていますが、実際にどのように地域住民が参加をして、この検証を行うのか、具体的に教えてください。","respondent":"稲田道路公園課長","answer":"来年度、人感センサー付街路灯の検証等を、この明るさ検証で、ある一部のエリアを選びまして、地域住民の方に現状のまちの夜の様子を見ていただいて、どれぐらいの明るさ、明るすぎるのか、それともちょうどいいのか、そういうところを住民の皆さんと一緒に考えて。","voiceIndex":307,"id":"exchange-129"},{"speaker":"金野委員","kind":"質問・要望","question":"私からは、２９９ページの道路新設改良費の補助２０５号線整備、二つ目には、３２９ページの区営住宅管理費、この二つをお伺いいたします。先ほどのご答弁によりますと、設計まではいっていますけれども、協議、決定には、まだ時間がかかるというか、なかなか進まないというようなご答弁だったんですけれども、進まない原因というのでしょうか、何か壁があるのですか、そこら辺を教えてください。","respondent":"武藤都市整備下水道課長","answer":"ただし、信号機をどこに新規でつけるかという内容につきましては、まだ警視庁のほうで、来年度に入ってから最終的に決定するということで、何かハードルがあるというわけではなくて、向うの検討段階として、まだ明らかになっている段階ではないというふうな状況です。","voiceIndex":310,"id":"exchange-130"},{"speaker":"金野委員","kind":"質問・要望","question":"なかなか難しいというご答弁、ちょっと残念なご答弁なんですが、実は、過去に２００６年の決算特別委員会でも、実はうちの会派の先輩議員が同じような質問をしていて、今後、つくところはありますかという質問に対しては、難しいというご答弁だったんです。これはどういうふうに理解をすればいいんでしょうか。なので、ほかのところも何とか頑張っていただきたいという思いなんですが、いかがでしょうか。","respondent":"柏原住宅担当課長","answer":"確かに、今申し上げました難しいというのは、耐震化工事の３棟につきましては、まだ設計をやってございませんので、その中でどうなるかというのは、詳細に確認しているというものです。","voiceIndex":314,"id":"exchange-131"},{"speaker":"金野委員","kind":"質問・要望","question":"よくわかりました。設置をしていただきたいという思いで、これは確認をしながら、要望するということで、今回、質問を挙げさせていただいているんです。当然、設計をしなければわからないというところですけれども、となると、例えば二葉一丁目では、設計が行われて、今年度、耐震化工事が行われましたけれども、やはり設置が不可能だというところでしたけれども、これは何が原因だったのでしょうか。","respondent":"柏原住宅担当課長","answer":"ただ、結果的には、建築基準法の日影の規制等々で、つけられないということが最終的に判明したといいますか、そこの部分が一番のネックだったというところで、つけられないという判断ということで、つけなかったです。","voiceIndex":316,"id":"exchange-132"},{"speaker":"金野委員","kind":"質問","question":"日影の問題だということで、では、いろいろな壁がある中で、まだ設計がされていない住宅も含めて、できるかできないか、今後、わかるということですけれども、区営住宅の、いわゆる公共住宅の高齢者対策、バリアフリーは、今後、区として、どのように考えていこうと、どういう対策をとっていこうとお考えでしょうか。","respondent":"柏原住宅担当課長","answer":"区営住宅には、区営住宅の中の住み替え制度というのを持ってございまして、例えば、足腰がちょっと弱くなって不自由になった方で、高い階にいる方が下の階に移りたいというようなときには、登録をいただいて、その住宅が空いた際にお移りいただくというような制度もありますので。","voiceIndex":318,"id":"exchange-133"},{"speaker":"金野委員","kind":"意見","question":"住み替えもあるということですけれども、それだけではなかなかできないという状況もあるのかなと思いますので、今後も研究していただいて、どうかこの対策をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":320,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"３１３ページ、まちづくりマスタープラン策定費、１,６０７万７,０００円。このほど、全体計画の骨子案が発表されましたけれども、今後の予定についてお聞きしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"来年度につきましては、品川区の５地区の地域特性に合わせましたよりきめの細かい、その地区に応じたまちづくりの基本方針を定めていくというようなスケジュールになっております。公表は、来年度の末というようなことで予定しているものです。","voiceIndex":322,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"スケジュールをお聞きいたしました。実は、木密地域不燃化１０年プロジェクトというのが、緊急的に入ってきました。当然、これを品川区が受けることによって、やはりまちづくりが変わってくると思うんですけれども、この辺の入れ込み方。品川区が手を挙げて、これからできるかどうかわかりませんけれども、その辺の考え方というものをお聞きしたいと思います。","respondent":"品川防災整備担当課長","answer":"今までの不燃化の助成に比べて、もう少しより充実した形でやっていこうというものですが、これがまず、先行としてモデル地区３地区を用意しております。品川区も、ぜひ、ここの３地区にエントリーされるように、今、いろいろ研究をしてやっている状況であります。","voiceIndex":324,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"先ほども、質問がありましたけれども、２９号線の問題。課長から、どうしても必要なんだという大変に力強い、延焼遮断帯についての２９号線のお話を伺いました。その中で、防災まちづくり、あるいは、都市基盤、すべての人にやさしい便利で安全な交通歩行環境の整備、都市計画道路の整備促進、優先整備路線と２９号線が入っています。２０年間検討をするつもりなんですか。いろいろ聞きたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"踏切を外す手法として、高架であるとか、アンダーも含めまして、より幅広く今後の検討をしてまいりたいという思いで、そうした表現にしたものですが、現在、戸越公園のまちづくり協議会に、区も出ておりまして、いろいろ検討する中では、全体として。","voiceIndex":326,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問・要望","question":"あそこがアンダーにできるわけないでしょう。だって、大崎高校のところまで高架になって、その先に踏切が六つ、もう第二京浜は上がっているんですよ。その間をアンダーにして、ジェットコースターじゃないですけど、そんな線路ができるわけない。こんな検討なんか無駄ですよ、高架に決まっている。当然、お話が入っていると思いますので、どのようなことでやるのか、ちょっと説明していただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"墨田区の事例につきましては、東京スカイツリーができまして、周辺の交通環境等々が大幅に変わるということがございまして、そうした状況をもとに、墨田区のほうが、区において連立事業を実施する、区施工の事業に踏み切ったというようなことで、話は伺っております。","voiceIndex":328,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"ですから、区施工でお金をかける。一方、戸越公園の場合はどうですかね。経済効果じゃないですよね。災害のときには、あそこは１kmぐらい遮断機が下り放しで上がらないんですよ。すぐそばに戸越公園周辺の避難所があって、そこに行けないじゃないですか。そのような研究会、当然ながら、東急も、品川区も参加しておりますけれども、この辺の地域の思いを、ひとつどうぞよろしくお願いします。","respondent":"松代都市計画課長","answer":"そのことがはっきりしたうえで、２９号線と鉄道の立体化というのが次に出てくる話だと考えています。","voiceIndex":330,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問・要望","question":"６月の選定に向けて眠れない夜が続きそうですけれども、先ほどの２９号線のことについて、今回は歯切れが悪かったですけれども、歯切れのいい答弁を、今度の質問のときには聞かせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":332,"id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"３０９ページの津波・高潮対策事業と、３２９ページの区営住宅、この２点、伺います。そのあたりのことについて、説明会を開くこと、区民意見を聞く場をたくさんつくっていただきたいということについてなんですが、ちょっと確認をさせていただきたいと思います。それから、改めて、区営住宅というのが何団地あって、住宅が何戸あるのか、教えてください。","respondent":"武藤都市整備下水道課長、柏原住宅担当課長","answer":"もう１点の液状化に絡みまして、浦安と八潮の比較ですけれども、湾岸の地域、同様の埋立てということで、比較的液状化しやすい地域ということで認識しております。今まで空き待ち募集ということで、待機者を募集といいますか、登録をして、空いたところをご案内するというものでしたけれども、今回からは、空いた住宅に対して募集をかけるということで、今回の１月募集では、空き住宅が４戸に対して。","voiceIndex":334,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"ほんとうに少ない状況です。１３団地、４３９戸があるということで、この間、私ども共産党では、区営住宅をつくってほしいという要望を、機会あるごとにしてまいりました。空き家になっている住宅がどういう種類の住宅で、どのぐらいあるのかという調査も、ぜひして、家賃補助も含めて、入れるような仕組みをしていただきたいと思っていますが、その点についての見解も伺います。","respondent":"中村建築課長、柏原住宅担当課長","answer":"前半のほうのご質問、建物の耐震関係ですが、品川清掃工場、その前のご質問は、東京電力火力発電所という認識で、お答えをいたします。それから中間に入っている不動産業界もいらっしゃいます。こういった方と、今、お話し合いをさせていただいているところでございまして、どういった形で有効活用ができるかというところを検討しています。","voiceIndex":337,"id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"そこに公営住宅の整備というのも入っておりまして、ちょっと紹介しますと、この緊急防災・減災事業債を活用した対象事業に認定されると、事業費の地方負担額の起債充当率が１００％になると、こういうことで、多分、担当の部課長は研究しておられると思いますけれども、公営住宅をつくらないではなくて、こういう使い勝手のいい制度ができたときに、ほんとうに飛びついて、つくっていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"私は、３２５ページ、建築物耐震化支援費と、３２３ページ、都市防災不燃化促進事業について、お聞きします。ところで、第一京浜、国道１５号についてお聞きしますが、この道路を含め、沿道付近は地盤が弱いと聞いております。そうすると、今現在、平成２４年度内にこの事業が執行される見通しがあるんでしょうか。現在もう、そういう計画が出ているんでしょうか。その２点についてお聞かせください。","respondent":"品川防災整備担当課長","answer":"実際の改修ですが、こちらは、平成２７年度まで予定しておりますので、まだ期間が十分にあるかと考えております。","voiceIndex":342,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"沿道の建物に。今回、平成２４年度に１０億円をそこに予算化するわけですよね。ところが、ここは、相当容積率が高い建物が建つわけですから、１年以内にこの予算が執行できるという見込みはかなり薄いと思うんです。それでも、平成２７年度まで持っていくというのはわかりますが、最初から１０億円という金額をぽんと出すのは、ちょっと不思議な気がするんですが、もう一度だけ、お聞かせください。","respondent":"品川防災整備担当課長","answer":"１０億円のほうなんですけれども、こちらは、耐震診断をやるだけでも、１棟当たり大体５００万円から１,０００万円前後かかります。そう考えてみると、１０億円という数字も、そんなに大きくないというふうに、私のほうは考えております。","voiceIndex":344,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問・要望","question":"少なくともここは関東ローム層ではないので、今、これだけの震度７という想定がある限り、ちょっとここはどうなのかなという心配がありますので、よろしくお願いいたします。特に木造住宅密集地域の不燃化を進め、不燃化率を高くして、木造住宅、密集地域を減らす対策をしますが、これは燃えにくい住宅、そして、延焼しにくい住宅に誘導するということでしょうか。お聞かせください。","respondent":"品川防災整備担当課長","answer":"これについては、委員おっしゃるとおり、まさに燃えないまちをつくるといっても、さすがにやはり難しいという点があります。燃えにくいまち、これからつくっていくということです。","voiceIndex":346,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"ところで、今、区内には、空き地ができますと、木造３階の建売住宅等が増えています。それも、隣接する建物と建物の間が４０cmから５０cmという間隔しかありません。敷地の境界線からではありません。これでは、もし火災が発生すれば、隣の住宅に延焼しやすいわけで、木造住宅密集地域を解消しようとする区の政策と相反するものではないかと思うんですが、どうなんでしょうか、お答えください。","respondent":"品川防災整備担当課長","answer":"木造住宅の密集地域の中で、地区計画というものを進めております。ここの中で、最低の土地の制限とか、そういったものをかけて、この辺の対応は行っている状況です。","voiceIndex":348,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"区で、一生懸命不燃化促進ということでやっているのは、もうわかります。ですが、逆に今度、規制のほうで、土地が空いたと、そうするともう完全に密集して、隣と隣が４０cmとか、そういう状態だったら、木造というのは燃えますよね。必ず。でも、やはり、中は木造ですから、その辺もし何か新しい方策、対策とかできましたら、よろしくお願いしたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-148"},{"speaker":"阿部委員","kind":"質問・要望","question":"私からは、３１９ページの都市開発費の主に大崎駅周辺地区、北品川五丁目第１地区などについて、お伺いします。これが１点です。それから、駅の入口が非常にわかりにくくて、ビルの中を抜けて行かないと入りにくいなどということもあり、あの辺を歩いていると、ほんとうに２週間にいっぺんぐらいのペースで、「駅までどうやって行くんですか」と聞かれます。ここまで、とりあえず、お願いします。","respondent":"山崎マスタープラン担当課長、三宅都市開発課長、久保田行財政改革担当課長","answer":"施設長として、児童・生徒の安全性の確保等々の必要性に応じて、再度、事業者に依頼をして、ＰＴＡ等を通じて、学校内部のほうで説明会を行うというような。まちづくり連絡会など、地元の開発者などが参加している会がございまして、そのところも、ハードからソフトに軸足を移しながら。御殿山小学校の既存校舎の跡地につきましては、新しい校舎、校庭等ができた後に、学校が移転しますので、その跡地につきましては。","voiceIndex":352,"id":"exchange-149"},{"speaker":"阿部委員","kind":"質問","question":"要綱に関してなんですけれども、それでは適切でないと言ったら言いすぎだと思いますけれども、要は、いろいろなところに判断が必要になると、その分だけ時間的に遅れて、トラブルのもとになってしまうから、最初からいかがですかということです。何も問題がなければ、こんなことは言わないので、再度、ご検討ください。私の質問は、敷地と、その隣の地区外の地域と一体的に整備を行うんですかということです。","respondent":"久保田行財政改革担当課長","answer":"先ほどもお答えしましたように、今、私どものほうで考えているのは、既存校舎のある場所を、あれが移転した後に、その跡地について活用を検討するですので、御殿山小学校ではないというところとは、現在のところでは別というふうに考えております。","voiceIndex":356,"id":"exchange-150"},{"speaker":"阿部委員","kind":"質問","question":"わかりました。敷地の部分です。五反田駅の駐輪場ですが、予定している台数、それから、五反田駅の駐輪場として、この先どの程度必要であるか、その適性な規模というのを考えていらしたら、教えてください。そういう意味では、少し福祉団体というのとは性格が違ったカテゴリになってきているのではないかと考えているんですけれども、その辺は、どのようにお考えでしょうか。","respondent":"藤木交通安全担当課長、榎本企画財政課長","answer":"今のところ、計画では、２００台程度増設を予定しております。適性規模ですが、私どもで年１回、放置自転車の台数を調査しておりまして、昨年は２０４台、一昨年は１８０台の放置自転車が、五反田周辺にございました。シルバー人材センターの費目の問題ですけれども、今回、就業支援ということで、サポしながわが就業センターとくっつくということが、まず一つあります。","voiceIndex":358,"id":"exchange-151"},{"speaker":"阿部委員","kind":"意見","question":"しながわ区民公園の駐車場のほうなんですけれども、要は、福祉団体だから区が貸し付けて、それでお仕事をしてもらうというくくりの中で、しながわ区民公園の駐車場の管理をしてもらっていると。もし、シルバー人材センターというものが福祉団体的色合いが減っているのであれば、ちょっとそれが当たらなくなるのではないかという疑問だったので、その辺のお考えをお聞かせください。","respondent":"井浦土木管理課長","answer":"シルバー人材センターにしながわ区民公園の駐車場を管理していただいているということの背景の説明としまして、高齢者雇用安定法に基づく指定団体であるということも踏まえまして、社会政策的な観点からお貸ししているです。","voiceIndex":361,"id":"exchange-152"},{"speaker":"阿部委員","kind":"質問","question":"了解いたしました。最後、時間がなくなってしまったので、１個だけ、先月の『ＡＥＲＡ』という雑誌で、危険な避難所という特集をしておりまして、その中で、品川区の避難所がほんとうに全滅状態といったらあれなんですけれども、その筆頭に戸越公園というのが出ておりまして、非常に何か怖いなという感じだったんです。多分、あの記事は読まれていらっしゃると思うので、反論があれば、教えてください。","respondent":"品川防災整備担当課長","answer":"反論というよりは、戸越公園付近は、大分、密集地域であることは確かだと思います。そういった意味でも、戸越公園周辺不燃化事業、それから防災生活圏事業を通じて、少しでも戸越公園が安全な避難場所となるように日々努力しているという状況です。","voiceIndex":363,"id":"exchange-153"},{"speaker":"若林委員","kind":"質問・要望","question":"３０９ページの河川管理費、３２１ページの下水道合流改善施設整備工事、時間があれば、３２８ページの住宅費です。河川管理費と下水道合流改善施設整備工事をまとめて伺います。その中で、東京都の委託金が２,９００万円余入っていますけれども、まず、都の委託金をどこに使うのかということを、一つお聞きしたいと思います。それから、特に目黒川についてお聞きいたします。","respondent":"藤田水とみどりの課長","answer":"その内訳といたしましては、清掃や汚泥の浚渫、それから、立会川等の護岸の補修等で使っているものです。","voiceIndex":366,"id":"exchange-154"},{"speaker":"若林委員","kind":"質問","question":"わかりにくい質問だったんでしょうか、すみません。目黒川については、一つは環境の面から、特に水質ということになりますか。二つ目には防災、三つ目ににぎわいという観点で、河川管理費とか、また、ページが違うところの下水道合流改善施設整備工事とか、こういうところで、大きな転換点にきているんだなと、いい方向にという意味で、そこで、全体像をちょっとお聞きしたいということです。","respondent":"藤田水とみどりの課長","answer":"防災の面では、防災船着場等のこと、それから、今回、予算のほうでもお出しをしておりますとおり、荷揚げ用のクレーン等を設置して、防災面でも、こういったことを活用していこうということで考えておりまして、これから目黒川については。","voiceIndex":368,"id":"exchange-155"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ、今後も、目黒川の活用を、よろしくお願いいたします。そんな中で、今、お話が出ましたのは、１月２５日に区長が都庁に伺って、ちょっとこれは担当の方に確認ですが、最後のほうに、今後も、「東京都と区が協力して抜本的な水質改善への取り組みを進めていくことを約束した」とあります。東京都のほうの認識というのは、同じなのかということの確認です。以上、何点かお聞きしました。","respondent":"藤田水とみどりの課長、三宅都市開発課長","answer":"これについては、そういったような事業者がいることを前提にしなければいけませんので、さまざま、これから調整を進めて、なるべく早い段階でこういった動きがとれればと考えています。３２１ページの下水道合流改善施設整備工事ですけれども、これは、北品川五丁目第１地区の再開発事業の費用を頂戴して、区のほうで整備するということになってあります。","voiceIndex":370,"id":"exchange-156"},{"speaker":"須藤委員","kind":"質問","question":"２年間見ていて、屋根がつかないので、４月に許可を取り消しますみたいな話があったんですけれども、ちょっと私の聞き方が違っているのかどうか。そこにバス停をつくりたいと東急がきたと、品川区は屋根をつくることを前提として許可をした。だけれども、２年間そのことが守られていない、ですから、４月になったら、そこを打ち切ると、そういう話になるんでしょうか。","respondent":"岩田都市環境事業部長","answer":"もう１バースは、実は、前々から、あそこで地元が祭日や休日にバス旅行をするときに、早朝にバスをとめていたということがありまして、地元要望もありましたので、それを正式に認めるわけにいかないので、一応、使わないバスバースということで、空間を設置していたものです。","voiceIndex":374,"id":"exchange-157"},{"speaker":"須藤委員","kind":"意見","question":"３２５ページの建築物耐震化支援、これは区側も言っているように、そうしてもらうのが一番いいんだという話なので、予算が１２億円ぐらいあるんですが、このことについて、もう一度ＰＲをしたり、もっと極端に言えば、区民の皆さんがいろいろな心配事で、じゃあ耐震化しようとかいう形できて、この予算以上になっても、それなりの補てんをしていきますという考え方があるかどうか、お聞かせください。","respondent":"稲田道路公園課長、品川防災整備担当課長","answer":"２９７ページ、道路擁壁安全点検委託につきましては、既に台帳等があるんですけれども、今回、もう一度点検してみようということでございまして、さらなるその先というのは、現在のところは、まだ予定しておりません。例えば、木造が予算を超えた場合でも、マンションのほうから持っていくというような形で、予算のほうは対応しているような状況です。","voiceIndex":376,"id":"exchange-158"},{"speaker":"須藤委員","kind":"質問","question":"去年の３月１１日のことがあったし、今、新聞とか報道で、首都直下型地震がくるという確率が非常に高まってきている。それから、今、３.１１のことで、東北のほうは、今、復興ということで、品川区の職員も現地に行ってもらって一生懸命頑張っています。私は、国全体でやろうということなので、品川区でもそういうパワーがある人がいれば、ぜひと思っていますが、いかがでしょうか。","respondent":"濱野区長","answer":"そしてまた、こういう派遣そのものは、宮古市のためでもありますけれども、一旦、私たち有事の際には、ボランティアなり、派遣を支援をしてくださる他の自治体の職員を、どのようにしたら受けとめることができるかということの訓練にもなると考えていますので。","voiceIndex":379,"id":"exchange-159"},{"speaker":"須藤委員","kind":"質問・要望","question":"万が一のときに、たまたまそれが防災訓練だからよかったけれども、ほんとうだったら、さあというときに使えなくなると思うので、何かあったときに点検をするというようなことは、今後、やっていただけますでしょうか、すべてについて。","respondent":"岩田都市環境事業部長","answer":"先ほどのは一つの例だと思うんですけれども、例えば同じようなもので、防火水槽は、東京消防庁が使っている４０ｔ以上は別にしまして、区は区民消火隊や町会で使う小さな防火水槽、これも何百カ所と持っておりますけれども、年に１回、水位の点検をしておりますので。","voiceIndex":381,"id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":117994,"voices":383}}]);
